function App() {
  const [route, setRoute] = useState(() => window.location.hash.replace('#/', '') || '')
  const [query, setQuery] = useState('')
  const [activeLens, setActiveLens] = useState('today')
  const [pendingGlobalSection, setPendingGlobalSection] = useState('')
  const [contactOpen, setContactOpen] = useState(false)
  const [groupOpen, setGroupOpen] = useState(false)
  const [contactBannerVisible, setContactBannerVisible] = useState(true)

  useEffect(() => {
    const onHashChange = () => {
      setRoute(window.location.hash.replace('#/', ''))
      setQuery('')
      window.scrollTo({ top: 0, left: 0 })
    }
    window.addEventListener('hashchange', onHashChange)
    return () => window.removeEventListener('hashchange', onHashChange)
  }, [])

  const routePath = route.split('?')[0]

  useEffect(() => {
    if (!pendingGlobalSection || routePath) return
    const frame = window.requestAnimationFrame(() => {
      document.getElementById(pendingGlobalSection)?.scrollIntoView({ behavior: 'smooth', block: 'start' })
      setPendingGlobalSection('')
    })
    return () => window.cancelAnimationFrame(frame)
  }, [activeLens, pendingGlobalSection, routePath])

  const requestedTopicId = routePath.startsWith('topic/') ? routePath.split('/')[1] : 'bazi'
  const topicId = TOPICS[requestedTopicId] ? requestedTopicId : 'bazi'
  const topic = TOPICS[topicId]
  const rawDetailId = routePath.startsWith(`topic/${topicId}/`) ? routePath.replace(`topic/${topicId}/`, '') : ''
  const detailId = topicId === 'liuyao'
    ? LIUYAO_ROUTE_ALIASES[rawDetailId] || rawDetailId
    : topicId === 'tarot'
      ? TAROT_ROUTE_ALIASES[rawDetailId] || rawDetailId
      : topicId === 'ziwei'
        ? ZIWEI_ROUTE_ALIASES[rawDetailId] || rawDetailId
        : topicId === 'taiyi'
          ? TAIYI_ROUTE_ALIASES[rawDetailId] || rawDetailId
          : topicId === 'mbti'
            ? PERSONALITY_ROUTE_ALIASES[rawDetailId] || rawDetailId
            : topicId === 'almanac'
              ? ALMANAC_ROUTE_ALIASES[rawDetailId] || rawDetailId
              : topicId === 'naming'
                ? NAMING_ROUTE_ALIASES[rawDetailId] || rawDetailId
            : rawDetailId
  const selectedCard = topic.cards.find((card) => card.id === detailId)
  const isTopic = routePath.startsWith('topic/')
  const filteredKnowledge = useMemo(() => {
    const needle = query.trim().toLowerCase()
    if (!needle) return topic.cards
    return topic.cards.filter((card) =>
      [card.title, card.latin, card.question, ...card.tags, ...(card.searchTerms || [])].join(' ').toLowerCase().includes(needle),
    )
  }, [query, topic])

  function openCard(id) {
    window.location.hash = `/topic/${topicId}/${id}`
  }

  function goGlobal() {
    setActiveLens('today')
    window.location.hash = '/'
  }

  function goGlobalSection(sectionId, lens) {
    if (lens) setActiveLens(lens)
    setPendingGlobalSection(sectionId)
    if (routePath) window.location.hash = '/'
  }

  function goTopic(nextTopicId) {
    window.location.hash = `/topic/${nextTopicId || (isTopic ? topicId : 'bazi')}`
  }

  return (
    <div className="app-shell">
      <Topbar query={query} setQuery={setQuery} mode={isTopic ? 'topic' : 'global'} topic={topic} goGlobal={goGlobal} goGlobalSection={goGlobalSection} goTopic={goTopic} openGroup={() => setGroupOpen(true)} />
      {contactBannerVisible && <ContactBanner openContact={() => setContactOpen(true)} dismiss={() => setContactBannerVisible(false)} />}
      {selectedCard ? (
        <DetailPage card={selectedCard} topic={topic} goHome={() => goTopic(topicId)} openCard={openCard} />
      ) : isTopic ? (
        <Overview topic={topic} cards={filteredKnowledge} openCard={openCard} query={query} goGlobal={goGlobal} />
      ) : (
        <GlobalMap activeLens={activeLens} setActiveLens={setActiveLens} />
      )}
      <ContactDock openContact={() => setContactOpen(true)} />
      {contactOpen && <ContactPanel close={() => setContactOpen(false)} />}
      {groupOpen && <GroupPanel close={() => setGroupOpen(false)} />}
    </div>
  )
}

