function BaziTopicDemonstration({ openCard }) {
  const [activeRow, setActiveRow] = useState('stems')
  const data = datasets.fourPillarsStructure
  const dayStem = data.fixed_example.find((item) => item.pillar === '日柱').stem
  const sample = data.fixed_example.map((item) => {
    const hidden = datasets.hiddenStems.records.find((record) => record.branch === item.branch)
    return {
      ...item,
      stemTenGod: datasets.stemRelations.ten_god_matrix[dayStem][item.stem],
      hidden: [hidden.main_stem, ...hidden.additional_stems].map((stem, index) => ({
        stem,
        kind: index === 0 ? '主气' : '兼藏',
        tenGod: datasets.stemRelations.ten_god_matrix[dayStem][stem],
      })),
    }
  })
  const rowDetails = {
    'ten-gods': { label: '十神', eyebrow: `以日干${dayStem}为基准`, description: '专业盘通常把十神排成一整行，方便横向比较四柱。它描述的是相对关系，不是每个字固定自带的名称。', node: 'stem-relations', nodeLabel: '天干与十神' },
    stems: { label: '天干', eyebrow: '八个字的上半层', description: '年、月、日、时四柱固定为四列；每柱上方的字是天干。日柱天干单独标为日主，作为十神比较的基准。', node: 'four-pillars-structure', nodeLabel: '四柱结构' },
    branches: { label: '地支', eyebrow: '八个字的下半层', description: '每柱下方的字是地支。先保持四列位置不动，再继续查看地支内部所藏与盘内关系。', node: 'four-pillars-structure', nodeLabel: '四柱结构' },
    hidden: { label: '藏干', eyebrow: '地支内的天干', description: '藏干另占一整行，主气在前、兼藏在后；这样可以直接对照它属于哪一柱，而不是把内容藏进弹窗。', node: 'hidden-stems', nodeLabel: '地支藏干' },
    relations: { label: '关系', eyebrow: '基础盘之后再读', description: '排盘产品通常把合、冲、刑、害放在基础四柱之外单列。固定例里只标出可由现有数据直接核对的辰戌冲。', node: 'branch-relations', nodeLabel: '地支关系' },
  }
  const current = rowDetails[activeRow]

  return (
    <section className="topic-demonstration" aria-labelledby="bazi-demo-title">
      <header className="topic-demo-heading">
        <div><p>固定案例 · 按常见专业盘式整理</p><h2 id="bazi-demo-title">先学会看盘面上的行与列</h2></div>
      </header>

      <div className="topic-demo-workbench">
        <div className="professional-chart" aria-label="固定八字盘面示例">
          <div className="chart-caption"><small>匿名固定例</small><strong>甲子 · 丙寅 · 戊辰 · 壬戌</strong><span>点击行名阅读</span></div>
          <div className="chart-grid chart-header-row">
            <span className="chart-corner">四柱</span>
            {sample.map((item) => <strong className={item.pillar === '日柱' ? 'day-column' : ''} key={item.pillar}>{item.pillar}{item.pillar === '日柱' && <small>日主所在</small>}</strong>)}
          </div>
          <div className={`chart-grid chart-data-row compact ${activeRow === 'ten-gods' ? 'active' : ''}`}>
            <button onClick={() => setActiveRow('ten-gods')}>十神</button>
            {sample.map((item) => <span key={item.pillar}>{item.pillar === '日柱' ? '日主' : item.stemTenGod}</span>)}
          </div>
          <div className={`chart-grid chart-data-row primary ${activeRow === 'stems' ? 'active' : ''}`}>
            <button onClick={() => setActiveRow('stems')}>天干</button>
            {sample.map((item) => <strong className={item.pillar === '日柱' ? 'day-column' : ''} key={item.pillar}>{item.stem}<small>{item.pillar === '日柱' ? '日主' : item.stemTenGod}</small></strong>)}
          </div>
          <div className={`chart-grid chart-data-row primary ${activeRow === 'branches' ? 'active' : ''}`}>
            <button onClick={() => setActiveRow('branches')}>地支</button>
            {sample.map((item) => <strong className={item.pillar === '日柱' ? 'day-column' : ''} key={item.pillar}>{item.branch}<small>支</small></strong>)}
          </div>
          <div className={`chart-grid chart-data-row hidden-row ${activeRow === 'hidden' ? 'active' : ''}`}>
            <button onClick={() => setActiveRow('hidden')}>藏干</button>
            {sample.map((item) => <span key={item.pillar}>{item.hidden.map((hidden) => <i key={hidden.stem}><b>{hidden.stem}</b><small>{hidden.tenGod}</small></i>)}</span>)}
          </div>
          <div className={`chart-grid chart-data-row relation-row ${activeRow === 'relations' ? 'active' : ''}`}>
            <button onClick={() => setActiveRow('relations')}>关系</button>
            <span /><span /><span className="relation-start">辰</span><span className="relation-end">戌<small>六冲</small></span>
          </div>
        </div>

        <aside className="topic-demo-reading">
          <small>{current.eyebrow}</small><h3>{current.label}</h3><p>{current.description}</p>
          <button onClick={() => openCard(current.node)}>具体规则：{current.nodeLabel}{ICONS.arrow}</button>
        </aside>
      </div>
    </section>
  )
}

function BaziIntroductionDetail({ openCard }) {
  const glossary = [
    ['四柱', '把出生年、月、日、时各写成一组干支。'],
    ['日干', '四柱里日柱的天干，后面很多关系都拿它当参照。'],
    ['月令', '不是公历月份，而是节气切分出来的节令月份。'],
    ['十神', '不是十个固定性格，而是别的天干相对日干的位置关系。'],
    ['用神', '不同书里可能在回答不同问题，不能默认只有一个意思。'],
  ]
  const boundaries = [
    '这里解释的是知识结构，不接收真人出生资料，也不替用户排盘。',
    '历史来源会保留复杂性，不把“李虚中三柱、徐子平补时柱”写成无争议定论。',
    '调候、格局、旺衰、用神、神煞分别放回各自节点，不合成一个万能总算法。',
  ]
  return (
    <section className="interactive-section bazi-introduction-detail">
      <header>
        <small>第一次进入八字</small>
        <h2>先把它理解成“一套把出生时间翻译成关系结构的语言”</h2>
        <p>古人先用天干地支记录时间。八字进一步把出生年、月、日、时写成四组干支，再以日干为参照，观察五行、阴阳、季节和各个干支之间怎样形成关系。后面不同传统发展出的旺衰、格局、调候、用神、神煞和大运，不是同一个按钮，而是围绕同一张结构的不同阅读框架。</p>
      </header>

      <div className="bazi-reading-river">
        {baziLearningStages.map((stage, index) => (
          <Fragment key={stage.id}>
            <article>
              <header><small>阶段 {index + 1} · {stage.label}</small><strong>{stage.note}</strong></header>
              <nav aria-label={`${stage.label}知识节点`}>
                {stage.cards.map((cardId) => {
                  const card = TOPICS.bazi.cards.find((item) => item.id === cardId)
                  return <button onClick={() => openCard(cardId)} key={cardId}>{card.title}<i aria-hidden="true">→</i></button>
                })}
              </nav>
            </article>
            {index < baziLearningStages.length - 1 && <i>→</i>}
          </Fragment>
        ))}
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>你正在看什么</span><h2>八字专题的十八个正式节点，分别在回答五类问题</h2></div>
        <div className="bazi-intro-categories">
          <article><small>对象从哪里来</small><strong>四柱、月令、藏干</strong><p>先把时间转换成可以进入阅读的干支结构。</p></article>
          <article><small>对象带什么属性</small><strong>阴阳、五行、节令</strong><p>同一个字进入不同季节与位置，状态会改变。</p></article>
          <article><small>对象怎样互相连接</small><strong>十神、地支关系、六十甲子、纳音</strong><p>八字不是看单个字，而是看它们之间的方向与排列。</p></article>
          <article><small>时间怎样继续推进</small><strong>十二长生、旺相休囚死、大运</strong><p>阅读不只看出生盘，还要看时令与后续阶段怎样进入。</p></article>
          <article><small>不同传统怎样组织判断</small><strong>旺衰、格局、调候、用神、神煞</strong><p>这些名称相互关联，但不是彼此替代的同义词。</p></article>
        </div>
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>历史线索</span><h2>目前更稳妥的说法是：干支历法更早，后来的命术阅读逐渐围绕它展开</h2></div>
        <div className="bazi-history-notes">
          <article><strong>更早的底座</strong><p>天干地支、节令和干支纪日先属于历法与时间记录系统，不是从八字开始才出现。</p></article>
          <article><strong>可见的唐宋线索</strong><p>唐代材料已经出现用出生干支和五行关系推人事的记录；现存《李虚中命书》的成书与流传层次较复杂，后半可见四柱法内容。</p></article>
          <article><strong>所以这里不直接下结论</strong><p>我们保留“李虚中”“子平体系”“后世整理”之间的历史复杂性，不把它压成一句简单发明史。</p></article>
        </div>
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>第一次看到术语时</span><h2>先用白话抓住它在结构里的位置</h2></div>
        <div className="bazi-glossary-grid">
          {glossary.map(([term, note]) => <article key={term}><strong>{term}</strong><p>{note}</p></article>)}
        </div>
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>主动边界</span><h2>这张地图帮助理解，但不替用户做判断</h2></div>
        <div className="bazi-boundary-list">{boundaries.map((item) => <p key={item}>{item}</p>)}</div>
      </div>
    </section>
  )
}

function LiuyaoTopicDemonstration({ openCard }) {
  const [activeLayer, setActiveLayer] = useState('overview')
  const example = liuyaoDatasets.movingLinesChange.fixed_example
  const inner = liuyaoDatasets.najiaAssembly.trigrams.find((item) => item.name === '坎')
  const outer = liuyaoDatasets.najiaAssembly.trigrams.find((item) => item.name === '离')
  const changedInner = liuyaoDatasets.najiaAssembly.trigrams.find((item) => item.name === '坤')
  const branchElements = { 子: '水', 丑: '土', 寅: '木', 卯: '木', 辰: '土', 巳: '火', 午: '火', 未: '土', 申: '金', 酉: '金', 戌: '土', 亥: '水' }
  const fireRelatives = { 木: '父母', 火: '兄弟', 土: '子孙', 金: '妻财', 水: '官鬼' }
  const rolePattern = liuyaoDatasets.selfResponse.patterns.find((item) => item.id === 'all_different')
  const contextFor = (branch) => liuyaoDatasets.monthDayContext.fixed_samples.find((item) => item.branch === branch)
  const spiritGroup = liuyaoDatasets.sixSpiritsSequence.stem_groups.find((item) => item.stems.includes('甲'))
  const stateLabels = { 'young-yang': '少阳', 'young-yin': '少阴', 'old-yang': '老阳 → 变阴', 'old-yin': '老阴 → 变阳' }
  const voidBranches = ['午', '未']
  const layers = [
    { id: 'overview', label: '整盘', note: '七列排盘表', node: 'hexagram-body', nodeLabel: '六爻卦体', description: '参照网页端 liuyao-tool：六爻从上到下排成六行，每行依次读爻位、六亲、六神、卦画、纳甲、五行和状态。' },
    { id: 'structure', label: '卦画', note: '先辨六个位置', node: 'hexagram-body', nodeLabel: '六爻卦体', description: '六条爻从初爻向上组成卦体，盘面则从上爻向下显示。下三爻为坎，上三爻为离。' },
    { id: 'roles', label: '世应', note: '标出相对位置', node: 'self-response', nodeLabel: '世应', description: '固定例中内外三组对应爻阴阳全异，因此世落三爻，应落上爻；两者始终上下相隔三位。' },
    { id: 'relatives', label: '六亲·纳甲', note: '把关系装进爻位', node: 'najia-assembly', nodeLabel: '纳甲', description: '坎、离在内外位置各有固定干支；再以未济所属离宫的火为基准，换算每爻的六亲名称。' },
    { id: 'spirits', label: '六神', note: '甲日从青龙起初爻', node: 'six-spirits-sequence', nodeLabel: '六神', description: '为补齐网页端盘式，固定例将原有申日明确为甲申日。甲日初爻起青龙，再向上按固定次序排六神。' },
    { id: 'change', label: '状态', note: '老阳才发生翻转', node: 'moving-lines-change', nodeLabel: '动爻与变卦', description: '二爻是老阳，在卦画旁标为○，状态列写作“老阳→变阴”；六爻翻转后，火水未济变为火地晋。' },
    { id: 'context', label: '月日', note: '时间从盘外进入', node: 'month-day-context', nodeLabel: '时间来源', description: '固定盘面先展示寅月、申日怎样从盘外连接每一爻；完整时间来源页再补太岁的年度范围门，不把年、月、日等权套用。' },
  ]
  const current = layers.find((item) => item.id === activeLayer)
  const baseBranches = [...inner.inner_branches, ...outer.outer_branches]
  const baseStems = [inner.inner_stem, inner.inner_stem, inner.inner_stem, outer.outer_stem, outer.outer_stem, outer.outer_stem]
  const lines = example.positions.map((position) => {
    const branch = baseBranches[position.index - 1]
    const changedBranch = position.index <= 3 ? changedInner.inner_branches[position.index - 1] : branch
    const changedStem = position.index <= 3 ? changedInner.inner_stem : outer.outer_stem
    return {
      ...position,
      branch,
      stem: baseStems[position.index - 1],
      relative: fireRelatives[branchElements[branch]],
      changedBranch,
      changedStem,
      changedRelative: fireRelatives[branchElements[changedBranch]],
      spirit: spiritGroup.lines[position.index - 1],
      role: position.index === rolePattern.shi ? '世' : position.index === rolePattern.ying ? '应' : '',
      context: contextFor(branch),
      moving: example.moving_positions.includes(position.index),
    }
  }).reverse()

  return (
    <section className="topic-demonstration liuyao-demonstration" aria-labelledby="liuyao-demo-title">
      <header className="topic-demo-heading">
        <div><p>固定案例 · 参照网页端开源排盘</p><h2 id="liuyao-demo-title">从七个字段，看懂一张六爻盘</h2></div>
      </header>

      <div className="liuyao-ledger-workbench web-plate-workbench">
        <div className={`web-plate layer-${activeLayer}`}>
          <nav className="plate-reading-guide" aria-label="选择要观察的盘面信息">
            <span>固定卦例</span>{layers.map((layer) => <button className={activeLayer === layer.id ? 'active' : ''} onClick={() => setActiveLayer(layer.id)} aria-pressed={activeLayer === layer.id} key={layer.id}>{layer.label}</button>)}
          </nav>
          <div className="web-plate-scroll">
            <table>
              <thead><tr><th>爻位</th><th>六亲</th><th>六神</th><th>卦画</th><th>纳甲</th><th>五行</th><th>状态</th></tr></thead>
              <tbody>{lines.map((line) => (
                <tr className={`${line.moving ? 'moving' : ''} ${line.role ? 'has-role' : ''} ${line.context ? 'has-context' : ''}`} key={line.index}>
                  <td>{line.index}爻</td><td>{line.relative}</td><td>{line.spirit}</td>
                  <td className="web-line-graphic"><span className={`web-yao ${line.base}`}><i /><i /></span><b>{line.moving ? '○' : ''}</b></td>
                  <td><span>{line.stem}{line.branch}</span>{line.role && <em>{line.role}</em>}{voidBranches.includes(line.branch) && <em className="void">空</em>}</td>
                  <td>{branchElements[line.branch]}</td><td><span>{stateLabels[line.state]}</span>{line.context && <small>{[...line.context.month_relations, ...line.context.day_relations].join(' · ')}</small>}</td>
                </tr>
              ))}</tbody>
            </table>
          </div>
          <div className="web-gua-summary">
            <p>本卦：<strong>{example.base_name}</strong><i>→</i>变卦：<strong>{example.changed_name}</strong></p>
            <p>离宫 · 三世卦 <small>本宫五行：火</small></p>
            <p>下卦：<strong>☵ 坎</strong><i>·</i>上卦：<strong>☲ 离</strong></p>
            <p>月建：<strong>寅</strong><i>·</i>日柱：<strong>甲申</strong><i>·</i>旬空：午、未</p>
          </div>
        </div>

        <aside className="topic-demo-reading liuyao-reading">
          <div><small>{current.note}</small><h3>{current.label}</h3></div><p>{current.description}</p>
          <button onClick={() => openCard(current.node)}>具体规则：{current.nodeLabel}{ICONS.arrow}</button>
        </aside>
      </div>
    </section>
  )
}

function KnowledgeCard({ card, topicId, index, onOpen }) {
  return (
    <article className="knowledge-card" tabIndex="0" onClick={onOpen} onKeyDown={(event) => event.key === 'Enter' && onOpen()}>
      <div className="card-topline">
        <span>{card.group}</span>
        <small>{card.count}</small>
      </div>
      <h3>{card.title} {topicId !== 'mbti' && <em>{card.latin}</em>}</h3>
      <blockquote>{card.question}</blockquote>
      <CardVisual id={card.id} topicId={topicId} card={card} />
      <div className="card-footer">
        <div>{card.tags.map((tag) => <span key={tag}>{tag}</span>)}</div>
        <button aria-label={`打开${card.title}`}>{ICONS.arrow}</button>
      </div>
      <span className="card-index">{String(index + 1).padStart(2, '0')}</span>
    </article>
  )
}

