function XiaoliurenCastingDetail() {
  const data = xiaoliurenDatasets.monthDayHourCasting
  const replay = xiaoliurenDatasets.fixedInputCastingReplay.replay
  const [activeId, setActiveId] = useState('month')
  const activeIndex = data.steps.findIndex((step) => step.id === activeId)
  const step = data.steps[activeIndex]
  const result = replay[activeIndex]
  return <section className="interactive-section xiaoliuren-casting-detail">
    <div className="interactive-heading"><span>固定字段 · 逐步累计</span><h2>月、日、时不是三个独立答案，而是三次接续移动</h2></div>
    <div className="xiaoliuren-fixed-input"><small>本页固定输入</small><span><b>月</b>五月</span><span><b>日</b>二十三</span><span><b>时</b>戌 · 序数11</span><em>不读取今天</em></div>
    <nav className="xiaoliuren-step-tabs" aria-label="选择起课步骤">{data.steps.map((item, index) => <button className={item.id === activeId ? 'active' : ''} onClick={() => setActiveId(item.id)} aria-pressed={item.id === activeId} key={item.id}><i>{index + 1}</i><strong>{item.label}</strong><small>{item.plain_language}</small></button>)}</nav>
    <div className="xiaoliuren-formula-stage"><article><small>{step.label} · 零基公式</small><code>{step.zero_based_formula}</code><p>{step.plain_language}</p><span>累计第 {result.one_based_cumulative_position} 位</span><strong>{result.palace}</strong></article><XiaoliurenPalaceCycle activeName={result.palace} /></div>
    <div className="knowledge-block xiaoliuren-input-chain"><div className="interactive-heading"><span>输入依赖</span><h2>每一步比前一步多接入一个字段</h2></div><div>{data.input_fields.map((field, index) => <Fragment key={field.id}><article><small>步骤 {index + 1}</small><strong>{field.label}</strong><span>{field.range}</span></article>{index < data.input_fields.length - 1 && <i>＋</i>}</Fragment>)}</div></div>
    <XiaoliurenBoundaryNote />
  </section>
}

