function QimenPalaceGrid({ values, detailed = false }) {
  const coordinate = qimenDatasets.ninePalaceCoordinate
  const byNumber = Object.fromEntries(coordinate.palaces.map((item) => [item.number, item]))
  return <div className={`qimen-palace-grid ${detailed ? 'detailed' : ''}`}>{coordinate.layout.flat().map((number) => {
    const palace = byNumber[number]
    return <article className={number === 5 ? 'center' : ''} key={number}><small>{number} · {palace.direction}</small><strong>{values?.[number - 1] || palace.trigram || '中'}</strong>{detailed && <span>{palace.name} · {palace.element}</span>}</article>
  })}</div>
}

function QimenCardPreview({ id }) {
  if (id === 'introduction-reading-map') return <div className="card-visual qimen-intro-preview"><strong>九宫</strong><i>＋</i><div>{['地盘','天盘','人盘','神盘'].map((item) => <span key={item}>{item}</span>)}</div></div>
  if (id === 'nine-palace-coordinate') return <div className="card-visual qimen-grid-preview"><QimenPalaceGrid /></div>
  if (id === 'earth-branch-palace-map') {
    const values = Array.from({length: 9}, (_, index) => qimenDatasets.earthBranchPalaceMap.palace_groups.find((item) => item.palace === index + 1)?.branches.join('') || '')
    return <div className="card-visual qimen-grid-preview"><small className="qimen-preview-label">十二支 · 中五无支</small><QimenPalaceGrid values={values} /></div>
  }
  if (id === 'three-wonders-six-instruments') return <div className="card-visual qimen-sequence-preview"><div><small>六仪</small>{['戊','己','庚','辛','壬','癸'].map((item) => <b key={item}>{item}</b>)}</div><div><small>三奇</small>{['丁','丙','乙'].map((item) => <b key={item}>{item}</b>)}</div></div>
  if (id === 'eighteen-earth-plate-layouts') return <div className="card-visual qimen-grid-preview"><small className="qimen-preview-label">阳遁一局 · 固定表</small><QimenPalaceGrid values={qimenDatasets.eighteenEarthPlateLayouts.layouts['阳遁']['1']} /></div>
  if (id === 'four-plate-assembly') return <div className="card-visual qimen-layer-preview">{qimenDatasets.fourPlateAssembly.layers.map((item) => <span key={item.name}><small>{item.order}</small><strong>{item.name}</strong><i>{item.objects.join(' · ')}</i></span>)}</div>
  if (id === 'yin-yang-dun-solar-term-ranges') return <div className="card-visual qimen-range-preview">{qimenDatasets.yinYangDunSolarTermRanges.ranges.map((item) => <span key={item.id}><small>{item.start} → {item.end}</small><strong>{item.label}</strong><i>{item.terms.length} 节气</i></span>)}</div>
  if (id === 'solar-term-three-yuan-ju-table') return <div className="card-visual qimen-yuan-preview"><small>冬至</small>{['上元 1','中元 7','下元 4'].map((item) => <span key={item}>{item}</span>)}</div>
  if (id === 'ju-method-variants') return <div className="card-visual qimen-ju-variants-preview">{qimenDatasets.juMethodVariants.methods.map((item) => <span key={item.id}><strong>{item.label}</strong><i></i><small>{item.inputs?.join('＋') || '节气／符头'}</small></span>)}</div>
  if (id === 'duty-star-duty-door') return <div className="card-visual qimen-duty-preview"><span><small>旬首</small><strong>甲寅遁癸</strong></span><i>→</i><span><small>值符星</small><strong>天蓬</strong></span><i>＋</i><span><small>值使门</small><strong>休门</strong></span></div>
  if (id === 'plate-style-variants') return <div className="card-visual qimen-plate-style-preview">{qimenDatasets.plateStyleVariants.styles.map((item) => <section key={item.id}><strong>{item.label}</strong><div>{Object.keys(item.objects || {}).map((layer) => <span key={layer}>{({stars:'星',doors:'门',deities:'神',stems:'干'})[layer]}</span>)}</div></section>)}</div>
  if (id === 'xun-void-palaces') return <div className="card-visual qimen-xun-void-preview">{qimenDatasets.xunVoidPalaces.rows.slice(0, 4).map((item) => <span key={item.xun}><small>{item.xun}</small><strong>{item.empty_branches.join(' · ')}</strong><i>→</i><b>{[...new Set(item.palaces)].join('／')}宫</b></span>)}</div>
  if (id === 'time-branch-horse-star') return <div className="card-visual qimen-horse-preview"><strong>驿马</strong>{qimenDatasets.timeBranchHorseStar.groups.map((item) => <span key={item.horse}><small>{item.branches.join('')}</small><b>{item.horse}</b><i>{item.palace_name}</i></span>)}</div>
  if (id === 'stem-tomb-entry') return <div className="card-visual qimen-tomb-preview">{qimenDatasets.stemTombEntry.implementation_table.filter((item) => ['乙','丁','癸'].includes(item.stem)).map((item) => <Fragment key={item.stem}><span><small>{item.group}</small><strong>{item.stem}</strong></span><i>入墓</i><span><strong>{item.tomb_branch}</strong><small>{item.palaces.join('／')}宫</small></span></Fragment>)}</div>
  if (id === 'six-instrument-punishment') return <div className="card-visual qimen-punishment-preview">{qimenDatasets.sixInstrumentPunishment.rows.slice(0, 4).map((item) => <span key={item.instrument}><small>{item.xun}</small><strong>{item.instrument}</strong><i>刑</i><b>{item.target_palace}宫</b></span>)}</div>
  if (id === 'door-palace-overcoming') return <div className="card-visual qimen-relation-preview"><span><small>门迫</small><strong>门克宫</strong></span><i>≠</i><span><small>宫制</small><strong>宫克门</strong></span></div>
  if (id === 'seasonal-five-phase-states') return <div className="card-visual qimen-season-matrix-preview">{qimenDatasets.seasonalFivePhaseStates.season_matrix.map((item) => <span key={item.season}><small>{item.season}</small><b>{item.旺}<i>旺</i></b><b>{item.相}<i>相</i></b><b>{item.死}<i>死</i></b></span>)}</div>
  if (id === 'nine-star-palace-states') return <div className="card-visual qimen-star-relation-preview">{qimenDatasets.nineStarPalaceStates.fixed_star_examples.map((item) => <span key={item.state}><small>{item.star} → {item.palace}宫</small><strong>{item.formula}</strong><i>＝</i><b>{item.state}</b></span>)}</div>
  if (id === 'eight-door-seasonal-states') return <div className="card-visual qimen-door-season-preview">{qimenDatasets.eightDoorSeasonalStates.fixed_checks.slice(0, 4).map((item) => <span key={`${item.door}-${item.month_branch}`}><small>{item.month_branch}月</small><strong>{item.door}</strong><i>{item.element}</i><b>{item.state}</b></span>)}</div>
  if (id === 'five-not-meet-hour-variants') return <div className="card-visual qimen-relation-preview"><span><small>严格资料表</small><strong>10 组</strong></span><i>≠</i><span><small>当前实现覆盖</small><strong>20 组</strong></span></div>
  if (id === 'three-wonder-condition-patterns') return <div className="card-visual qimen-wonder-patterns-preview">{qimenDatasets.threeWonderConditionPatterns.patterns.map((item) => <span key={item.id}><small>{item.required_layers.join('＋')}</small><strong>{item.label}</strong><i>{item.moving_object} → {item.target}</i></span>)}</div>
  const data = qimenDatasetByCardId[id]
  const items = (data?.items || []).map((item) => typeof item === 'string' ? item : item.name)
  return <div className="card-visual qimen-object-preview">{items.map((item, index) => <span key={item}><small>{index + 1}</small><strong>{item}</strong></span>)}</div>
}

function QimenBoundaries({ items }) {
  return <div className="qimen-boundaries">{items.map((item) => <p key={item}>{item}</p>)}</div>
}

function QimenIntroductionDetail({ openCard }) {
  return <section className="interactive-section qimen-introduction-detail">
    <header><small>第一次进入奇门</small><h2>先把一张盘拆成“坐标、对象、移动、标记、强弱、条件”六个问题</h2><p>你不需要先背格局或断语。当前专题先回答：盘面在哪里、有哪些对象、怎样装配、状态标记由什么条件产生，以及月令、实际落宫和跨层同宫为什么不能混成一层。</p></header>
    <div className="qimen-reading-river">{qimenLearningStages.map((stage, index) => <Fragment key={stage.id}><article><header><small>阶段 {index + 1} · {stage.label}</small><strong>{stage.question}</strong><span>{stage.note}</span></header><nav aria-label={`${stage.label}知识节点`}>{stage.cards.map((cardId) => { const card = qimenCards.find((item) => item.id === cardId); return <button onClick={() => openCard(cardId)} key={cardId}>{card.title}<i aria-hidden="true">→</i></button> })}</nav></article>{index < qimenLearningStages.length - 1 && <i>→</i>}</Fragment>)}</div>
    <div className="qimen-guide-objects"><QimenPalaceGrid detailed /><section>{['地盘 · 三奇六仪','天盘 · 九星与天盘干','人盘 · 八门','神盘 · 八神／版本化神系'].map((item) => <span key={item}>{item}</span>)}</section></div>
    <QimenBoundaries items={['页面不读取系统时间，不替用户起局。','八门、九星、八神的象意与吉凶不进入阅读页面。','拆补、置闰、茅山与转盘、飞盘、鸣法都按具名版本并列，不设默认正统。']} />
  </section>
}

function QimenObjectTable({ data }) {
  const items = data.items || []
  return <div className="qimen-object-table">{items.map((raw, index) => {
    const item = typeof raw === 'string' ? { name: raw } : raw
    return <article key={item.name}><small>{String(index + 1).padStart(2, '0')}</small><strong>{item.name}</strong>{item.home_palace && <span>原始 {item.home_palace} 宫</span>}{item.element && <b>{item.element}</b>}{item.special && <p>{item.special}</p>}</article>
  })}</div>
}

function QimenNodeDetail({ id }) {
  const data = qimenDatasetByCardId[id]
  const [dun, setDun] = useState('阳遁')
  const [ju, setJu] = useState('1')
  const [qimenChoice, setQimenChoice] = useState('')
  useEffect(() => { setDun('阳遁'); setJu('1'); setQimenChoice('') }, [id])

  if (id === 'nine-palace-coordinate') return <section className="interactive-section qimen-node-detail"><div className="interactive-heading"><span>固定坐标</span><h2>宫号按洛书落位，不按一至九从左上顺读</h2></div><QimenPalaceGrid detailed /><div className="qimen-coordinate-ledger">{data.palaces.map((item) => <article key={item.number}><small>{item.direction}</small><strong>{item.name}</strong><span>{item.trigram || '无卦'} · {item.element}</span></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>

  if (id === 'three-wonders-six-instruments') return <section className="interactive-section qimen-node-detail"><div className="qimen-category-board">{data.categories.map((group) => <article key={group.id}><small>{group.items.length} 个对象</small><h3>{group.label}</h3><div>{group.items.map((item) => <b key={item}>{item}</b>)}</div><p>{group.role}</p></article>)}</div><div className="knowledge-block qimen-sequence-detail"><div className="interactive-heading"><span>地盘排布序列</span><h2>分类不决定排布先后</h2></div><div>{data.earth_plate_sequence.map((item, index) => <span key={item}><small>{index + 1}</small><strong>{item}</strong></span>)}</div><p>{data.sequence_note}</p></div><QimenBoundaries items={data.reading_boundaries} /></section>

  if (id === 'eighteen-earth-plate-layouts') {
    const values = data.layouts[dun][ju]
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-dun-selector">{Object.keys(data.layouts).map((item) => <button className={item === dun ? 'active' : ''} onClick={() => setDun(item)} key={item}>{item}<small>{data.directions.find((entry) => entry.label === item).movement}</small></button>)}</nav><nav className="qimen-ju-selector">{Object.keys(data.layouts[dun]).map((item) => <button className={item === ju ? 'active' : ''} onClick={() => setJu(item)} key={item}>{item}局</button>)}</nav><div className="qimen-layout-stage"><header><small>当前固定表</small><h2>{dun}{ju}局</h2><p>戊在 {values.indexOf('戊') + 1} 宫；宫号一至九与下方九宫视觉位置是两条坐标。</p></header><QimenPalaceGrid values={values} detailed /></div><div className="qimen-palace-row">{values.map((item, index) => <span key={index}><small>{index + 1}宫</small><strong>{item}</strong></span>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'four-plate-assembly') return <section className="interactive-section qimen-node-detail"><div className="qimen-assembly-river">{data.layers.map((layer, index) => <Fragment key={layer.name}><article><small>第 {layer.order} 层 · {layer.dependency}</small><h3>{layer.name}</h3><strong>{layer.objects.join(' · ')}</strong><p>{layer.question}</p></article>{index < data.layers.length - 1 && <i>↓</i>}</Fragment>)}</div><div className="knowledge-block qimen-version-table"><div className="interactive-heading"><span>不是一条唯一算法</span><h2>三个盘式先保留为实现版本</h2></div>{data.version_comparison.map((item) => <article key={item.style}><h3>{item.style}</h3><strong>{item.structure}</strong><p>{item.status}</p><small>{item.source}</small></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>

  if (id === 'yin-yang-dun-solar-term-ranges') {
    const range = data.ranges.find((item) => item.id === (qimenChoice || 'yang'))
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-big-selector">{data.ranges.map((item) => <button className={item.id === range.id ? 'active' : ''} onClick={() => setQimenChoice(item.id)} key={item.id}><small>{item.start} → {item.end}</small><strong>{item.label}</strong><span>{item.movement}</span></button>)}</nav><div className="qimen-term-range"><header><small>{range.terms.length} 个节气</small><h2>{range.label} · {range.start}起</h2></header><div>{range.terms.map((term, index) => <span key={term}><small>{index + 1}</small><strong>{term}</strong></span>)}</div></div><div className="qimen-chain">{data.boundary_chain.map((item, index) => <Fragment key={item}><span><small>{index + 1}</small>{item}</span>{index < data.boundary_chain.length - 1 && <i>→</i>}</Fragment>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'solar-term-three-yuan-ju-table') {
    const table = data.tables[dun]
    const selectedTerm = table.find((item) => item.term === qimenChoice) || table[0]
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-dun-selector">{Object.keys(data.tables).map((item) => <button className={item === dun ? 'active' : ''} onClick={() => { setDun(item); setQimenChoice('') }} key={item}>{item}<small>{data.tables[item].length}个节气</small></button>)}</nav><nav className="qimen-term-selector">{table.map((item) => <button className={item.term === selectedTerm.term ? 'active' : ''} onClick={() => setQimenChoice(item.term)} key={item.term}>{item.term}</button>)}</nav><div className="qimen-yuan-stage"><header><small>当前固定表</small><h2>{selectedTerm.term}</h2></header>{data.columns.map((column,index) => <article key={column}><small>{column}</small><strong>{dun}{selectedTerm.values[index]}局</strong></article>)}</div><div className="qimen-fixed-checks">{data.fixed_checks.map((item) => <article key={item.term}><small>{item.term} · {item.yuan}</small><strong>{item.result}</strong><p>{item.evidence}</p></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'ju-method-variants') {
    const method = data.methods.find((item) => item.id === (qimenChoice || 'chaibu'))
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-method-selector">{data.methods.map((item) => <button className={item.id === method.id ? 'active' : ''} onClick={() => setQimenChoice(item.id)} key={item.id}><strong>{item.label}</strong><small>{item.status}</small></button>)}</nav><div className="qimen-method-stage"><header><small>当前具名版本</small><h2>{method.label}</h2><span>{method.inputs.join(' ＋ ')}</span></header><article><small>怎样定元</small><p>{method.yuan_rule}</p><strong>{method.implementation_evidence}</strong></article></div><div className="qimen-futou-groups">{data.futou_groups.map((group) => <article key={group.yuan}><small>{group.branch_group} · {group.branches.join('')}</small><h3>{group.yuan}</h3><p>{group.heads.join(' · ')}</p></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'duty-star-duty-door') {
    const example = data.fixed_examples.find((item) => item.id === qimenChoice) || data.fixed_examples[0]
    return <section className="interactive-section qimen-node-detail"><div className="qimen-chain qimen-duty-chain">{data.role_chain.map((item, index) => <Fragment key={item.label}><span><small>{index + 1} · {item.label}</small>{item.result}</span>{index < data.role_chain.length - 1 && <i>→</i>}</Fragment>)}</div><div className="qimen-xun-map">{data.xun_head_instruments.map((item) => <span key={item.xun}><small>{item.xun}</small><strong>遁{item.instrument}</strong></span>)}</div><nav className="qimen-method-selector">{data.fixed_examples.map((item) => <button className={item.id === example.id ? 'active' : ''} onClick={() => setQimenChoice(item.id)} key={item.id}><strong>{item.label}</strong><small>{item.time}</small></button>)}</nav><div className="qimen-duty-stage"><header><small>{example.ju}</small><h2>{example.xun}遁{example.instrument}</h2></header><article><small>值符星</small><strong>{example.duty_star}</strong></article><article><small>值使门</small><strong>{example.duty_door}</strong></article></div><div className="qimen-name-boundaries">{data.name_boundaries.map((item) => <article key={item.term}><strong>{item.term}</strong><p>{item.identity}</p></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'plate-style-variants') {
    const style = data.styles.find((item) => item.id === (qimenChoice || 'rotating'))
    const snapshot = data.fixed_snapshots.find((item) => item.style === style.label)
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-method-selector">{data.styles.map((item) => <button className={item.id === style.id ? 'active' : ''} onClick={() => setQimenChoice(item.id)} key={item.id}><strong>{item.label}</strong><small>{item.status}</small></button>)}</nav><div className="qimen-style-stage"><header><small>{style.evidence}</small><h2>{style.label}</h2><p>{style.movement}</p></header><div>{Object.entries(style.objects).map(([key,value]) => <article key={key}><small>{{stars:'星',doors:'门',deities:'神',stems:'干'}[key]}</small><strong>{value}</strong></article>)}</div><footer><strong>中宫</strong>{style.center}<br /><strong>附加层</strong>{style.extra_layers.join(' · ')}</footer></div><div className="qimen-snapshot"><small>{snapshot.time} · 固定快照</small><strong>{snapshot.visible_center}</strong><p>{snapshot.notable}</p></div><div className="qimen-axis-list">{data.comparison_axes.map((item,index) => <span key={item}><small>{index+1}</small>{item}</span>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'xun-void-palaces') {
    const row = data.rows.find((item) => item.xun === qimenChoice) || data.rows[0]
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-term-selector qimen-xun-selector">{data.rows.map((item) => <button className={item.xun === row.xun ? 'active' : ''} onClick={() => setQimenChoice(item.xun)} key={item.xun}>{item.xun}<small>遁{item.instrument}</small></button>)}</nav><div className="qimen-state-stage"><header><small>当前时旬</small><h2>{row.xun}遁{row.instrument}</h2><p>{row.shape}</p></header><div className="qimen-state-equation"><span><small>两支空亡</small><strong>{row.empty_branches.join(' · ')}</strong></span><i>→</i><span><small>九宫落点</small><strong>{row.palaces.map((item) => `${item}宫`).join(' · ')}</strong></span></div></div><div className="qimen-fixed-checks">{data.fixed_checks.map((item) => <article key={item.time}><small>{item.time} · {item.time_xun}</small><strong>{item.result}</strong></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'time-branch-horse-star') {
    const branches = ['子','丑','寅','卯','辰','巳','午','未','申','酉','戌','亥']
    const requestedBranch = qimenChoice || '午'
    const group = data.groups.find((item) => item.branches.includes(requestedBranch)) || data.groups[0]
    const branch = group.branches.includes(requestedBranch) ? requestedBranch : group.branches[0]
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-term-selector qimen-branch-selector">{branches.map((item) => <button className={item === branch ? 'active' : ''} onClick={() => setQimenChoice(item)} key={item}>{item}时</button>)}</nav><div className="qimen-state-stage"><header><small>当前固定时支</small><h2>{branch}时</h2><p>归入 {group.branches.join(' · ')} 三合组</p></header><div className="qimen-state-equation"><span><small>取马支</small><strong>{group.horse}</strong></span><i>→</i><span><small>落宫</small><strong>{group.palace_name}</strong></span></div></div><div className="qimen-group-register">{data.groups.map((item) => <article className={item === group ? 'active' : ''} key={item.horse}><small>{item.branches.join(' · ')}</small><strong>马在{item.horse}</strong><span>{item.palace_name}</span></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'stem-tomb-entry') {
    const row = data.implementation_table.find((item) => item.stem === (qimenChoice || '乙')) || data.implementation_table[1]
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-term-selector qimen-stem-selector">{data.implementation_table.map((item) => <button className={item.stem === row.stem ? 'active' : ''} onClick={() => setQimenChoice(item.stem)} key={item.stem}>{item.stem}<small>{item.group}</small></button>)}</nav><div className="qimen-state-stage"><header><small>当前实现表</small><h2>{row.stem} · {row.group}</h2><p>天盘{row.stem}落到墓支所在宫时形成结构标记</p></header><div className="qimen-state-equation"><span><small>墓支</small><strong>{row.tomb_branch}</strong></span><i>→</i><span><small>实现落宫</small><strong>{row.palaces.map((item) => `${item}宫`).join(' · ')}</strong></span></div></div><div className="qimen-version-table qimen-variant-register">{data.variant_register.map((item) => <article key={item.version}><small>{item.version}</small><h3>{item.乙奇}</h3><p>{item.status}</p></article>)}</div><div className="qimen-fixed-checks">{data.fixed_checks.map((item) => <article key={item.time}><small>{item.time}</small><strong>{item.marks.join(' · ')}</strong></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'six-instrument-punishment') {
    const row = data.rows.find((item) => item.instrument === (qimenChoice || '戊')) || data.rows[0]
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-term-selector qimen-stem-selector">{data.rows.map((item) => <button className={item.instrument === row.instrument ? 'active' : ''} onClick={() => setQimenChoice(item.instrument)} key={item.instrument}>{item.instrument}<small>{item.xun}</small></button>)}</nav><div className="qimen-state-stage"><header><small>{row.xun}遁{row.instrument}</small><h2>{row.instrument}落{row.palace_name}</h2><p>{row.relation_type}</p></header><div className="qimen-state-equation"><span><small>地支关系</small><strong>{row.relation}</strong></span><i>→</i><span><small>状态</small><strong>六仪击刑</strong></span></div></div><div className="qimen-chain">{data.recognition_chain.map((item, index) => <Fragment key={item}><span><small>{index + 1}</small>{item}</span>{index < data.recognition_chain.length - 1 && <i>→</i>}</Fragment>)}</div><div className="qimen-unmarked"><small>没有列为击刑目标宫</small><strong>{data.unmarked_palaces.map((item) => `${item}宫`).join(' · ')}</strong></div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'door-palace-overcoming') {
    const direction = data.directions.find((item) => item.id === (qimenChoice || 'door_overcomes')) || data.directions[0]
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-big-selector qimen-relation-selector">{data.directions.map((item) => <button className={item.id === direction.id ? 'active' : ''} onClick={() => setQimenChoice(item.id)} key={item.id}><small>{item.formula}</small><strong>{item.label}</strong><span>13 组组合</span></button>)}</nav><div className="qimen-relation-stage"><header><small>当前克制方向</small><h2>{direction.label}</h2><p>{direction.formula}</p></header><div>{direction.pairs.map((item) => <article key={item.relation}><small>{item.relation}</small><strong>{item.doors.join(' · ')}</strong><span>落 {item.palaces.map((palace) => `${palace}宫`).join(' · ')}</span></article>)}</div></div><div className="qimen-door-elements">{data.door_elements.map((item) => <span key={item.element}><small>{item.element}</small><strong>{item.doors.join(' · ')}</strong></span>)}</div><div className="qimen-fixed-checks">{data.fixed_checks.map((item) => <article key={item.time}><small>{item.time} · {item.door}落{item.palace}宫</small><strong>{item.result}</strong></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'seasonal-five-phase-states') {
    const row = data.season_matrix.find((item) => item.season === (qimenChoice || '春')) || data.season_matrix[0]
    const branchGroup = data.month_branch_groups.find((item) => item.season === row.season)
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-term-selector qimen-strength-selector">{data.season_matrix.map((item) => <button className={item.season === row.season ? 'active' : ''} onClick={() => setQimenChoice(item.season)} key={item.season}>{item.season}<small>{data.month_branch_groups.find((group) => group.season === item.season).branches.join(' · ')}</small></button>)}</nav><div className="qimen-relation-stage"><header><small>{branchGroup.branches.join(' · ')}月 · {branchGroup.command_element}当令</small><h2>{row.season}季五行状态</h2><p>同一行里，每个五行只占一个状态位置。</p></header><div>{data.state_order.map((state) => <article key={state}><small>{state}</small><strong>{row[state]}</strong><span>{data.relation_guide.find((item) => item.state === state).relation}</span></article>)}</div></div><div className="qimen-fixed-checks">{data.fixed_checks.map((item) => <article key={`${item.month_branch}-${item.element}`}><small>{item.month_branch}月 · {item.season}</small><strong>{item.element} · {item.state}</strong></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'nine-star-palace-states') {
    const example = data.fixed_star_examples.find((item) => item.state === (qimenChoice || '旺')) || data.fixed_star_examples[0]
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-term-selector qimen-strength-selector">{data.fixed_star_examples.map((item) => <button className={item.state === example.state ? 'active' : ''} onClick={() => setQimenChoice(item.state)} key={item.state}>{item.state}<small>{item.palace_name}</small></button>)}</nav><div className="qimen-state-stage"><header><small>{data.viewpoint}</small><h2>{example.star}落{example.palace_name}</h2><p>{example.star_element}星遇{example.palace_element}宫</p></header><div className="qimen-state-equation"><span><small>五行方向</small><strong>{example.formula}</strong></span><i>→</i><span><small>落宫状态</small><strong>{example.state}</strong></span></div></div><div className="qimen-relation-stage qimen-rule-register"><header><small>五条关系同用一个观察方向</small><h2>九星为“我”</h2></header><div>{data.relation_rules.map((item) => <article key={item.state}><small>{item.state} · {item.source_wording}</small><strong>{item.formula}</strong></article>)}</div></div><div className="qimen-door-elements">{data.star_groups.map((item) => <span key={item.element}><small>{item.element}</small><strong>{item.stars.join(' · ')}</strong></span>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'eight-door-seasonal-states') {
    const seasonalBase = qimenDatasets.seasonalFivePhaseStates
    const branches = seasonalBase.month_branch_groups.flatMap((item) => item.branches)
    const branch = qimenChoice || '子'
    const seasonGroup = seasonalBase.month_branch_groups.find((item) => item.branches.includes(branch)) || seasonalBase.month_branch_groups[0]
    const row = seasonalBase.season_matrix.find((item) => item.season === seasonGroup.season)
    const stateForElement = (element) => seasonalBase.state_order.find((state) => row[state] === element)
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-term-selector qimen-branch-selector">{branches.map((item) => <button className={item === branch ? 'active' : ''} onClick={() => setQimenChoice(item)} key={item}>{item}月</button>)}</nav><div className="qimen-chain qimen-derived-chain">{data.derivation.map((item, index) => <Fragment key={item}><span><small>{index + 1}</small>{item}</span>{index < data.derivation.length - 1 && <i>→</i>}</Fragment>)}</div><div className="qimen-relation-stage"><header><small>固定月支 · {branch}月</small><h2>{seasonGroup.season}季八门状态</h2><p>先归入{seasonGroup.season}，再按每扇门的五行查表。</p></header><div>{data.door_groups.map((item) => { const state = stateForElement(item.element); return <article key={item.element}><small>{item.element} · {state}</small><strong>{item.doors.join(' · ')}</strong><span>{branch}月统一读取为{state}</span></article> })}</div></div><div className="qimen-fixed-checks">{data.fixed_checks.map((item) => <article key={`${item.door}-${item.month_branch}`}><small>{item.month_branch}月 · {item.season}</small><strong>{item.door} · {item.state}</strong><p>{item.element}门</p></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'earth-branch-palace-map') {
    const branch = qimenChoice || '子'
    const row = data.branch_to_palace.find((item) => item.branch === branch) || data.branch_to_palace[0]
    const values = Array.from({ length: 9 }, (_, index) => {
      const group = data.palace_groups.find((item) => item.palace === index + 1)
      return group ? group.branches.join(' · ') : '—'
    })
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-term-selector qimen-branch-selector">{data.branch_to_palace.map((item) => <button className={item.branch === row.branch ? 'active' : ''} onClick={() => setQimenChoice(item.branch)} key={item.branch}>{item.branch}<small>{item.direction}</small></button>)}</nav><div className="qimen-state-stage"><header><small>当前固定地支</small><h2>{row.branch} · {row.direction}</h2><p>{row.axis}位置；这里只查固定空间归属。</p></header><div className="qimen-state-equation"><span><small>十二地支</small><strong>{row.branch}</strong></span><i>→</i><span><small>九宫落点</small><strong>{row.palace_name}</strong></span></div></div><QimenPalaceGrid values={values} detailed /><div className="qimen-fixed-checks">{data.dependency_examples.map((item) => <article key={item.rule}><small>{item.rule} · {item.input}</small><strong>{item.lookup}</strong><p>{item.result}</p></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'five-not-meet-hour-variants') {
    const strict = data.strict_pairs.find((item) => item.day_stem === (qimenChoice || '甲')) || data.strict_pairs[0]
    const additional = data.implementation_variant.additional_opposite_polarity_pairs.find((item) => item.day_stem === strict.day_stem)
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-term-selector qimen-stem-selector">{data.strict_pairs.map((item) => <button className={item.day_stem === strict.day_stem ? 'active' : ''} onClick={() => setQimenChoice(item.day_stem)} key={item.day_stem}>{item.day_stem}<small>日干</small></button>)}</nav><div className="qimen-version-table qimen-variant-register"><article><small>来源严格表 · 10组</small><h3>{strict.day_stem}日 → {strict.hour_ganzhi}时</h3><p>{strict.relation}，并检查阴阳同类（{strict.polarity}）与完整时柱。</p></article><article><small>当前实现放宽 · {data.implementation_variant.pair_count}组干对</small><h3>{strict.day_stem}日 → {strict.hour_stem}或{additional.hour_stem}时干</h3><p>{data.implementation_variant.formula}；不检查阴阳同类，也不检查时支。</p></article></div><div className="qimen-fixed-checks">{data.fixed_comparisons.map((item) => <article key={`${item.day_stem}-${item.hour_stem}`}><small>{item.day_stem}日 · {item.hour_stem}时干</small><strong>严格表 {item.strict_table ? '命中' : '不命中'} ／ 实现 {item.implementation ? '命中' : '不命中'}</strong><p>{item.reason}</p></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  if (id === 'three-wonder-condition-patterns') {
    const pattern = data.patterns.find((item) => item.id === qimenChoice) || data.patterns[0]
    const example = data.fixed_examples.find((item) => item.matched === pattern.label)
    return <section className="interactive-section qimen-node-detail"><nav className="qimen-method-selector">{data.patterns.map((item) => <button className={item.id === pattern.id ? 'active' : ''} onClick={() => setQimenChoice(item.id)} key={item.id}><strong>{item.label}</strong><small>{item.required_layers.length}层对象</small></button>)}</nav><div className="qimen-state-stage"><header><small>{pattern.required_layers.join(' ＋ ')}</small><h2>{pattern.label}</h2><p>{pattern.condition}</p></header><div className="qimen-state-equation"><span><small>移动对象</small><strong>{pattern.moving_object}</strong></span><i>→</i><span><small>目标</small><strong>{pattern.target}</strong></span></div><footer>{pattern.excluded_result}</footer></div>{pattern.prerequisites && <div className="qimen-chain qimen-derived-chain">{pattern.prerequisites.map((item, index) => <Fragment key={item}><span><small>{index + 1}</small>{item}</span>{index < pattern.prerequisites.length - 1 && <i>＋</i>}</Fragment>)}</div>}{pattern.id === 'three_wonders_ascend_hall' && <div className="qimen-door-elements">{data.ascend_hall_pairs.map((item) => <span key={item.wonder}><small>{item.wonder}奇</small><strong>{item.palace_name}</strong></span>)}</div>}<div className="qimen-fixed-checks"><article><small>{example.label}</small><strong>{example.facts.join(' · ')}</strong><p>只识别：{example.matched}</p></article>{data.direction_comparison.map((item) => <article key={item.pattern}><small>{item.pattern}</small><strong>{item.subject}</strong><p>落到：{item.lands_on}</p></article>)}</div><QimenBoundaries items={data.reading_boundaries} /></section>
  }

  const sequence = data.rotation_order || data.eight_position_rotation || data.base_sequence
  const variants = data.center_variants || data.variant_register
  return <section className="interactive-section qimen-node-detail"><QimenObjectTable data={data} />{sequence && <div className="knowledge-block qimen-sequence-detail"><div className="interactive-heading"><span>当前基础序列</span><h2>对象身份与实际落宫仍需分开</h2></div><div>{sequence.map((item, index) => <span key={item}><small>{index + 1}</small><strong>{item}</strong></span>)}</div></div>}{variants && <div className="knowledge-block qimen-version-table"><div className="interactive-heading"><span>版本登记</span><h2>不同实现不压成一套答案</h2></div>{variants.map((item, index) => <article key={item.variant || item.source}><h3>{item.variant || item.source}</h3><strong>{item.handling}</strong>{item.examples && <p>{item.examples.join(' ／ ')}</p>}</article>)}</div>}<QimenBoundaries items={data.reading_boundaries} /></section>
}

