function TaiyiNodeDetail({ card }) {
  const [sectionId, setSectionId] = useState(card.sections[0].id)
  useEffect(() => setSectionId(card.sections[0].id), [card.id])
  const active = card.sections.find((item) => item.id === sectionId) || card.sections[0]

  return (
    <div className="taiyi-node-detail">
      {card.sections.length > 1 && (
        <nav className="taiyi-node-tabs" aria-label={`${card.title}内容分层`}>
          {card.sections.map((item, index) => (
            <button className={item.id === active.id ? 'active' : ''} onClick={() => setSectionId(item.id)} aria-pressed={item.id === active.id} key={item.id}>
              <i>{String(index + 1).padStart(2, '0')}</i><span><strong>{item.label}</strong><small>{item.note}</small></span>
            </button>
          ))}
        </nav>
      )}
      <TaiyiDetailPart id={active.id} />
    </div>
  )
}

