function calculateMajorStarAnchors(day, bureau) {
  let offset = 0
  while ((day + offset) % bureau !== 0) offset += 1
  const quotient = (day + offset) / bureau
  const baseIndex = (quotient - 1) % 12
  const ziweiIndex = ((baseIndex + (offset % 2 === 0 ? offset : -offset)) % 12 + 12) % 12
  const tianfuIndex = (12 - ziweiIndex) % 12
  return { offset, quotient, baseIndex, ziweiIndex, tianfuIndex }
}

