function TarotCombinationDetail() {
  const data = tarotDatasets.multiCardCombination
  const spreads = tarotDatasets.spreadStructures
  const deck = tarotDatasets.deckStructure
  const major = tarotDatasets.majorArcanaImages
  const minor = tarotDatasets.minorArcanaImages
  const [exampleId, setExampleId] = useState(data.examples[0].id)
  const [layerId, setLayerId] = useState(data.layers[0].id)
  const example = data.examples.find((item) => item.id === exampleId)
  const sourceExample = [spreads.fixed_example, spreads.fixed_mixed_example].find((item) => item.id === example.source_example)
  const positions = spreads.spreads.find((item) => item.id === sourceExample.spread_id).positions
  const cards = sourceExample.cards.map((item) => {
    if (!item.suit_id) {
      const card = major.cards.find((entry) => entry.number === item.card_number)
      return { ...item, name: card.name_zh, image: card.image, route: `/topic/tarot/major-arcana-images?card=${encodeURIComponent(card.number)}&mode=imagery`, position: positions[item.position_number - 1] }
    }
    const suit = minor.suits.find((entry) => entry.id === item.suit_id)
    const rank = minor.ranks.find((entry) => entry.id === item.rank_id)
    return { ...item, name: `${suit.name_zh}${rank.name_zh}`, image: `${suit.name_en}${rank.file_number}.png`, route: `/topic/tarot/minor-arcana-images?suit=${encodeURIComponent(suit.id)}&rank=${encodeURIComponent(rank.id)}&mode=imagery`, position: positions[item.position_number - 1] }
  })
  const layer = data.layers.find((item) => item.id === layerId)

  return <section className="interactive-section tarot-combination-detail">
    <div className="interactive-heading"><span>问题 · 牌阵 · 牌位 · 单牌 · 整组</span><h2>先固定五层结构，再看牌与牌的关系</h2></div>
    <nav className="tarot-combination-layers" aria-label="选择多牌组合层级">{data.layers.map((item) => <button className={item.id === layerId ? 'active' : ''} onClick={() => setLayerId(item.id)} aria-pressed={item.id === layerId} key={item.id}><i>{item.index}</i><strong>{item.label}</strong></button>)}</nav>
    <article className="tarot-combination-layer"><small>{layer.question}</small><p>{layer.note}</p></article>
    <div className="knowledge-block tarot-combination-examples"><div className="interactive-heading"><span>两组既有固定牌例</span><h2>切换牌组组成，五层结构保持不变</h2></div><nav aria-label="选择固定牌例">{data.examples.map((item) => <button className={item.id === exampleId ? 'active' : ''} onClick={() => setExampleId(item.id)} aria-pressed={item.id === exampleId} key={item.id}>{item.label}</button>)}</nav>
      <div className="tarot-combination-workbench"><section>{cards.map((item, index) => <Fragment key={`${item.position_number}-${item.name}`}><button onClick={() => { window.location.hash = `#${item.route}` }}><small>{item.position_number} · {item.position}</small><img className={item.orientation === 'reversed' ? 'reversed' : ''} src={`${deck.image_set.base_path}${item.image}`} alt={`${item.name}${item.orientation === 'reversed' ? '逆位' : '正位'}牌面`} loading="lazy" /><strong>{item.name}</strong><span>{item.orientation === 'reversed' ? '逆位' : '正位'}</span></button>{index < cards.length - 1 && <i>→</i>}</Fragment>)}</section><article><small>{example.question}</small><ul>{example.observations.map((item) => <li key={item}>{item}</li>)}</ul></article></div>
    </div>
    <div className="knowledge-block tarot-position-context"><div className="interactive-heading"><span>同一张牌 · 不同任务</span><h2>牌位先规定这张牌在整组里负责什么</h2></div><div>{data.same_card_positions.map((item) => <button onClick={() => { window.location.hash = `#${item.route}` }} key={item.position}><strong>{item.position}</strong><span>{item.role}</span><i>→</i></button>)}</div></div>
  </section>
}

