function TarotReviewDetail() {
  const data = tarotDatasets.readingReview
  const spreads = tarotDatasets.spreadStructures
  const deck = tarotDatasets.deckStructure
  const major = tarotDatasets.majorArcanaImages
  const minor = tarotDatasets.minorArcanaImages
  const [blockId, setBlockId] = useState(data.record_blocks[0].id)
  const [practiceId, setPracticeId] = useState(data.practice_modes[0].id)
  const block = data.record_blocks.find((item) => item.id === blockId)
  const practice = data.practice_modes.find((item) => item.id === practiceId)
  const example = [spreads.fixed_example, spreads.fixed_mixed_example].find((item) => item.id === data.fixed_record.example_id)
  const positions = spreads.spreads.find((item) => item.id === example.spread_id).positions
  const cards = example.cards.map((item) => {
    if (!item.suit_id) {
      const card = major.cards.find((entry) => entry.number === item.card_number)
      return { name: card.name_zh, image: card.image, position: positions[item.position_number - 1], orientation: item.orientation }
    }
    const suit = minor.suits.find((entry) => entry.id === item.suit_id)
    const rank = minor.ranks.find((entry) => entry.id === item.rank_id)
    return { name: `${suit.name_zh}${rank.name_zh}`, image: `${suit.name_en}${rank.file_number}.png`, position: positions[item.position_number - 1], orientation: item.orientation }
  })
  const guidedCards = data.guided_case.cards.map((item) => {
    const card = major.cards.find((entry) => entry.name_zh === item.name)
    return { ...item, image: card.image }
  })

  return <section className="interactive-section tarot-review-detail">
    <div className="interactive-heading"><span>静态记录模板</span><h2>把当时的输入、版本和之后的复核分开保存</h2></div>
    <div className="tarot-review-ledger"><header><div><small>固定问题</small><strong>{data.fixed_record.question}</strong></div><span><small>时间范围</small>{data.fixed_record.time_range}</span></header><section><span><small>牌阵</small>{data.fixed_record.spread}</span><span><small>使用规则</small>{data.fixed_record.protocol}</span></section><div>{cards.map((item) => <figure key={item.position}><img className={item.orientation === 'reversed' ? 'reversed' : ''} src={`${deck.image_set.base_path}${item.image}`} alt={`${item.name}${item.orientation === 'reversed' ? '逆位' : '正位'}牌面`} loading="lazy" /><figcaption><strong>{item.position}</strong><span>{item.name} · {item.orientation === 'reversed' ? '逆位' : '正位'}</span></figcaption></figure>)}</div></div>
    <div className="knowledge-block tarot-review-blocks"><div className="interactive-heading"><span>五组记录字段</span><h2>选择一组，查看这一栏保存什么</h2></div><nav aria-label="选择记录字段组">{data.record_blocks.map((item, index) => <button className={item.id === blockId ? 'active' : ''} onClick={() => setBlockId(item.id)} aria-pressed={item.id === blockId} key={item.id}><i>{index + 1}</i><strong>{item.label}</strong></button>)}</nav><article><div>{block.fields.map((item) => <span key={item}><i>□</i>{item}</span>)}</div><p>{block.note}</p></article></div>
    <div className="knowledge-block tarot-review-questions"><div className="interactive-heading"><span>之后再看</span><h2>五个复核问题</h2></div><div>{data.review_questions.map((item, index) => <article key={item}><i>{index + 1}</i><p>{item}</p></article>)}</div></div>
    <div className="knowledge-block tarot-practice-modes"><div className="interactive-heading"><span>固定材料 · 自己练习</span><h2>五种练习各自只检查一个问题</h2></div><nav aria-label="选择学习练习">{data.practice_modes.map((item) => <button className={item.id === practiceId ? 'active' : ''} onClick={() => setPracticeId(item.id)} aria-pressed={item.id === practiceId} key={item.id}>{item.label}</button>)}</nav><article><small>练习材料</small><strong>{practice.material}</strong><p>{practice.task}</p><blockquote>{practice.check}</blockquote><button onClick={() => { window.location.hash = `#${practice.route}` }}>打开对应知识 <i>→</i></button></article></div>
    <div className="knowledge-block tarot-study-steps"><div className="interactive-heading"><span>并入的固定案例</span><h2>{data.guided_case.label}</h2></div><p>{data.guided_case.question}</p><section className="tarot-review-guided-cards">{guidedCards.map((item) => <figure key={item.position}><img className={item.orientation === 'reversed' ? 'reversed' : ''} src={`${deck.image_set.base_path}${item.image}`} alt={`${item.name}${item.orientation === 'reversed' ? '逆位' : '正位'}牌面`} loading="lazy" /><figcaption><strong>{item.position}</strong><span>{item.name} · {item.orientation === 'reversed' ? '逆位' : '正位'}</span></figcaption></figure>)}</section><div>{data.guided_case.steps.map((item, index) => <button onClick={() => { window.location.hash = `#${item.route}` }} key={item.label}><i>{index + 1}</i><strong>{item.label}</strong><span>{item.task}</span><b>打开知识 →</b></button>)}</div><blockquote>{data.guided_case.check}</blockquote></div>
    <div className="tarot-review-sources">{data.source_layers.map((item) => <article key={item.label}><strong>{item.label}</strong><p>{item.note}</p></article>)}</div>
  </section>
}

function TarotEthicsDetail() {
  const data = tarotDatasets.consultationEthics
  const [situationId, setSituationId] = useState(data.situations[0].id)
  const situation = data.situations.find((item) => item.id === situationId)

  return <section className="interactive-section tarot-ethics-detail">
    <div className="interactive-heading"><span>继续 · 改写 · 转交 · 保密 · 停止</span><h2>先看情境落在哪条边界上</h2></div>
    <nav className="tarot-ethics-situations" aria-label="选择咨询边界情境">{data.situations.map((item) => <button className={`${item.action_tone} ${item.id === situationId ? 'active' : ''}`} onClick={() => setSituationId(item.id)} aria-pressed={item.id === situationId} key={item.id}><small>{item.label}</small><strong>{item.action}</strong></button>)}</nav>
    <div className={`tarot-ethics-workbench ${situation.action_tone}`}><section><small>出现的问题</small><blockquote>{situation.question}</blockquote></section><i aria-hidden="true">→</i><article><header><small>处理方式</small><strong>{situation.action}</strong></header><p>{situation.response}</p><span>{situation.reason}</span></article></div>
    <div className="knowledge-block tarot-ethics-principles"><div className="interactive-heading"><span>五项共同原则</span><h2>每项原则只回答一个判断</h2></div><div>{data.principles.map((item) => <article key={item.id}><header><strong>{item.label}</strong><small>{item.short}</small></header><p>{item.note}</p></article>)}</div></div>
    <div className="knowledge-block tarot-ethics-links"><div className="interactive-heading"><span>回到已有知识</span><h2>边界不是终点，必要时换一个入口</h2></div><div>{data.linked_nodes.map((item) => <button onClick={() => { window.location.hash = `#${item.route}` }} key={item.route}><strong>{item.label}</strong><span>{item.note}</span><i>→</i></button>)}</div></div>
  </section>
}

function TarotDeckDetail() {
  const data = tarotDatasets.deckStructure
  const requestedParams = new URLSearchParams(window.location.hash.split('?')[1] || '')
  const requestedView = requestedParams.get('view')
  const requestedCatalogId = requestedParams.get('card')
  const [view, setView] = useState(requestedView === 'catalog' ? 'catalog' : 'structure')
  const [catalogId, setCatalogId] = useState(requestedCatalogId || 'major-0')
  const imagePath = (filename) => `${data.image_set.base_path}${filename}`
  const minorImage = (activeSuit, index) => `${activeSuit.name_en}${String(index + 1).padStart(2, '0')}.png`
  const catalogCards = [
    ...data.major_arcana.map((card, index) => ({ id: `major-${index}`, group: '大阿卡纳', label: card.name_zh, latin: card.name_en, number: card.number, image: card.image })),
    ...data.minor_arcana.suits.flatMap((activeSuit) => data.minor_arcana.ranks.map((rank, index) => ({ id: `${activeSuit.id}-${rank.id}`, group: activeSuit.name_zh, label: `${activeSuit.name_zh}${rank.name_zh}`, latin: `${rank.name_en} of ${activeSuit.name_en}`, number: rank.name_zh, image: minorImage(activeSuit, index), suitId: activeSuit.id, rankId: rank.id }))),
  ]
  const catalogCard = catalogCards.find((card) => card.id === catalogId) || catalogCards[0]
  const selectDeckView = (id) => {
    setView(id)
    window.history.replaceState(null, '', id === 'catalog'
      ? `#/topic/tarot/deck-structure?view=catalog&card=${encodeURIComponent(catalogCard.id)}`
      : '#/topic/tarot/deck-structure')
  }
  const selectCatalogCard = (id) => {
    setCatalogId(id)
    window.history.replaceState(null, '', `#/topic/tarot/deck-structure?view=catalog&card=${encodeURIComponent(id)}`)
  }
  const openCatalogCard = () => {
    window.location.hash = catalogCard.id.startsWith('major-')
      ? `/topic/tarot/major-arcana-images?card=${encodeURIComponent(catalogCard.number)}`
      : `/topic/tarot/minor-arcana-images?suit=${encodeURIComponent(catalogCard.suitId)}&rank=${encodeURIComponent(catalogCard.rankId)}`
  }

  return (
    <section className="interactive-section tarot-deck-detail">
      <div className="interactive-heading"><span>固定RWS样本 · 只识别牌组</span><h2>先看结构，再进入单牌资料</h2></div>
      <nav className="tarot-view-selector" aria-label="牌组结构与相关知识节点">
        {[['structure', '整体结构', '78 → 22 + 56'], ['catalog', '完整牌表', '78张一览']].map(([id, label, note]) => (
          <button className={view === id ? 'active' : ''} onClick={() => selectDeckView(id)} aria-pressed={view === id} key={id}><strong>{label}</strong><small>{note}</small></button>
        ))}
        <button className="related" onClick={() => { window.location.hash = '/topic/tarot/major-arcana-images' }}><strong>大阿卡纳</strong><small>查看22张单牌 <i aria-hidden="true">→</i></small></button>
        <button className="related" onClick={() => { window.location.hash = '/topic/tarot/minor-arcana-images' }}><strong>小阿卡纳</strong><small>查看56张单牌 <i aria-hidden="true">→</i></small></button>
      </nav>

      {view === 'structure' && (
        <div className="tarot-anatomy-board">
          <header><small>完整固定样本</small><strong>78</strong><span>张牌</span></header>
          <article className="major"><div><small>Major Arcana</small><strong>大阿卡纳</strong><b>22张</b></div><section className="tarot-major-sample">{[data.major_arcana[0], data.major_arcana[10], data.major_arcana[21]].map((card) => <img src={imagePath(card.image)} alt={`${card.name_zh}牌面`} loading="lazy" key={card.number} />)}<p>0 → XXI</p></section></article>
          <article className="minor"><div><small>Minor Arcana</small><strong>小阿卡纳</strong><b>56张</b></div><section>{data.minor_arcana.suits.map((item) => <span className={item.id} key={item.id}><img src={imagePath(minorImage(item, 0))} alt={`${item.name_zh}王牌牌面`} loading="lazy" /><div><strong>{item.name_zh}</strong><small>10 数字牌 + 4 宫廷牌</small></div></span>)}</section></article>
        </div>
      )}

      {view === 'catalog' && (
        <div className="tarot-full-catalog">
          <div>
            <section className="major">
              <header><strong>大阿卡纳</strong><small>22张</small></header>
              <div>{data.major_arcana.map((card, index) => <button className={catalogId === `major-${index}` ? 'active' : ''} onClick={() => selectCatalogCard(`major-${index}`)} aria-pressed={catalogId === `major-${index}`} title={`${card.number} ${card.name_zh}`} key={card.number}><img src={imagePath(card.image)} alt="" loading="lazy" /><span>{card.number}</span></button>)}</div>
            </section>
            {data.minor_arcana.suits.map((activeSuit) => (
              <section className={activeSuit.id} key={activeSuit.id}>
                <header><strong>{activeSuit.name_zh}</strong><small>14张</small></header>
                <div>{data.minor_arcana.ranks.map((rank, index) => { const id = `${activeSuit.id}-${rank.id}`; return <button className={catalogId === id ? 'active' : ''} onClick={() => selectCatalogCard(id)} aria-pressed={catalogId === id} title={`${activeSuit.name_zh}${rank.name_zh}`} key={rank.id}><img src={imagePath(minorImage(activeSuit, index))} alt="" loading="lazy" /><span>{rank.name_zh}</span></button> })}</div>
              </section>
            ))}
          </div>
          <article>
            <img src={imagePath(catalogCard.image)} alt={`${catalogCard.label}牌面`} />
            <small>{catalogCard.group} · {catalogCard.number}</small>
            <strong>{catalogCard.label}</strong>
            <span>{catalogCard.latin}</span>
            <button onClick={openCatalogCard}>查看这张牌 <i aria-hidden="true">→</i></button>
          </article>
        </div>
      )}

      <div className="knowledge-block tarot-version-block">
        <div className="interactive-heading"><span>编号与译名都带版本</span><h2>78张结构稳定，不代表每副牌的顺序和名称完全相同</h2></div>
        <div>{data.version_notes.map((item) => <article key={item.label}><small>{item.label}</small><strong>{item.title}</strong><p>{item.note}</p></article>)}</div>
      </div>
      <div className="knowledge-block tarot-boundary-block">
        <div className="interactive-heading"><span>三层对象 · 不压成一张牌义表</span><h2>身份、图像与解释分别需要自己的来源</h2></div>
        <div>{data.reading_boundaries.map((item, index) => <article key={item.label}><i>{index + 1}</i><small>{item.label}</small><strong>{item.title}</strong><p>{item.note}</p></article>)}</div>
      </div>
    </section>
  )
}

function TarotHistoryDetail() {
  const data = tarotDatasets.historyAndDecks
  const deck = tarotDatasets.deckStructure
  const requestedParams = new URLSearchParams(window.location.hash.split('?')[1] || '')
  const requestedPeriod = requestedParams.get('period')
  const requestedComparison = requestedParams.get('compare')
  const [activeId, setActiveId] = useState(data.timeline.some((item) => item.id === requestedPeriod) ? requestedPeriod : data.timeline[0].id)
  const [comparisonId, setComparisonId] = useState(data.visual_comparisons.some((item) => item.id === requestedComparison) ? requestedComparison : data.visual_comparisons[0].id)
  const active = data.timeline.find((item) => item.id === activeId)
  const activeComparison = data.visual_comparisons.find((item) => item.id === comparisonId) || data.visual_comparisons[0]
  const rwsSamples = [deck.major_arcana[0], deck.major_arcana[17], deck.major_arcana[21]]
  const choosePeriod = (id) => {
    setActiveId(id)
    window.history.replaceState(null, '', `#/topic/tarot/history-and-decks?period=${encodeURIComponent(id)}&compare=${encodeURIComponent(comparisonId)}`)
  }
  const chooseComparison = (id) => {
    setComparisonId(id)
    window.history.replaceState(null, '', `#/topic/tarot/history-and-decks?period=${encodeURIComponent(activeId)}&compare=${encodeURIComponent(id)}`)
  }

  return (
    <section className="interactive-section tarot-history-detail">
      <div className="interactive-heading"><span>15世纪 → 20世纪</span><h2>先看塔罗怎么变成今天的样子</h2></div>
      <nav className="tarot-history-timeline" aria-label="选择塔罗历史阶段">
        {data.timeline.map((item, index) => (
          <button className={item.id === activeId ? 'active' : ''} onClick={() => choosePeriod(item.id)} aria-pressed={item.id === activeId} key={item.id}>
            <i>{String(index + 1).padStart(2, '0')}</i><strong>{item.period}</strong><small>{item.place}</small>
          </button>
        ))}
      </nav>
      <div className={`tarot-history-workbench ${active.id}`}>
        <article>
          <small>{active.place}</small><b>{active.period}</b><h3>{active.title}</h3><p>{active.note}</p>
        </article>
        {active.id === 'rws'
          ? <figure>{rwsSamples.map((card, index) => <img src={`${deck.image_set.base_path}${card.image}`} alt={`${card.name_zh}牌面`} loading="lazy" style={{ '--history-card': index }} key={card.number} />)}</figure>
          : <figure className="history-artifact"><img src={active.artifact_image} alt={active.artifact_alt} /><figcaption>{active.artifact_label}</figcaption></figure>}
      </div>

      <section className="tarot-deck-visual-comparison">
        <div className="interactive-heading"><span>12张牌 · 两种画面</span><h2>选一张，对照马赛系与RWS</h2></div>
        <nav className="tarot-deck-visual-selector" aria-label="选择牌面对照">
          {data.visual_comparisons.map((item) => <button className={item.id === comparisonId ? 'active' : ''} onClick={() => chooseComparison(item.id)} aria-pressed={item.id === comparisonId} key={item.id}><i>{item.marker}</i><strong>{item.name_zh}</strong></button>)}
        </nav>
        <article className="tarot-deck-visual-active">
          <header><strong>{activeComparison.name_zh}</strong><small>{activeComparison.name_en}</small></header>
          <div className="tarot-deck-visual-pair">
            <figure><span>RWS 1910</span><img src={`${deck.image_set.base_path}${activeComparison.rws_image}`} alt={`RWS ${activeComparison.name_zh}牌面`} /></figure>
            <i aria-hidden="true">↔</i>
            <figure><span>{activeComparison.marseille_label}</span><img src={activeComparison.marseille_image} alt={`马赛系${activeComparison.name_zh}牌面`} /></figure>
          </div>
          <p>{activeComparison.note}</p>
        </article>
      </section>

      <section className="tarot-family-comparison">
        <div className="interactive-heading"><span>三种常见参照</span><h2>牌面看起来不同，是因为牌系不同</h2></div>
        <div>
          {data.deck_families.map((item, index) => (
            <article className={item.id} key={item.id}>
              <i>{String(index + 1).padStart(2, '0')}</i><img src={item.sample_image} alt={item.sample_alt} loading="lazy" /><small>{item.period}</small><h3>{item.name}</h3><b>{item.latin}</b>
              <dl><div><dt>画面</dt><dd>{item.look}</dd></div><div><dt>区别</dt><dd>{item.difference}</dd></div></dl>
              {item.id === 'rws' && <button onClick={() => { window.location.hash = '/topic/tarot/deck-structure' }}>查看RWS牌组结构 <i aria-hidden="true">→</i></button>}
            </article>
          ))}
        </div>
      </section>
      <aside className="tarot-card-system-comparison"><strong>相邻系统辨别</strong><p>{data.adjacent_system_note}</p></aside>
    </section>
  )
}

function TarotGlossaryDetail() {
  const data = tarotDatasets.glossary
  const requestedParams = new URLSearchParams(window.location.hash.split('?')[1] || '')
  const requestedTermId = requestedParams.get('term')
  const initialTerm = data.terms.find((term) => term.id === requestedTermId) || data.terms[0]
  const [groupId, setGroupId] = useState(initialTerm.group)
  const [termId, setTermId] = useState(initialTerm.id)
  const terms = data.terms.filter((term) => term.group === groupId)
  const term = data.terms.find((item) => item.id === termId) || terms[0]
  const relatedTerms = (term.related || []).map((id) => data.terms.find((item) => item.id === id)).filter(Boolean)
  useEffect(() => {
    const requestedTerm = data.terms.find((item) => item.id === requestedTermId)
    if (requestedTerm && requestedTerm.id !== termId) {
      setGroupId(requestedTerm.group)
      setTermId(requestedTerm.id)
    }
  }, [requestedTermId, termId, data.terms])
  const chooseGroup = (id) => {
    const first = data.terms.find((item) => item.group === id)
    setGroupId(id)
    setTermId(first.id)
    window.history.replaceState(null, '', `#/topic/tarot/glossary?term=${encodeURIComponent(first.id)}`)
  }
  const chooseTerm = (item) => {
    setGroupId(item.group)
    setTermId(item.id)
    window.history.replaceState(null, '', `#/topic/tarot/glossary?term=${encodeURIComponent(item.id)}`)
  }

  return (
    <section className="interactive-section tarot-glossary-detail">
      <div className="interactive-heading"><span>4组 · 12个词</span><h2>点一个词，马上知道它在说什么</h2></div>
      <nav className="tarot-glossary-groups" aria-label="选择术语分组">
        {data.groups.map((group) => <button className={group.id === groupId ? 'active' : ''} onClick={() => chooseGroup(group.id)} aria-pressed={group.id === groupId} key={group.id}><strong>{group.label}</strong><small>{group.note}</small></button>)}
      </nav>
      <div className={`tarot-glossary-workbench group-${groupId}`}>
        <nav aria-label={`选择${data.groups.find((group) => group.id === groupId).label}术语`}>
          {terms.map((item) => <button className={item.id === term.id ? 'active' : ''} onClick={() => chooseTerm(item)} aria-pressed={item.id === term.id} key={item.id}><strong>{item.term}</strong><small>{item.latin}</small></button>)}
        </nav>
        <article>
          <header><small>{term.latin}</small><h3>{term.term}</h3><b>{term.short}</b></header>
          <p>{term.detail}</p>
          <div><small>例子</small><strong>{term.example}</strong></div>
          {relatedTerms.length > 0 && <nav className="tarot-related-terms" aria-label="相关塔罗术语"><small>相关词</small>{relatedTerms.map((item) => <button onClick={() => chooseTerm(item)} key={item.id}>{item.term}</button>)}</nav>}
          <button onClick={() => { window.location.hash = term.route }}>查看对应知识 <i aria-hidden="true">→</i></button>
        </article>
      </div>
    </section>
  )
}

function TarotImageryMapDetail() {
  const data = tarotDatasets.imageryElementsMap
  const deck = tarotDatasets.deckStructure
  const major = tarotDatasets.majorArcanaImages
  const minor = tarotDatasets.minorArcanaImages
  const requestedParams = new URLSearchParams(window.location.hash.split('?')[1] || '')
  const allTerms = data.groups.flatMap((group) => group.terms)
  const requestedTerm = requestedParams.get('element')
  const requestedScope = requestedParams.get('scope')
  const initialTerm = allTerms.includes(requestedTerm) ? requestedTerm : data.groups[0].terms[0]
  const [groupId, setGroupId] = useState(data.groups.find((group) => group.terms.includes(initialTerm)).id)
  const [element, setElement] = useState(initialTerm)
  const [scope, setScope] = useState(['all', 'major', 'minor'].includes(requestedScope) ? requestedScope : 'all')
  const imagePath = (filename) => `${deck.image_set.base_path}${filename}`
  const findMatches = (term) => [
    ...major.cards.filter((card) => card.visible_elements.some((item) => item.includes(term))).map((card) => ({ id:`major-${card.number}`, group:'major', groupLabel:'大阿卡纳', name:card.name_zh, number:card.number, image:card.image, route:`/topic/tarot/major-arcana-images?card=${encodeURIComponent(card.number)}&mode=imagery` })),
    ...minor.suits.flatMap((suit) => minor.ranks.filter((rank) => minor.observations[suit.id][rank.id].some((item) => item.includes(term))).map((rank) => ({ id:`${suit.id}-${rank.id}`, group:'minor', groupLabel:suit.name_zh, name:`${suit.name_zh}${rank.name_zh}`, number:rank.name_zh, image:`${suit.name_en}${rank.file_number}.png`, route:`/topic/tarot/minor-arcana-images?suit=${encodeURIComponent(suit.id)}&rank=${encodeURIComponent(rank.id)}&mode=imagery` }))),
  ]
  const matches = findMatches(element)
  const visibleMatches = scope === 'all' ? matches : matches.filter((item) => item.group === scope)
  const currentGroup = data.groups.find((group) => group.id === groupId)
  const replaceUrl = (nextElement, nextScope) => window.history.replaceState(null, '', `#/topic/tarot/imagery-elements-map?element=${encodeURIComponent(nextElement)}&scope=${nextScope}`)
  const chooseGroup = (id) => { const term = data.groups.find((group) => group.id === id).terms[0]; setGroupId(id); setElement(term); replaceUrl(term, scope) }
  const chooseElement = (term) => { setElement(term); replaceUrl(term, scope) }
  const chooseScope = (id) => { setScope(id); replaceUrl(element, id) }

  return (
    <section className="interactive-section tarot-imagery-map-detail">
      <div className="interactive-heading"><span>78张牌 · 跨牌连接</span><h2>选一个元素，看它出现在哪些牌里</h2></div>
      <nav className="tarot-imagery-groups" aria-label="选择牌面元素分组">
        {data.groups.map((group) => <button className={group.id === groupId ? 'active' : ''} onClick={() => chooseGroup(group.id)} aria-pressed={group.id === groupId} key={group.id}><strong>{group.label}</strong><small>{group.note}</small></button>)}
      </nav>
      <nav className="tarot-imagery-terms" aria-label={`选择${currentGroup.label}元素`}>
        {currentGroup.terms.map((term) => { const count = findMatches(term).length; return <button className={term === element ? 'active' : ''} onClick={() => chooseElement(term)} aria-pressed={term === element} key={term}><strong>{term}</strong><small>{count}张</small></button> })}
      </nav>
      <div className="tarot-imagery-map-workbench">
        <header><i>{element}</i><div><small>共同可见元素</small><strong>{matches.length}张牌</strong><span>大阿卡纳 {matches.filter((item) => item.group === 'major').length} · 小阿卡纳 {matches.filter((item) => item.group === 'minor').length}</span></div></header>
        <nav aria-label="筛选大阿卡纳或小阿卡纳">{[['all','全部'],['major','大阿卡纳'],['minor','小阿卡纳']].map(([id,label]) => <button className={scope === id ? 'active' : ''} onClick={() => chooseScope(id)} aria-pressed={scope === id} key={id}>{label}</button>)}</nav>
        {visibleMatches.length > 0
          ? <div>{visibleMatches.map((item) => <button onClick={() => { window.location.hash = item.route }} key={item.id}><img src={imagePath(item.image)} alt="" loading="lazy" /><span><small>{item.groupLabel} · {item.number}</small><strong>{item.name}</strong></span><i aria-hidden="true">→</i></button>)}</div>
          : <p>当前范围内没有匹配牌面。</p>}
      </div>
    </section>
  )
}

