function MajorArcanaImagesDetail() {
  const data = tarotDatasets.majorArcanaImages
  const meaningData = tarotDatasets.waiteMajorMeanings
  const deck = tarotDatasets.deckStructure
  const visualTerms = ['山', '水', '杖', '太阳', '玫瑰']
  const requestedParams = new URLSearchParams(window.location.hash.split('?')[1] || '')
  const requestedNumber = requestedParams.get('card')
  const requestedMode = requestedParams.get('mode')
  const [activeNumber, setActiveNumber] = useState(data.cards.some((card) => card.number === requestedNumber) ? requestedNumber : data.cards[0].number)
  const [detailMode, setDetailMode] = useState(['imagery', 'upright', 'reversed'].includes(requestedMode) ? requestedMode : 'imagery')
  const [visualTerm, setVisualTerm] = useState(visualTerms[0])
  const activeIndex = data.cards.findIndex((card) => card.number === activeNumber)
  const card = data.cards[activeIndex]
  const meaning = meaningData.cards.find((item) => item.number === activeNumber)
  const matchingVisualTerms = visualTerms.filter((term) => card.visible_elements.some((element) => element.includes(term)))
  const visualMatches = data.cards.filter((item) => item.visible_elements.some((element) => element.includes(visualTerm)))
  const imagePath = (filename) => `${deck.image_set.base_path}${filename}`
  const replaceMajorUrl = (number, mode) => window.history.replaceState(null, '', `#/topic/tarot/major-arcana-images?card=${encodeURIComponent(number)}&mode=${mode}`)
  const selectCard = (number) => { setActiveNumber(number); replaceMajorUrl(number, detailMode) }
  const selectMode = (mode) => { setDetailMode(mode); replaceMajorUrl(activeNumber, mode) }
  const selectRelative = (offset) => selectCard(data.cards[(activeIndex + offset + data.cards.length) % data.cards.length].number)
  const openVisualMatch = (number) => {
    setActiveNumber(number)
    setDetailMode('imagery')
    window.history.replaceState(null, '', `#/topic/tarot/major-arcana-images?card=${encodeURIComponent(number)}&mode=imagery`)
    requestAnimationFrame(() => document.querySelector('.major-image-workbench')?.scrollIntoView({ behavior: 'smooth', block: 'center' }))
  }
  const openVisualTerm = (term) => {
    setVisualTerm(term)
    requestAnimationFrame(() => document.querySelector('.major-element-index')?.scrollIntoView({ behavior: 'smooth', block: 'start' }))
  }

  return (
    <section className="interactive-section major-imagery-detail">
      <div className="interactive-heading"><span>22张大阿卡纳</span><h2>选一张牌，查看牌面与牌义</h2></div>
      <div className="major-image-index" aria-label="选择大阿卡纳牌面">
        {data.cards.map((item) => <button className={item.number === activeNumber ? 'active' : ''} onClick={() => selectCard(item.number)} aria-pressed={item.number === activeNumber} title={`${item.number} ${item.name_zh}`} key={item.number}><img src={imagePath(item.image)} alt="" loading="lazy" /><span>{item.number}</span></button>)}
      </div>

      <div className="major-image-workbench">
        <figure>
          <img className={detailMode === 'reversed' ? 'reversed' : ''} src={imagePath(card.image)} alt={`${card.number} ${card.name_zh}${detailMode === 'reversed' ? '逆位' : '正位'}牌面`} />
        </figure>
        <article>
          <header><small>{card.number}</small><div><h3>{card.name_zh}</h3><p>{card.name_en}</p></div><button className="deck-card-backlink" onClick={() => { window.location.hash = `/topic/tarot/deck-structure?view=catalog&card=major-${activeIndex}` }}>78张牌表 <i aria-hidden="true">→</i></button></header>
          <nav className="card-reading-tabs" aria-label="选择查看内容">
            <button className={detailMode === 'imagery' ? 'active' : ''} onClick={() => selectMode('imagery')}>牌面</button>
            <button className={detailMode === 'upright' ? 'active' : ''} onClick={() => selectMode('upright')}>正位牌义</button>
            <button className={detailMode === 'reversed' ? 'active' : ''} onClick={() => selectMode('reversed')}>逆位牌义</button>
          </nav>
          {detailMode === 'imagery'
            ? <section className="combined-visible-elements"><small>画面中有什么</small>{card.visible_elements.map((element, index) => <p key={element}><i>{index + 1}</i><span>{element}</span></p>)}{matchingVisualTerms.length > 0 && <nav className="card-element-backlinks" aria-label="查看相关画面元素索引"><small>相关索引</small>{matchingVisualTerms.map((term) => <button onClick={() => openVisualTerm(term)} key={term}>{term} <i aria-hidden="true">↓</i></button>)}</nav>}</section>
            : <section className="combined-meaning-keywords">{meaning[detailMode].map((keyword) => <span key={keyword}>{keyword}</span>)}</section>}
          <nav><button onClick={() => selectRelative(-1)} aria-label="查看上一张牌">← 上一张</button><span>{activeIndex + 1} / {data.cards.length}</span><button onClick={() => selectRelative(1)} aria-label="查看下一张牌">下一张 →</button></nav>
        </article>
      </div>
      <section className="major-element-index">
        <div className="interactive-heading"><span>重复画面元素</span><h2>相同元素出现在哪些牌里</h2></div>
        <nav aria-label="选择画面元素">
          {visualTerms.map((term) => { const count = data.cards.filter((item) => item.visible_elements.some((element) => element.includes(term))).length; return <button className={term === visualTerm ? 'active' : ''} onClick={() => setVisualTerm(term)} aria-pressed={term === visualTerm} key={term}><strong>{term}</strong><small>{count}张</small></button> })}
        </nav>
        <div>
          {visualMatches.map((item) => <button className={item.number === activeNumber ? 'active' : ''} onClick={() => openVisualMatch(item.number)} key={item.number}><img src={imagePath(item.image)} alt="" loading="lazy" /><span><small>{item.number}</small><strong>{item.name_zh}</strong></span><i aria-hidden="true">→</i></button>)}
        </div>
      </section>
      <div className="knowledge-block major-image-version">
        <div className="interactive-heading"><span>力量与正义 · 编号版本</span><h2>{data.version_example.title}</h2></div>
        <div>
          {data.version_example.cards.map((name) => { const item = data.cards.find((entry) => entry.name_zh === name); return <article key={name}><img src={imagePath(item.image)} alt={`${name}牌面`} loading="lazy" /><div><small>RWS编号</small><strong>{item.number} · {item.name_zh}</strong></div></article> })}
          <aside><small>RWS</small><strong>{data.version_example.rws}</strong><small>更早常见顺序</small><strong>{data.version_example.earlier_common}</strong><p>{data.version_example.note}</p></aside>
        </div>
      </div>
    </section>
  )
}

function MinorArcanaImagesDetail() {
  const data = tarotDatasets.minorArcanaImages
  const meaningData = tarotDatasets.waiteMinorMeanings
  const deck = tarotDatasets.deckStructure
  const visualTerms = ['云', '山', '水', '船', '花', '马']
  const requestedParams = new URLSearchParams(window.location.hash.split('?')[1] || '')
  const requestedSuitId = requestedParams.get('suit')
  const requestedRankId = requestedParams.get('rank')
  const requestedMode = requestedParams.get('mode')
  const requestedView = requestedParams.get('view')
  const [suitId, setSuitId] = useState(data.suits.some((item) => item.id === requestedSuitId) ? requestedSuitId : data.suits[0].id)
  const [rankId, setRankId] = useState(data.ranks.some((item) => item.id === requestedRankId) ? requestedRankId : data.ranks[0].id)
  const [detailMode, setDetailMode] = useState(['imagery', 'upright', 'reversed'].includes(requestedMode) ? requestedMode : 'imagery')
  const [compareOrientation, setCompareOrientation] = useState('upright')
  const [courtOrientation, setCourtOrientation] = useState('upright')
  const [visualTerm, setVisualTerm] = useState(visualTerms[0])
  const suit = data.suits.find((item) => item.id === suitId)
  const rankIndex = data.ranks.findIndex((item) => item.id === rankId)
  const rank = data.ranks[rankIndex]
  const visibleElements = data.observations[suit.id][rank.id]
  const keywords = detailMode === 'imagery' ? [] : meaningData.meanings[suit.id][rank.id][detailMode]
  const matchingVisualTerms = visualTerms.filter((term) => visibleElements.some((element) => element.includes(term)))
  const pipRanks = data.ranks.filter((item) => item.kind === '数字牌')
  const courtRanks = data.ranks.filter((item) => item.kind === '宫廷牌')
  const visualMatches = data.suits.flatMap((activeSuit) => data.ranks.filter((activeRank) => data.observations[activeSuit.id][activeRank.id].some((element) => element.includes(visualTerm))).map((activeRank) => ({ suit: activeSuit, rank: activeRank })))
  const imagePath = (activeSuit, activeRank) => `${deck.image_set.base_path}${activeSuit.name_en}${activeRank.file_number}.png`
  const replaceMinorUrl = (nextSuitId, nextRankId, mode) => window.history.replaceState(null, '', `#/topic/tarot/minor-arcana-images?suit=${encodeURIComponent(nextSuitId)}&rank=${encodeURIComponent(nextRankId)}&mode=${mode}`)
  const chooseSuit = (id) => { setSuitId(id); setRankId(data.ranks[0].id); setDetailMode('imagery'); replaceMinorUrl(id, data.ranks[0].id, 'imagery') }
  const selectRank = (id) => { setRankId(id); replaceMinorUrl(suitId, id, detailMode) }
  const selectMode = (mode) => { setDetailMode(mode); replaceMinorUrl(suitId, rankId, mode) }
  const selectRelative = (offset) => selectRank(data.ranks[(rankIndex + offset + data.ranks.length) % data.ranks.length].id)
  const openVisualMatch = (activeSuit, activeRank) => {
    setSuitId(activeSuit.id)
    setRankId(activeRank.id)
    setDetailMode('imagery')
    window.history.replaceState(null, '', `#/topic/tarot/minor-arcana-images?suit=${encodeURIComponent(activeSuit.id)}&rank=${encodeURIComponent(activeRank.id)}&mode=imagery`)
    requestAnimationFrame(() => document.querySelector('.minor-image-workbench')?.scrollIntoView({ behavior: 'smooth', block: 'center' }))
  }
  const openVisualTerm = (term) => {
    setVisualTerm(term)
    requestAnimationFrame(() => document.querySelector('.minor-element-index')?.scrollIntoView({ behavior: 'smooth', block: 'start' }))
  }

  useEffect(() => {
    const target = requestedView === 'pips' ? '#pip-card-atlas' : requestedView === 'court' ? '#court-card-atlas' : ''
    if (!target) return
    requestAnimationFrame(() => document.querySelector(target)?.scrollIntoView({ block: 'start' }))
  }, [requestedView])

  return (
    <section className={`interactive-section minor-imagery-detail suit-${suit.id}`}>
      <div className="interactive-heading"><span>四个花色 · 56张牌</span><h2>选一张牌，查看牌面与牌义</h2></div>
      <nav className="minor-suit-selector" aria-label="选择小阿卡纳花色">
        {data.suits.map((item) => <button className={`${item.id} ${item.id === suitId ? 'active' : ''}`} onClick={() => chooseSuit(item.id)} aria-pressed={item.id === suitId} key={item.id}><i>{item.mark}</i><span><strong>{item.name_zh}</strong><small>{item.name_en}</small></span></button>)}
      </nav>
      <div className="minor-card-index" aria-label={`选择${suit.name_zh}牌面`}>
        {data.ranks.map((item) => <button className={`${item.kind === '宫廷牌' ? 'court' : ''} ${item.id === rankId ? 'active' : ''}`} onClick={() => selectRank(item.id)} aria-pressed={item.id === rankId} title={`${suit.name_zh}${item.name_zh}`} key={item.id}><img src={imagePath(suit, item)} alt="" loading="lazy" /><span>{item.name_zh}</span></button>)}
      </div>
      <div className="minor-image-workbench">
        <figure><img className={detailMode === 'reversed' ? 'reversed' : ''} src={imagePath(suit, rank)} alt={`${suit.name_zh}${rank.name_zh}${detailMode === 'reversed' ? '逆位' : '正位'}牌面`} /></figure>
        <article>
          <header><i>{suit.mark}</i><div><small>{rank.kind}</small><h3>{suit.name_zh}{rank.name_zh}</h3><p>{rank.name_en} of {suit.name_en}</p></div><button className="deck-card-backlink" onClick={() => { window.location.hash = `/topic/tarot/deck-structure?view=catalog&card=${encodeURIComponent(`${suit.id}-${rank.id}`)}` }}>78张牌表 <i aria-hidden="true">→</i></button></header>
          <nav className="card-reading-tabs" aria-label="选择查看内容">
            <button className={detailMode === 'imagery' ? 'active' : ''} onClick={() => selectMode('imagery')}>牌面</button>
            <button className={detailMode === 'upright' ? 'active' : ''} onClick={() => selectMode('upright')}>正位牌义</button>
            <button className={detailMode === 'reversed' ? 'active' : ''} onClick={() => selectMode('reversed')}>逆位牌义</button>
          </nav>
          {detailMode === 'imagery'
            ? <section className="minor-visible-elements"><small>画面中有什么</small>{visibleElements.map((element, index) => <p key={element}><i>{index + 1}</i><span>{element}</span></p>)}{matchingVisualTerms.length > 0 && <nav className="card-element-backlinks" aria-label="查看相关场景元素索引"><small>相关索引</small>{matchingVisualTerms.map((term) => <button onClick={() => openVisualTerm(term)} key={term}>{term} <i aria-hidden="true">↓</i></button>)}</nav>}</section>
            : <section className="combined-meaning-keywords">{keywords.map((keyword) => <span key={keyword}>{keyword}</span>)}</section>}
          <nav><button onClick={() => selectRelative(-1)}>← 上一张</button><span>{rankIndex + 1} / 14</span><button onClick={() => selectRelative(1)}>下一张 →</button></nav>
        </article>
      </div>
      <section className="minor-rank-comparison">
        <div className="interactive-heading"><span>四花色横向看</span><h2>同为{rank.name_zh}，四张牌有什么不同</h2></div>
        <nav className="minor-compare-orientation" aria-label="选择横向对照方向">
          <button className={compareOrientation === 'upright' ? 'active' : ''} onClick={() => setCompareOrientation('upright')}>正位</button>
          <button className={compareOrientation === 'reversed' ? 'active' : ''} onClick={() => setCompareOrientation('reversed')}>逆位</button>
        </nav>
        <div>
          {data.suits.map((item) => (
            <button className={`${item.id} ${item.id === suitId ? 'active' : ''}`} onClick={() => openVisualMatch(item, rank)} aria-label={`查看${item.name_zh}${rank.name_zh}`} key={item.id}>
              <img className={compareOrientation === 'reversed' ? 'reversed' : ''} src={imagePath(item, rank)} alt={`${item.name_zh}${rank.name_zh}${compareOrientation === 'reversed' ? '逆位' : '正位'}牌面`} loading="lazy" />
              <span className="minor-rank-title"><i>{item.mark}</i><strong>{item.name_zh}{rank.name_zh}</strong></span>
              <span className="minor-rank-keywords">{meaningData.meanings[item.id][rank.id][compareOrientation].slice(0, 4).map((keyword) => <i key={keyword}>{keyword}</i>)}</span>
              <small>查看单牌 →</small>
            </button>
          ))}
        </div>
      </section>
      <section className="pip-card-atlas" id="pip-card-atlas">
        <div className="interactive-heading"><span>4个花色 × 10个等级</span><h2>40张数字牌按号码排开</h2></div>
        <div className="pip-card-atlas-scroll">
          <div className="pip-card-atlas-grid">
            <div className="pip-atlas-corner"><strong>4 × 10</strong><small>花色 × 等级</small></div>
            {pipRanks.map((pipRank) => <header key={pipRank.id}><strong>{pipRank.name_zh}</strong><small>{pipRank.name_en}</small></header>)}
            {data.suits.map((activeSuit) => (
              <Fragment key={activeSuit.id}>
                <header className={`pip-suit-label ${activeSuit.id}`}><i>{activeSuit.mark}</i><strong>{activeSuit.name_zh}</strong><small>{activeSuit.name_en}</small></header>
                {pipRanks.map((pipRank) => (
                  <button className={`${activeSuit.id} ${activeSuit.id === suitId && pipRank.id === rankId ? 'active' : ''}`} onClick={() => openVisualMatch(activeSuit, pipRank)} aria-label={`查看${activeSuit.name_zh}${pipRank.name_zh}`} key={`${activeSuit.id}-${pipRank.id}`}>
                    <img src={imagePath(activeSuit, pipRank)} alt={`${activeSuit.name_zh}${pipRank.name_zh}牌面`} loading="lazy" />
                    <span>{activeSuit.mark}{pipRank.name_zh}</span>
                  </button>
                ))}
              </Fragment>
            ))}
          </div>
        </div>
      </section>
      <section className="court-card-atlas" id="court-card-atlas">
        <div className="interactive-heading"><span>4个等级 × 4个花色</span><h2>16张宫廷牌放在一起看</h2></div>
        <nav className="minor-compare-orientation" aria-label="选择宫廷牌对照方向">
          <button className={courtOrientation === 'upright' ? 'active' : ''} onClick={() => setCourtOrientation('upright')}>正位</button>
          <button className={courtOrientation === 'reversed' ? 'active' : ''} onClick={() => setCourtOrientation('reversed')}>逆位</button>
        </nav>
        <div className="court-card-atlas-scroll">
          <div className="court-card-atlas-grid">
            <div className="court-atlas-corner"><strong>4 × 4</strong><small>等级 × 花色</small></div>
            {data.suits.map((item) => <header className={item.id} key={item.id}><i>{item.mark}</i><strong>{item.name_zh}</strong><small>{item.name_en}</small></header>)}
            {courtRanks.map((courtRank) => (
              <Fragment key={courtRank.id}>
                <header className="court-rank-label"><strong>{courtRank.name_zh}</strong><small>{courtRank.name_en}</small></header>
                {data.suits.map((activeSuit) => (
                  <button className={`${activeSuit.id} ${activeSuit.id === suitId && courtRank.id === rankId ? 'active' : ''}`} onClick={() => openVisualMatch(activeSuit, courtRank)} aria-label={`查看${activeSuit.name_zh}${courtRank.name_zh}`} key={`${activeSuit.id}-${courtRank.id}`}>
                    <img className={courtOrientation === 'reversed' ? 'reversed' : ''} src={imagePath(activeSuit, courtRank)} alt={`${activeSuit.name_zh}${courtRank.name_zh}${courtOrientation === 'reversed' ? '逆位' : '正位'}牌面`} loading="lazy" />
                    <span><strong>{activeSuit.name_zh}{courtRank.name_zh}</strong>{meaningData.meanings[activeSuit.id][courtRank.id][courtOrientation].slice(0, 3).map((keyword) => <i key={keyword}>{keyword}</i>)}</span>
                  </button>
                ))}
              </Fragment>
            ))}
          </div>
        </div>
      </section>
      <section className="minor-element-index">
        <div className="interactive-heading"><span>重复场景元素</span><h2>相同元素出现在哪些小阿卡纳里</h2></div>
        <nav aria-label="选择小阿卡纳画面元素">
          {visualTerms.map((term) => { const count = data.suits.reduce((total, activeSuit) => total + data.ranks.filter((activeRank) => data.observations[activeSuit.id][activeRank.id].some((element) => element.includes(term))).length, 0); return <button className={term === visualTerm ? 'active' : ''} onClick={() => setVisualTerm(term)} aria-pressed={term === visualTerm} key={term}><strong>{term}</strong><small>{count}张</small></button> })}
        </nav>
        <div>
          {visualMatches.map(({ suit: activeSuit, rank: activeRank }) => <button className={`${activeSuit.id} ${activeSuit.id === suitId && activeRank.id === rankId ? 'active' : ''}`} onClick={() => openVisualMatch(activeSuit, activeRank)} key={`${activeSuit.id}-${activeRank.id}`}><img src={imagePath(activeSuit, activeRank)} alt="" loading="lazy" /><span><small>{activeSuit.name_zh}</small><strong>{activeSuit.name_zh}{activeRank.name_zh}</strong></span><i aria-hidden="true">→</i></button>)}
        </div>
      </section>
    </section>
  )
}

function WaiteMajorMeaningsDetail() {
  const data = tarotDatasets.waiteMajorMeanings
  const deck = tarotDatasets.deckStructure
  const [activeNumber, setActiveNumber] = useState(data.cards[0].number)
  const [orientation, setOrientation] = useState('upright')
  const card = data.cards.find((item) => item.number === activeNumber)
  const activeIndex = data.cards.findIndex((item) => item.number === activeNumber)
  const selectRelative = (offset) => setActiveNumber(data.cards[(activeIndex + offset + data.cards.length) % data.cards.length].number)

  return (
    <section className="interactive-section waite-meanings-detail">
      <div className="interactive-heading"><span>Arthur Edward Waite · 1910</span><h2>选择一张牌，再切换正位或逆位</h2></div>
      <div className="waite-meaning-index" aria-label="选择大阿卡纳牌义">
        {data.cards.map((item) => <button className={item.number === activeNumber ? 'active' : ''} onClick={() => setActiveNumber(item.number)} aria-pressed={item.number === activeNumber} key={item.number}><img src={`${deck.image_set.base_path}${item.image}`} alt="" loading="lazy" /><span>{item.number}</span></button>)}
      </div>
      <div className="waite-meaning-workbench">
        <figure><img className={orientation === 'reversed' ? 'reversed' : ''} src={`${deck.image_set.base_path}${card.image}`} alt={`${card.name_zh}牌面`} /></figure>
        <article>
          <header><small>{card.number}</small><div><h3>{card.name_zh}</h3><p>{card.name_en}</p></div></header>
          <nav className="waite-orientation-selector"><button className={orientation === 'upright' ? 'active' : ''} onClick={() => setOrientation('upright')}>正位</button><button className={orientation === 'reversed' ? 'active' : ''} onClick={() => setOrientation('reversed')}>逆位</button></nav>
          <section className="waite-keywords">{card[orientation].map((keyword) => <span key={keyword}>{keyword}</span>)}</section>
          <nav className="waite-meaning-pager"><button onClick={() => selectRelative(-1)}>← 上一张</button><span>{activeIndex + 1} / 22</span><button onClick={() => selectRelative(1)}>下一张 →</button></nav>
        </article>
      </div>
    </section>
  )
}

function WaiteMinorMeaningsDetail() {
  const data = tarotDatasets.waiteMinorMeanings
  const deck = tarotDatasets.deckStructure
  const [suitId, setSuitId] = useState(data.suits[0].id)
  const [rankId, setRankId] = useState(data.ranks[0].id)
  const [orientation, setOrientation] = useState('upright')
  const suit = data.suits.find((item) => item.id === suitId)
  const rankIndex = data.ranks.findIndex((item) => item.id === rankId)
  const rank = data.ranks[rankIndex]
  const keywords = data.meanings[suit.id][rank.id][orientation]
  const imagePath = (activeSuit, activeRank) => `${deck.image_set.base_path}${activeSuit.name_en}${activeRank.file_number}.png`
  const chooseSuit = (id) => { setSuitId(id); setRankId(data.ranks[0].id); setOrientation('upright') }
  const selectRelative = (offset) => setRankId(data.ranks[(rankIndex + offset + data.ranks.length) % data.ranks.length].id)

  return (
    <section className={`interactive-section minor-imagery-detail waite-minor-meanings-detail suit-${suit.id}`}>
      <div className="interactive-heading"><span>Arthur Edward Waite · 1910</span><h2>选一张小阿卡纳，再切换正位或逆位</h2></div>
      <nav className="minor-suit-selector" aria-label="选择小阿卡纳牌义花色">
        {data.suits.map((item) => <button className={`${item.id} ${item.id === suitId ? 'active' : ''}`} onClick={() => chooseSuit(item.id)} aria-pressed={item.id === suitId} key={item.id}><i>{item.mark}</i><span><strong>{item.name_zh}</strong><small>{item.name_en}</small></span></button>)}
      </nav>
      <div className="minor-card-index" aria-label={`选择${suit.name_zh}牌义`}>
        {data.ranks.map((item) => <button className={`${item.kind === '宫廷牌' ? 'court' : ''} ${item.id === rankId ? 'active' : ''}`} onClick={() => setRankId(item.id)} aria-pressed={item.id === rankId} title={`${suit.name_zh}${item.name_zh}`} key={item.id}><img src={imagePath(suit, item)} alt="" loading="lazy" /><span>{item.name_zh}</span></button>)}
      </div>
      <div className="waite-meaning-workbench waite-minor-workbench">
        <figure><img className={orientation === 'reversed' ? 'reversed' : ''} src={imagePath(suit, rank)} alt={`${suit.name_zh}${rank.name_zh}${orientation === 'reversed' ? '逆位' : '正位'}牌面`} /></figure>
        <article>
          <header><small>{suit.mark}</small><div><h3>{suit.name_zh}{rank.name_zh}</h3><p>{rank.name_en} of {suit.name_en}</p></div></header>
          <nav className="waite-orientation-selector"><button className={orientation === 'upright' ? 'active' : ''} onClick={() => setOrientation('upright')}>正位</button><button className={orientation === 'reversed' ? 'active' : ''} onClick={() => setOrientation('reversed')}>逆位</button></nav>
          <section className="waite-keywords">{keywords.map((keyword) => <span key={keyword}>{keyword}</span>)}</section>
          <nav className="waite-meaning-pager"><button onClick={() => selectRelative(-1)}>← 上一张</button><span>{rankIndex + 1} / 14</span><button onClick={() => selectRelative(1)}>下一张 →</button></nav>
        </article>
      </div>
    </section>
  )
}

function TarotSpreadsDetail() {
  const data = tarotDatasets.spreadStructures
  const deck = tarotDatasets.deckStructure
  const majorMeanings = tarotDatasets.waiteMajorMeanings
  const minorImages = tarotDatasets.minorArcanaImages
  const minorMeanings = tarotDatasets.waiteMinorMeanings
  const fixedExamples = [data.fixed_example, data.fixed_mixed_example]
  const requestedParams = new URLSearchParams(window.location.hash.split('?')[1] || '')
  const requestedSpreadId = requestedParams.get('spread')
  const requestedVersionId = requestedParams.get('version')
  const requestedPosition = Number(requestedParams.get('position'))
  const requestedExampleId = requestedParams.get('example')
  const requestedExamplePosition = Number(requestedParams.get('examplePosition'))
  const initialSpread = data.spreads.find((item) => item.id === requestedSpreadId) || data.spreads.find((item) => item.id === 'celtic')
  const initialExample = fixedExamples.find((item) => item.id === requestedExampleId) || fixedExamples[0]
  const [spreadId, setSpreadId] = useState(initialSpread.id)
  const [versionId, setVersionId] = useState(data.celtic_versions.some((item) => item.id === requestedVersionId) ? requestedVersionId : 'waite_1910')
  const [activeNumber, setActiveNumber] = useState(Number.isInteger(requestedPosition) && requestedPosition >= 1 && requestedPosition <= initialSpread.card_count ? requestedPosition : 1)
  const [exampleId, setExampleId] = useState(initialExample.id)
  const [examplePosition, setExamplePosition] = useState(Number.isInteger(requestedExamplePosition) && requestedExamplePosition >= 1 && requestedExamplePosition <= initialExample.cards.length ? requestedExamplePosition : 1)
  const spread = data.spreads.find((item) => item.id === spreadId)
  const version = data.celtic_versions.find((item) => item.id === versionId)
  const labels = spreadId === 'celtic' ? version.positions : spread.positions
  const fixedExample = fixedExamples.find((item) => item.id === exampleId)
  const examplePositions = data.spreads.find((item) => item.id === fixedExample.spread_id).positions
  const exampleCards = fixedExample.cards.map((item) => {
    if (!item.suit_id) {
      const card = majorMeanings.cards.find((entry) => entry.number === item.card_number)
      return { ...item, name: card.name_zh, image: card.image, keywords: card[item.orientation], route: `/topic/tarot/major-arcana-images?card=${encodeURIComponent(card.number)}&mode=${item.orientation}`, position: examplePositions[item.position_number - 1] }
    }
    const suit = minorImages.suits.find((entry) => entry.id === item.suit_id)
    const rank = minorImages.ranks.find((entry) => entry.id === item.rank_id)
    return { ...item, name: `${suit.name_zh}${rank.name_zh}`, image: `${suit.name_en}${rank.file_number}.png`, keywords: minorMeanings.meanings[suit.id][rank.id][item.orientation], route: `/topic/tarot/minor-arcana-images?suit=${encodeURIComponent(suit.id)}&rank=${encodeURIComponent(rank.id)}&mode=${item.orientation}`, position: examplePositions[item.position_number - 1] }
  })
  const activeExample = exampleCards.find((item) => item.position_number === examplePosition)
  const replaceSpreadUrl = (nextSpreadId, nextVersionId, nextPosition, nextExampleId, nextExamplePosition) => window.history.replaceState(null, '', `#/topic/tarot/spread-structures?spread=${encodeURIComponent(nextSpreadId)}&version=${encodeURIComponent(nextVersionId)}&position=${nextPosition}&example=${encodeURIComponent(nextExampleId)}&examplePosition=${nextExamplePosition}`)
  const chooseSpread = (id) => { setSpreadId(id); setActiveNumber(1); replaceSpreadUrl(id, versionId, 1, exampleId, examplePosition) }
  const chooseVersion = (id) => { setVersionId(id); replaceSpreadUrl(spreadId, id, activeNumber, exampleId, examplePosition) }
  const choosePosition = (position) => { setActiveNumber(position); replaceSpreadUrl(spreadId, versionId, position, exampleId, examplePosition) }
  const chooseExample = (id) => { setExampleId(id); setExamplePosition(1); replaceSpreadUrl(spreadId, versionId, activeNumber, id, 1) }
  const chooseExamplePosition = (position) => { setExamplePosition(position); replaceSpreadUrl(spreadId, versionId, activeNumber, exampleId, position) }

  return (
    <section className="interactive-section tarot-spreads-detail">
      <div className="interactive-heading"><span>1 · 3 · 5 · 10 张</span><h2>选择牌阵，查看牌位排列</h2></div>
      <nav className="tarot-spread-selector" aria-label="选择牌阵结构">
        {data.spreads.map((item) => <button className={item.id === spreadId ? 'active' : ''} onClick={() => chooseSpread(item.id)} aria-pressed={item.id === spreadId} key={item.id}><i>{item.card_count}</i><span><strong>{item.label}</strong><small>{item.latin}</small></span></button>)}
      </nav>
      {spreadId === 'celtic' && <nav className="tarot-spread-version-selector" aria-label="选择凯尔特十字版本">{data.celtic_versions.map((item) => <button className={item.id === versionId ? 'active' : ''} onClick={() => chooseVersion(item.id)} aria-pressed={item.id === versionId} key={item.id}>{item.label}</button>)}</nav>}
      <div className="tarot-spread-version-note"><b>{spreadId === 'celtic' ? version.label : spread.version_label}</b><span>{spreadId === 'celtic' ? version.version_note : spread.version_note}</span></div>
      <div className={`tarot-spread-workbench ${spreadId}`}>
        <div className={spreadId === 'celtic' ? 'tarot-celtic-board' : `tarot-sequence-board count-${spread.card_count}`}>
          {labels.map((label, index) => <button className={`slot-${index + 1} ${activeNumber === index + 1 ? 'active' : ''}`} onClick={() => choosePosition(index + 1)} key={`${versionId}-${index}`}><i>{index + 1}</i><strong>{label}</strong></button>)}
        </div>
        <article className="tarot-position-card"><small>第 {activeNumber} 位</small><strong>{labels[activeNumber - 1]}</strong><span>{spread.label}</span></article>
      </div>
      {spreadId === 'celtic' && (
        <section className="tarot-celtic-position-comparison">
          <div className="interactive-heading"><span>同一编号 · 三种命名</span><h2>第 {activeNumber} 位在三个版本里怎么写</h2></div>
          <div>{data.celtic_versions.map((item) => <button className={item.id === versionId ? 'active' : ''} onClick={() => chooseVersion(item.id)} aria-pressed={item.id === versionId} key={item.id}><small>{item.label}</small><strong>{item.positions[activeNumber - 1]}</strong><i aria-hidden="true">{item.id === versionId ? '当前' : '切换 →'}</i></button>)}</div>
        </section>
      )}
      <section className="tarot-fixed-example">
        <div className="interactive-heading"><span>固定三张牌</span><h2>牌位与单牌怎样对应</h2></div>
        <nav className="tarot-example-selector" aria-label="选择固定牌例">
          {fixedExamples.map((item) => <button className={item.id === exampleId ? 'active' : ''} onClick={() => chooseExample(item.id)} aria-pressed={item.id === exampleId} key={item.id}>{item.short_label}</button>)}
        </nav>
        <div className="tarot-fixed-example-board">
          <div>
            {exampleCards.map((item) => (
              <button className={item.position_number === examplePosition ? 'active' : ''} onClick={() => chooseExamplePosition(item.position_number)} aria-pressed={item.position_number === examplePosition} key={item.position_number}>
                <small>{item.position_number} · {item.position}</small>
                <img className={item.orientation === 'reversed' ? 'reversed' : ''} src={`${deck.image_set.base_path}${item.image}`} alt={`${item.name}${item.orientation === 'reversed' ? '逆位' : '正位'}牌面`} loading="lazy" />
                <strong>{item.name}</strong>
                <span>{item.orientation === 'reversed' ? '逆位' : '正位'}</span>
              </button>
            ))}
          </div>
          <article>
            <small>第 {activeExample.position_number} 位 · {activeExample.position}</small>
            <strong>{activeExample.name}</strong>
            <span>{activeExample.orientation === 'reversed' ? '逆位' : '正位'}</span>
            <p>{activeExample.keywords.slice(0, 4).map((keyword) => <i key={keyword}>{keyword}</i>)}</p>
            <button onClick={() => { window.location.hash = activeExample.route }}>查看这张牌 <i aria-hidden="true">→</i></button>
          </article>
        </div>
      </section>
    </section>
  )
}

function TaiyiClassicalSourcesDetail() {
  const data = taiyiDatasets.classicalSourcesMap
  const [workId, setWorkId] = useState(data.works[0].id)
  const work = data.works.find((item) => item.id === workId) || data.works[0]

  return (
    <section className="interactive-section taiyi-sources-detail">
      <div className="interactive-heading"><span>底本 → 连接文本 → 锁定实现 → 项目处理</span><h2>先辨认一条知识来自哪一层，再讨论它说了什么</h2></div>
      <div className="taiyi-source-ladder">
        {data.source_ladder.map((item, index) => <Fragment key={item.id}><article><i>{item.index}</i><small>{item.role}</small><strong>{item.name}</strong><p>{item.strength}</p><footer>{item.limit}</footer></article>{index < data.source_ladder.length - 1 && <b aria-hidden="true">→</b>}</Fragment>)}
      </div>

      <div className="knowledge-block taiyi-source-works">
        <div className="interactive-heading"><span>五组古籍 + 一份现代实现</span><h2>每份材料只承担它能够证明的那一层</h2></div>
        <nav aria-label="选择太乙来源材料">
          {data.works.map((item) => <button className={item.id === workId ? 'active' : ''} onClick={() => setWorkId(item.id)} aria-pressed={item.id === workId} key={item.id}><small>{item.period}</small><strong>{item.name}</strong><span>{item.current_role}</span></button>)}
        </nav>
        <article>
          <header><small>{work.identity_status}</small><strong>{work.name}</strong><b>{work.attribution}</b></header>
          <p>{work.evidence}</p>
          <div>{work.current_coverage.map((item) => <span key={item}>{item}</span>)}</div>
          <footer><b>使用边界</b>{work.boundary}</footer>
        </article>
      </div>

      <div className="knowledge-block taiyi-source-routes">
        <div className="interactive-heading"><span>现有节点怎样回到来源</span><h2>书名、规则页和代码函数之间保留可追踪路径</h2></div>
        <div>{data.evidence_routes.map((route) => <article key={route.id}><header><small>{route.nodes.length} 个对象</small><strong>{route.label}</strong></header><div>{route.nodes.map((node) => <span key={node}>{node}</span>)}</div><section><p><b>古籍层</b>{route.classical_sources.join(' · ')}</p><p><b>实现层</b>{route.implementation_source}</p></section><footer>{route.note}</footer></article>)}</div>
      </div>

      <div className="knowledge-block taiyi-source-rules">
        <div className="interactive-heading"><span>五条处理规则</span><h2>最容易被误写成“版本共识”的地方</h2></div>
        <div>{data.handling_rules.map((item) => <article key={item.label}><strong>{item.label}</strong><small>{item.example}</small><p>{item.handling}</p></article>)}</div>
      </div>
      <div className="taiyi-boundary-grid">{data.reading_boundaries.map((item) => <article key={item.label}><strong>{item.label}</strong><p>{item.note}</p></article>)}</div>
      <p className="reading-note">本页是来源导航，不是完整书目史；未核定作者、年代和底本关系的材料继续明确标为待核验。</p>
    </section>
  )
}

function TaiyiMinuteCountDetail() {
  const data = taiyiDatasets.minuteCount
  const [methodId, setMethodId] = useState(1)
  const method = data.fixed_methods.find((item) => item.method === methodId) || data.fixed_methods[1]

  return (
    <section className="interactive-section taiyi-minute-detail">
      <div className="interactive-heading"><span>现代扩展 · ji_style 4</span><h2>一分钟怎样进入分干支、积分数与七十二局</h2></div>
      <p className="taiyi-symbol-example">{data.fixed_input}</p>

      <div className="taiyi-minute-identities">{data.identity_layers.map((item) => <article key={item.id}><i>{item.index}</i><header><small>{item.status}</small><strong>{item.name}</strong></header><b>{item.value}</b><p>{item.note}</p></article>)}</div>

      <div className="knowledge-block taiyi-minute-chain">
        <div className="interactive-heading"><span>四步生成链</span><h2>局号输入和阴阳遁输入不是同一条路线</h2></div>
        <div>{data.generation_chain.map((item, index) => <Fragment key={item.id}><article><i>{item.index}</i><small>{item.input}</small><strong>{item.label}</strong><code>{item.formula}</code><b>{item.output}</b><p>{item.note}</p></article>{index < data.generation_chain.length - 1 && <span aria-hidden="true">→</span>}</Fragment>)}</div>
      </div>

      <div className="knowledge-block taiyi-minute-methods">
        <div className="interactive-heading"><span>固定00:00 · method 0—3</span><h2>四个名字在分计里实际只形成两组积分</h2></div>
        <nav aria-label="选择分计实现分支">{data.fixed_methods.map((item) => <button className={item.method === methodId ? 'active' : ''} onClick={() => setMethodId(item.method)} aria-pressed={item.method === methodId} key={item.method}><small>method {item.method}</small><strong>{item.label}</strong><span>{item.board}</span></button>)}</nav>
        <article><header><small>{method.status}</small><strong>{method.label}</strong><b>{method.board}</b></header><div><span>分干支<b>{method.minute_ganzhi}</b></span><i>校正</i><span>积分数<b>{method.accumulated.toLocaleString()}</b></span><i>mod 72</i><span>局号<b>{method.board_number}</b></span><i>→</i><span>太乙宫<b>{method.taiyi_palace}</b></span></div><footer>积分 mod 60 = {method.remainder60}；具名标签只按锁定接口显示，不证明古籍版本等价。</footer></article>
      </div>

      <div className="knowledge-block taiyi-minute-sequence">
        <div className="interactive-heading"><span>00:00 → 01:01</span><h2>原数跨小时跳跃，两个余数周期仍逐分前进</h2></div>
        <div>{data.minute_sequence.map((item, index) => <article key={item.time}><header><small>{String(index + 1).padStart(2, '0')}</small><strong>{item.time}</strong><b>{item.minute_ganzhi}</b></header><div><span>积分数<strong>{item.accumulated.toLocaleString()}</strong></span><span>第<strong>{item.board_number}</strong>局</span></div><footer>{item.transition}</footer></article>)}</div>
      </div>

      <div className="knowledge-block taiyi-minute-dun">
        <div className="interactive-heading"><span>另一条定遁旁路</span><h2>分干支负责校正积分，却不负责决定阴阳遁</h2></div>
        <div>{data.dun_routes.map((item) => <article key={item.half}><header><small>{item.status}</small><strong>{item.half}</strong><b>{item.selector}</b></header><p>{item.first_group}</p><p>{item.reverse_group}</p><footer>分干支：{item.minute_ganzhi_role}</footer></article>)}</div>
      </div>

      <div className="knowledge-block taiyi-minute-boundaries">
        <div className="interactive-heading"><span>五个下游边界</span><h2>能出局不等于纪元、五子元和日界已经闭合</h2></div>
        <div>{data.downstream_boundaries.map((item) => <article key={item.label}><header><strong>{item.label}</strong><small>{item.status}</small></header><p>{item.implementation}</p><footer>{item.effect}</footer></article>)}</div>
      </div>

      <div className="knowledge-block taiyi-minute-differences">
        <div className="interactive-heading"><span>三处来源差异</span><h2>明确它是什么，也明确它还不是什么</h2></div>
        <div>{data.source_differences.map((item) => <article key={item.label}><strong>{item.label}</strong><section><span><small>古籍层</small>{item.classical}</span><i>≠</i><span><small>实现层</small>{item.implementation}</span></section><p>{item.handling}</p></article>)}</div>
      </div>
      <div className="taiyi-boundary-grid">{data.reading_boundaries.map((item) => <article key={item.label}><strong>{item.label}</strong><p>{item.note}</p></article>)}</div>
      <p className="reading-note">页面只复核锁定程序的分钟入口；不接受真人时间，不输出分钟级吉凶或行动建议。</p>
    </section>
  )
}

