function TaiyiBasesBlessingsDetail() {
  const data = taiyiDatasets.threeBasesFiveBlessingsCycles
  const [objectId, setObjectId] = useState(data.objects[0].id)
  const [methodId, setMethodId] = useState(1)
  const object = data.objects.find((item) => item.id === objectId)
  const method = data.method_results.find((item) => item.method === methodId)
  const fixedPosition = data.method_results[1].positions[object.name].split(' · ')[0]

  return <section className="interactive-section taiyi-bases-detail">
    <div className="interactive-heading"><span>积年入口 ≠ 局数入口</span><h2>三基同名成组，周期却不相同；五福又走五宫长周期</h2></div>
    <p className="taiyi-symbol-example">{data.fixed_input}</p>

    <nav className="taiyi-bases-tabs" aria-label="选择三基与五福对象">{data.objects.map((item) => <button className={item.id === objectId ? 'active' : ''} onClick={() => setObjectId(item.id)} aria-pressed={item.id === objectId} key={item.id}><strong>{item.name}</strong><small>{item.input}</small></button>)}</nav>
    <article className="taiyi-bases-panel"><header><small>{object.input}</small><strong>{object.name}</strong><b>{object.implementation_cycle}</b></header><p>{object.classical_anchor}</p><div>{object.implementation_order.map((position, index) => <span className={position === fixedPosition ? 'active' : ''} key={`${position}-${index}`}><small>{index + 1}</small><strong>{position}</strong></span>)}</div><footer><span>原典／实现差异</span>{object.difference}</footer></article>

    <div className="knowledge-block taiyi-bases-paths"><div className="interactive-heading"><span>两条输入路径</span><h2>先辨对象读取积年，还是读取模72后的局数</h2></div><div>{data.input_paths.map((path) => <article key={path.label}><strong>{path.label}</strong><div>{path.nodes.map((node, index) => <Fragment key={node}><span>{node}</span>{index < path.nodes.length - 1 && <i>→</i>}</Fragment>)}</div><p>{path.note}</p></article>)}</div></div>

    <div className="knowledge-block taiyi-bases-runtime"><div className="interactive-heading"><span>固定年计 · method 0—3</span><h2>同为十三局，五福仍可能不同</h2></div>
      <nav className="taiyi-bases-methods" aria-label="选择三基与五福的积年分支">{data.method_results.map((item) => <button className={item.method === methodId ? 'active' : ''} onClick={() => setMethodId(item.method)} aria-pressed={item.method === methodId} key={item.method}><small>method {item.method}</small><strong>{item.label}</strong><span>{item.board}</span></button>)}</nav>
      <article className="taiyi-bases-result"><header><small>{method.accumulated.toLocaleString()}积年</small><strong>{method.board}</strong><b>{method.status}</b></header><div>{Object.entries(method.positions).map(([name, position]) => <span key={name}><small>{name}</small><strong>{position}</strong></span>)}</div></article>
    </div>

    <div className="knowledge-block taiyi-bases-comparisons"><div className="interactive-heading"><span>为什么要保留两条入口</span><h2>相同局数、相同单项与完全相同，是三种情况</h2></div><div>{data.comparison_examples.map((item) => <article key={item.label}><strong>{item.label}</strong><section><span>{item.left}</span><i>↔</i><span>{item.right}</span></section><b>{item.shared}</b><p>{item.note}</p></article>)}</div></div>
    <div className="knowledge-block taiyi-interface-diff"><div className="interactive-heading"><span>来源与实现边界</span><h2>四处不能用“三基五福”一个总称带过</h2></div><div>{data.source_differences.map((item) => <article key={item.label}><strong>{item.label}</strong><p>{item.evidence}</p><small>{item.handling}</small></article>)}</div></div>
    <div className="taiyi-boundary-grid">{data.reading_boundaries.map((item) => <article key={item.label}><strong>{item.label}</strong><p>{item.note}</p></article>)}</div>
    <p className="reading-note">页面只比较周期、输入路径与固定样本；不展示服方、进献、灾异或现实行动判断。</p>
  </section>
}

