function TaiyiYinyangParityDetail() {
  const data = taiyiDatasets.palaceYinyangCountParity
  const [matrixId, setMatrixId] = useState(data.matrix[0].id)
  const [methodId, setMethodId] = useState(1)
  const matrixItem = data.matrix.find((item) => item.id === matrixId)
  const method = data.method_results.find((item) => item.method === methodId)

  return <section className="interactive-section taiyi-parity-detail">
    <div className="interactive-heading"><span>宫位属性 × 算数奇偶</span><h2>两条输入轴交叉后，才得到重阳、重阴或和型</h2></div>
    <p className="taiyi-symbol-example">{data.fixed_input}</p>

    <div className="taiyi-parity-axes">
      <section><header><small>轴一</small><strong>太乙宫阴阳</strong></header><div>{data.palace_groups.map((item) => <article key={item.id}><b>{item.name}</b><p>{item.palaces.join(' · ')}</p><span>{item.positions.join(' · ')}</span><small>{item.note}</small></article>)}</div></section>
      <section><header><small>轴二</small><strong>主客算奇偶</strong></header><div>{data.parity_axis.map((item) => <article key={item.id}><b>{item.name}数</b><p>{item.rule}</p><span>固定例见 {item.examples.join('、')}</span></article>)}</div></section>
    </div>

    <div className="knowledge-block taiyi-parity-matrix"><div className="interactive-heading"><span>卷二四格结构</span><h2>宫阴阳不是宫数奇偶</h2></div>
      <nav aria-label="选择太乙宫阴阳与算数奇偶组合">{data.matrix.map((item) => <button className={`${item.id === matrixId ? 'active' : ''} ${item.tone}`} onClick={() => setMatrixId(item.id)} aria-pressed={item.id === matrixId} key={item.id}><small>{item.palace_nature}</small><i>×</i><small>{item.count_parity}数</small><strong>{item.public_state}</strong></button>)}</nav>
      <article className="taiyi-parity-matrix-panel"><header><small>原典结构名称</small><strong>{matrixItem.classical_state}</strong><b>{matrixItem.palace_nature} × {matrixItem.count_parity}数</b></header><p>{matrixItem.implementation_note}</p></article>
    </div>

    <div className="knowledge-block taiyi-parity-runtime"><div className="interactive-heading"><span>固定年计 · method 0—3</span><h2>太乙都在阴宫，主客算奇偶仍会改变组合</h2></div>
      <nav className="taiyi-parity-methods" aria-label="选择阴阳和不和的积年分支">{data.method_results.map((item) => <button className={item.method === methodId ? 'active' : ''} onClick={() => setMethodId(item.method)} aria-pressed={item.method === methodId} key={item.method}><small>method {item.method}</small><strong>{item.label}</strong><span>{item.board}</span></button>)}</nav>
      <article className="taiyi-parity-result"><header><small>{method.accumulated.toLocaleString()}积年</small><strong>太乙{method.taiyi_palace}宫 · {method.taiyi_position} · {method.palace_nature}</strong><b>{method.status}</b></header><div><section><small>主算</small><strong>{method.host_count} · {method.host_parity}数</strong><b>{method.host_state}</b><span>{method.host_basis}</span></section><section><small>客算</small><strong>{method.guest_count} · {method.guest_parity}数</strong><b>{method.guest_state}</b><span>{method.guest_basis}</span></section></div><footer>定算不在锁定tui_danger的输入里，页面不补造第三条结果。</footer></article>
    </div>

    <div className="knowledge-block taiyi-parity-differences"><div className="interactive-heading"><span>五处边界</span><h2>结构可以复核，断语不进入阅读页面</h2></div><div>{data.layer_differences.map((item) => <article key={item.label}><strong>{item.label}</strong><section><span><small>卷二</small>{item.classical}</span><i>≠</i><span><small>锁定实现</small>{item.implementation}</span></section><p>{item.handling}</p></article>)}</div></div>
    <div className="taiyi-boundary-grid">{data.reading_boundaries.map((item) => <article key={item.label}><strong>{item.label}</strong><p>{item.note}</p></article>)}</div>
    <p className="reading-note">页面只展示宫位阴阳、算数奇偶与四格结构；不接收真人时间，不展示厄会、火水、胜负、灾害或行动判断。</p>
  </section>
}

