    <nav className="taiyi-five-essence-tabs" aria-label="选择十精周期对象">{data.objects.map((item) => <button className={`${item.id === objectId ? 'active' : ''} ${item.tone}`} onClick={() => setObjectId(item.id)} aria-pressed={item.id === objectId} key={item.id}><small>{item.status}</small><strong>{item.name}</strong><span>{item.classical_cycle} · {item.domain}</span></button>)}</nav>
