function TaiyiModesDetail() {
  const data = taiyiDatasets.calculationModesVersionsFixedExample
  const [timeId, setTimeId] = useState(data.time_granularities[0].id)
  const [methodId, setMethodId] = useState(data.method_branches[1].id)
  const time = data.time_granularities.find((item) => item.id === timeId)
  const method = data.method_branches.find((item) => item.id === methodId)
  return <section className="interactive-section taiyi-modes-detail">
    <div className="interactive-heading"><span>两条选择轴 · 固定输入</span><h2>时间粒度回答“累计到哪一层”，积年分支回答“从哪个常数起算”</h2></div>
    <p className="taiyi-symbol-example">{data.fixed_input}</p>
    <div className="taiyi-mode-block"><header><small>轴一 · ji_style 0—4</small><h3>五种普通式盘时间粒度</h3></header><nav aria-label="选择太乙时间粒度">{data.time_granularities.map((item) => <button className={item.id === timeId ? 'active' : ''} onClick={() => setTimeId(item.id)} aria-pressed={item.id === timeId} key={item.id}><small>{item.index}</small><strong>{item.label}</strong><span>{item.board}</span></button>)}</nav><article><header><small>{time.source_status}</small><strong>{time.label}</strong><b>{time.board} · 太乙{time.palace}宫</b></header><div><span>{time.accumulated_label}</span><strong>{time.accumulated.toLocaleString()}</strong></div><section><p><b>原典锚点</b>{time.classical_anchor}</p><p><b>锁定实现</b>{time.implementation_note}</p></section></article></div>
    <div className="taiyi-life-branch"><small>CLI中的第六个mode</small><strong>命法不是第六种普通式盘粒度</strong><div><span>CLI life = {data.life_branch.mapped_index}</span><i>→</i><span>{data.life_branch.actual_route}</span></div><p>{data.life_branch.boundary}</p></div>
    <div className="knowledge-block taiyi-method-block"><div className="interactive-heading"><span>轴二 · method 0—3</span><h2>四个具名实现分支在同一固定年计下比较</h2></div><nav aria-label="选择太乙积年分支">{data.method_branches.map((item) => <button className={item.id === methodId ? 'active' : ''} onClick={() => setMethodId(item.id)} aria-pressed={item.id === methodId} key={item.id}><small>{item.index}</small><strong>{item.label}</strong><span>余 {item.remainder}</span></button>)}</nav><article><header><small>{method.status}</small><strong>{method.label}</strong><b>{method.board}</b></header><div><span>起算常数 <b>{method.base_constant.toLocaleString()}</b></span><i>＋1552</i><span>积年数 <b>{method.accumulated.toLocaleString()}</b></span><i>mod 72</i><span>余数 <b>{method.remainder}</b></span></div><p>太乙落{method.palace}宫 · {method.position}</p></article></div>
    <div className="knowledge-block taiyi-interface-diff"><div className="interactive-heading"><span>接口边界</span><h2>四处不能被“六计四法”一句话抹平的差异</h2></div><div>{data.interface_differences.map((item) => <article key={item.label}><strong>{item.label}</strong><p>{item.evidence}</p><small>{item.handling}</small></article>)}</div></div>
    <div className="taiyi-boundary-grid">{data.reading_boundaries.map((item) => <article key={item.label}><strong>{item.label}</strong><p>{item.note}</p></article>)}</div>
    <p className="reading-note">页面只切换固定样本；不推荐计法，不接收个人出生信息。</p>
  </section>
}

