function WesternAspectsDetail() {
  const data = westernAstrologyDatasets.aspectsOrbsAndMovement
  const [aspectId, setAspectId] = useState('sextile')
  const [movementId, setMovementId] = useState('applying')
  const aspect = data.major_aspects.find((item) => item.id === aspectId) || data.major_aspects[0]
  const movement = data.movement_states.find((item) => item.id === movementId) || data.movement_states[0]

  function fixedSeparation(target, state, next = false) {
    if (state === 'exact') {
      if (!next) return target
      return target === 180 ? 179 : target + 1
    }
    const error = state === 'applying' ? (next ? 2 : 3) : (next ? 4 : 3)
    if (target === 180) return target - error
    return target + error
  }

  const currentSeparation = fixedSeparation(aspect.angle, movement.id)
  const nextSeparation = fixedSeparation(aspect.angle, movement.id, true)
  const currentError = Math.abs(currentSeparation - aspect.angle)
  const nextError = Math.abs(nextSeparation - aspect.angle)

  return <section className="interactive-section astrology-aspects-detail">
    <div className="interactive-heading"><span>固定几何观察</span><h2>先选目标角，再看误差正在缩小还是扩大</h2></div>
    <nav className="astrology-aspect-selector" aria-label="选择主相位">{data.major_aspects.map((item) => <button className={item.id === aspect.id ? 'active' : ''} onClick={() => setAspectId(item.id)} aria-pressed={item.id === aspect.id} key={item.id}><b>{item.angle}°</b><span><strong>{item.name}</strong><small>{item.english}</small></span></button>)}</nav>
    <nav className="astrology-movement-selector" aria-label="选择相位运动状态">{data.movement_states.map((item) => <button className={item.id === movement.id ? 'active' : ''} onClick={() => setMovementId(item.id)} aria-pressed={item.id === movement.id} key={item.id}><strong>{item.label}</strong><small>{item.rule}</small></button>)}</nav>

    <div className="astrology-aspect-stage">
      <article><small>目标角</small><strong>{aspect.angle}°</strong><span>{aspect.name} · {aspect.source_label}</span></article>
      <div className="astrology-orb-flow"><span><small>当前角距离</small><b>{currentSeparation}°</b><i>误差 {currentError}°</i></span><em>→</em><span><small>固定下一步</small><b>{nextSeparation}°</b><i>误差 {nextError}°</i></span></div>
      <aside className={movement.id}><small>运动状态</small><strong>{movement.label}</strong><p>{movement.rule}</p></aside>
    </div>

    <div className="knowledge-block astrology-geometry-steps"><div className="interactive-heading"><span>四层计算</span><h2>角距离、目标角、容许度和运动方向各自回答不同问题</h2></div><div>{data.geometry_steps.map((step, index) => <article key={step.id}><i>{index + 1}</i><strong>{step.label}</strong><p>{step.formula}</p></article>)}</div></div>

    <div className="knowledge-block astrology-minor-aspects"><div className="interactive-heading"><span>实现补充</span><h2>flatlib另保存八个次要相位角，本页只登记角度</h2></div><div>{data.minor_aspect_angles.map((angle) => <span key={angle}><b>{angle}°</b><small>次要角</small></span>)}</div></div>

    <div className="knowledge-block astrology-aspect-differences"><div className="interactive-heading"><span>来源分层</span><h2>共同结构可以合并，参数与解释不能混成唯一表</h2></div><div>{data.source_differences.map((item) => <article key={item.field}><strong>{item.field}</strong><p><small>正文来源</small>{item.fortune_telling_skills}</p><p><small>实现来源</small>{item.flatlib}</p><span>{item.handling}</span></article>)}</div></div>

    <div className="astrology-source-boundaries">{data.reading_boundaries.map((item, index) => <p key={item}><i>{String(index + 1).padStart(2, '0')}</i>{item}</p>)}</div>
  </section>
}

