function WesternDignitiesDetail({ openCard }) {
  const data = westernAstrologyDatasets.essentialDignities
  const [exampleId, setExampleId] = useState('sun-aries')
  const example = data.fixed_examples.find((item) => item.id === exampleId) || data.fixed_examples[0]
  const sign = data.signs.find((item) => item.id === example.sign) || data.signs[0]
  const triplicity = data.triplicities.find((item) => item.signs.includes(sign.id))
  const term = sign.egyptian_terms.find((item) => item[1] <= example.degree && example.degree < item[2])
  const faceIndex = Math.min(2, Math.floor(example.degree / 10))
  const activeTriplicity = example.sect === 'day' ? triplicity.day : triplicity.night
  const holders = {
    ruler: sign.ruler,
    exalt: sign.exalt,
    triplicity: activeTriplicity,
    term: term?.[0],
    face: sign.faces[faceIndex],
  }
  const matchedLayers = data.dignity_layers.filter((layer) => holders[layer.id] === example.planet)
  const exileMatch = sign.exile === example.planet
  const fallMatch = sign.fall === example.planet
  const peregrineMatch = matchedLayers.length === 0 && !exileMatch && !fallMatch

  function planetName(id) {
    return id ? data.planet_names[id] : '无登记'
  }

  function layerDetail(layer) {
    if (layer.id === 'ruler') return `${sign.name}的守护星`
    if (layer.id === 'exalt') return sign.exalt_degree == null ? '本星座没有登记擢升对象' : `来源另标锚点 ${sign.exalt_degree}°`
    if (layer.id === 'triplicity') return `${triplicity.element}象 · ${example.sect === 'day' ? '日间主' : '夜间主'}；合作主 ${planetName(triplicity.participant)}`
    if (layer.id === 'term') return `埃及界 ${term?.[1]}°—${term?.[2]}°`
    return `迦勒底面 ${faceIndex * 10}°—${(faceIndex + 1) * 10}°`
  }

  return <section className="interactive-section astrology-dignities-detail">
    <div className="interactive-heading"><span>固定位置查表</span><h2>对象、星座、昼夜与度数依次进入五层规则</h2></div>
    <nav className="astrology-dignity-examples" aria-label="选择固定尊贵示例">{data.fixed_examples.map((item) => <button className={item.id === example.id ? 'active' : ''} onClick={() => setExampleId(item.id)} aria-pressed={item.id === example.id} key={item.id}><strong>{item.label}</strong><small>{item.sect === 'day' ? '日间' : '夜间'}固定例</small></button>)}</nav>

    <div className="astrology-dignity-stage">
      <header><small>当前固定位置</small><b>{`${sign.symbol}\uFE0E`}</b><strong>{planetName(example.planet)}</strong><span>{sign.name} {example.degree}° · {example.sect === 'day' ? '日间' : '夜间'}</span></header>
      <div className="astrology-dignity-layers">{data.dignity_layers.map((layer) => {
        const holder = holders[layer.id]
        const matched = holder === example.planet
        return <article className={matched ? 'matched' : ''} key={layer.id}><i>{layer.source_points > 0 ? `+${layer.source_points}` : layer.source_points}</i><small>{layer.name}</small><strong>{planetName(holder)}</strong><p>{layerDetail(layer)}</p>{matched && <em>当前行星命中</em>}</article>
      })}</div>
    </div>

    <div className="astrology-dignity-result"><strong>{matchedLayers.length ? `命中 ${matchedLayers.length} 层正尊贵` : '没有命中正尊贵'}</strong><span>{matchedLayers.length ? matchedLayers.map((item) => item.name).join(' · ') : '继续检查落陷、弱势与游走'}</span><p>这里保留逐层身份，不把分值相加成最终强弱。</p></div>

    <div className="knowledge-block astrology-debility-board"><div className="interactive-heading"><span>另一组状态</span><h2>落陷、弱势和游走不是五层尊贵中的第六至第八级</h2></div><div>
      <article className={exileMatch ? 'matched' : ''}><i>-5</i><strong>落陷</strong><span>{planetName(sign.exile)}</span><p>{exileMatch ? '当前行星命中' : `当前星座登记：${planetName(sign.exile)}`}</p></article>
      <article className={fallMatch ? 'matched' : ''}><i>-4</i><strong>弱势</strong><span>{planetName(sign.fall)}</span><p>{fallMatch ? `当前行星命中；来源锚点 ${sign.fall_degree}°` : sign.fall ? `来源锚点 ${sign.fall_degree}°` : '本星座没有登记弱势对象'}</p></article>
      <article className={peregrineMatch ? 'matched' : ''}><i>0</i><strong>游走</strong><span>{peregrineMatch ? planetName(example.planet) : '未命中'}</span><p>没有正尊贵，且不以落陷／弱势字段代替游走检查。</p></article>
    </div></div>

    <div className="knowledge-block astrology-dignity-reading"><div className="interactive-heading"><span>阅读顺序</span><h2>每加一项输入，只开启对应的一层规则</h2></div><div>{data.reading_steps.map((item, index) => <article key={item.label}><i>{String(index + 1).padStart(2, '0')}</i><strong>{item.label}</strong><p>{item.note}</p></article>)}</div></div>

    <div className="knowledge-block astrology-triplicity-register"><div className="interactive-heading"><span>Dorotheus三分主</span><h2>同一元素组还要区分日间、夜间与合作角色</h2></div><div>{data.triplicities.map((item) => <article className={item.element === triplicity.element ? 'active' : ''} key={item.element}><strong>{item.element}</strong><small>{item.signs.map((id) => data.signs.find((signItem) => signItem.id === id)?.name).join(' · ')}</small><p><span>日</span>{planetName(item.day)} <span>夜</span>{planetName(item.night)} <span>合作</span>{planetName(item.participant)}</p></article>)}</div></div>

    <div className="knowledge-block astrology-dignity-variants"><div className="interactive-heading"><span>版本参数</span><h2>界表、面表与分值不能静默合并</h2></div><div>{data.variant_register.map((item) => <article key={item.field}><strong>{item.field}</strong><p><small>当前实现默认</small>{item.flatlib_default}</p><p><small>另有支持</small>{item.other_supported.join(' · ')}</p><span>{item.handling}</span></article>)}</div></div>

    <WesternNodeLinks title="这页同时读取星座坐标与盘面昼夜，缺少前置条件就不能完整查表" openCard={openCard} links={[{ id: 'zodiac-signs-and-longitude-coordinate', role: '前置一', title: '十二星座与黄经坐标', note: '确定星座与座内度数' }, { id: 'sect-and-planetary-joys', role: '前置二', title: '教派与喜乐基础关系', note: '确定日间盘或夜间盘' }]} />
    <div className="astrology-source-boundaries">{data.reading_boundaries.map((item, index) => <p key={item}><i>{String(index + 1).padStart(2, '0')}</i>{item}</p>)}</div>
  </section>
}

