function WesternSectJoysDetail() {
  const data = westernAstrologyDatasets.sectAndPlanetaryJoys
  const [sectId, setSectId] = useState('day')
  const [planetId, setPlanetId] = useState('sun')
  const chartSect = data.chart_sects.find((item) => item.id === sectId) || data.chart_sects[0]
  const planet = data.planets.find((item) => item.id === planetId) || data.planets[0]
  const joy = data.joy_houses.find((item) => item.planet === planet.id)
  const planetStatus = planet.sect === 'conditional' ? '待额外条件' : planet.sect === sectId ? '与当前盘教派相符' : '与当前盘教派不相符'

  return <section className="interactive-section astrology-sect-detail">
    <div className="interactive-heading"><span>抽象昼夜观察</span><h2>先确定整张盘的昼夜，再比较行星归属</h2></div>
    <nav className="astrology-chart-sect-selector" aria-label="选择抽象盘面教派">{data.chart_sects.map((item) => <button className={item.id === chartSect.id ? 'active' : ''} onClick={() => setSectId(item.id)} aria-pressed={item.id === chartSect.id} key={item.id}><strong>{item.name}</strong><small>{item.condition}</small><span>{item.english}</span></button>)}</nav>

    <div className={`astrology-sect-horizon ${chartSect.id}`}>
      <section className="day"><small>地平线以上</small><strong>日间组三星</strong><div>{data.planets.filter((item) => item.sect === 'day').map((item) => <button className={item.id === planet.id ? 'selected' : ''} onClick={() => setPlanetId(item.id)} key={item.id}><b>{item.symbol}</b><span>{item.name}</span></button>)}</div></section>
      <div className="astrology-horizon-line"><span>ASC</span><i /><b>{chartSect.id === 'day' ? '☉ 在上方' : '☉ 在下方'}</b><i /><span>DSC</span></div>
      <section className="night"><small>地平线以下</small><strong>夜间组三星</strong><div>{data.planets.filter((item) => item.sect === 'night').map((item) => <button className={item.id === planet.id ? 'selected' : ''} onClick={() => setPlanetId(item.id)} key={item.id}><b>{item.symbol}</b><span>{item.name}</span></button>)}</div></section>
      <aside><button className={planet.id === 'mercury' ? 'selected' : ''} onClick={() => setPlanetId('mercury')}><b>☿</b><strong>水星</strong><small>随条件变化</small></button></aside>
    </div>

    <div className="astrology-sect-result"><article><small>盘面教派</small><strong>{chartSect.name}</strong><p>{chartSect.condition}</p></article><i>×</i><article><small>当前行星</small><strong>{planet.symbol} {planet.name}</strong><p>{planet.sect === 'day' ? '日间行星' : planet.sect === 'night' ? '夜间行星' : '条件型行星'}</p></article><i>→</i><article className={planet.sect === sectId ? 'matched' : planet.sect === 'conditional' ? 'conditional' : ''}><small>关系状态</small><strong>{planetStatus}</strong><p>这里只保存是否相符，不解释吉凶。</p></article></div>

    <div className="knowledge-block astrology-joy-board"><div className="interactive-heading"><span>固定喜乐宫</span><h2>喜乐是七条行星—宫位对应，不等于盘的教派</h2></div><nav aria-label="选择七曜查看喜乐宫">{data.planets.map((item) => <button className={item.id === planet.id ? 'active' : ''} onClick={() => setPlanetId(item.id)} aria-pressed={item.id === planet.id} key={item.id}><b>{item.symbol}</b><span>{item.name}</span><small>{item.joy_house}宫</small></button>)}</nav><div className="astrology-joy-house-grid">{Array.from({length: 12}, (_, index) => index + 1).map((house) => {
        const houseJoy = data.joy_houses.find((item) => item.house === house)
        const housePlanet = data.planets.find((item) => item.id === houseJoy?.planet)
        return <article className={`${house === planet.joy_house ? 'selected' : ''} ${houseJoy ? 'has-joy' : ''}`} key={house}><i>{house}</i>{housePlanet ? <><b>{housePlanet.symbol}</b><strong>{housePlanet.name}</strong></> : <span>—</span>}</article>
      })}</div><p className="astrology-joy-reading"><strong>{planet.name}喜乐于第 {joy.house} 宫</strong><span>{joy.source_theme}</span><small>命中只表示固定对应；本页不继承来源评分。</small></p></div>

    <div className="knowledge-block astrology-sect-layers"><div className="interactive-heading"><span>三个问题</span><h2>盘、行星与宫位分别产生三种关系</h2></div><div>{data.relation_layers.map((item, index) => <article key={item.id}><i>{String(index + 1).padStart(2, '0')}</i><strong>{item.label}</strong><p>{item.question}</p><span>{item.output}</span></article>)}</div></div>

    <div className="knowledge-block astrology-sect-differences"><div className="interactive-heading"><span>来源分层</span><h2>教学简写、实现条件与项目处理分别保存</h2></div><div>{data.source_differences.map((item) => <article key={item.field}><strong>{item.field}</strong><p><small>作者资料</small>{item.author_source}</p><p><small>实现层</small>{item.implementation_source}</p><span>{item.handling}</span></article>)}</div></div>

    <div className="astrology-source-boundaries">{data.reading_boundaries.map((item, index) => <p key={item}><i>{String(index + 1).padStart(2, '0')}</i>{item}</p>)}</div>
  </section>
}

