function WesternLotsDetail({ openCard }) {
  const data = westernAstrologyDatasets.coreLotsAndSectFormulas
  const [sectId, setSectId] = useState('day')
  const [lotId, setLotId] = useState('fortune')
  const lot = data.lots.find((item) => item.id === lotId) || data.lots[0]
  const formula = lot[sectId]
  const results = data.fixed_chart.results[sectId]
  const inputMap = Object.fromEntries(data.fixed_chart.inputs.map((item) => [item.name, item.longitude]))
  const valueMap = { ...inputMap, 福点: results.fortune, 精神点: results.spirit }
  const a = valueMap[formula.a]
  const b = valueMap[formula.b]
  const c = valueMap[formula.c]
  const raw = c + b - a
  const normalized = ((raw % 360) + 360) % 360

  return <section className="interactive-section astrology-lots-detail">
    <div className="interactive-heading"><span>固定黄经公式</span><h2>先定教派，再沿依赖顺序计算</h2></div>
    <div className="astrology-lots-controls">
      <nav aria-label="选择抽象盘面教派"><button className={sectId === 'day' ? 'active' : ''} onClick={() => setSectId('day')} aria-pressed={sectId === 'day'}><strong>日间盘</strong><small>Diurnal</small></button><button className={sectId === 'night' ? 'active' : ''} onClick={() => setSectId('night')} aria-pressed={sectId === 'night'}><strong>夜间盘</strong><small>Nocturnal</small></button></nav>
      <nav aria-label="选择核心Lot">{data.lots.map((item) => <button className={item.id === lot.id ? 'active' : ''} onClick={() => setLotId(item.id)} aria-pressed={item.id === lot.id} key={item.id}><strong>{item.name}</strong><small>{item.english}</small></button>)}</nav>
    </div>

    <div className="astrology-lots-stage">
      <header><small>{sectId === 'day' ? '日间公式' : '夜间公式'}</small><strong>{lot.name}</strong><span>{lot.english}</span><em>依赖层级 {lot.dependency_level}</em></header>
      <div className="astrology-lots-formula"><article><small>C · 投射起点</small><strong>{formula.c}</strong><b>{c}°</b></article><i>＋</i><article><small>B · 距离终点</small><strong>{formula.b}</strong><b>{b}°</b></article><i>−</i><article><small>A · 距离起点</small><strong>{formula.a}</strong><b>{a}°</b></article></div>
      <div className="astrology-lots-result"><small>{formula.expression}</small><p>{c}° ＋ {b}° − {a}° ＝ <b>{raw}°</b></p><i>按360°取模</i><strong>{normalized}°</strong></div>
    </div>

    <div className="knowledge-block astrology-lots-inputs"><div className="interactive-heading"><span>固定输入与结果</span><h2>同一组黄经，只切换公式的教派分支</h2></div><div>{data.fixed_chart.inputs.map((item) => <article key={item.id}><small>{item.name}</small><strong>{item.longitude}°</strong></article>)}</div><div>{data.lots.map((item) => <article className={item.id === lot.id ? 'selected' : ''} key={item.id}><small>{item.name}</small><span>日 {data.fixed_chart.results.day[item.id]}°</span><i>↔</i><span>夜 {data.fixed_chart.results.night[item.id]}°</span></article>)}</div></div>

    <div className="knowledge-block astrology-lots-dependencies"><div className="interactive-heading"><span>两层依赖</span><h2>派生点不能和一级点无序同时计算</h2></div><div>{[1, 2].map((level) => <section key={level}><header><i>0{level}</i><strong>{level === 1 ? '一级点' : '派生点'}</strong></header>{data.lots.filter((item) => item.dependency_level === level).map((item) => <article key={item.id}><small>{item.name}</small><div>{item.depends_on.map((dependency, index) => <span key={dependency}>{index ? <i>＋</i> : null}{dependency}</span>)}</div><strong>{item[sectId].expression}</strong></article>)}</section>)}</div></div>

    <div className="knowledge-block astrology-lots-steps"><div className="interactive-heading"><span>计算顺序</span><h2>四步把对象、公式和结果分开</h2></div><div>{data.calculation_steps.map((item, index) => <article key={item.label}><i>{String(index + 1).padStart(2, '0')}</i><strong>{item.label}</strong><p>{item.note}</p></article>)}</div></div>

    <div className="knowledge-block astrology-lots-inventory"><div className="interactive-heading"><span>实现库存</span><h2>20项软件公式不等于20项已经核清的传统规则</h2></div><div><article><small>flatlib公式</small><strong>{data.implementation_inventory.formula_count}</strong><span>项</span></article><article><small>本页发布</small><strong>{data.implementation_inventory.published_here}</strong><span>项</span></article><p>{data.implementation_inventory.note}</p></div><div>{data.implementation_inventory.dependency_kinds.map((item) => <span key={item}>{item}</span>)}</div></div>

    <div className="knowledge-block astrology-lots-differences"><div className="interactive-heading"><span>来源差异</span><h2>公式形态相近，名称和实现范围仍需分开</h2></div><div>{data.source_differences.map((item) => <article key={item.field}><strong>{item.field}</strong><p><small>作者资料</small>{item.author_source}</p><p><small>flatlib</small>{item.flatlib}</p><span>{item.handling}</span></article>)}</div></div>

    <WesternNodeLinks title="Lots是计算点：先知道盘的昼夜，再把黄经带入公式" openCard={openCard} links={[{ id: 'sect-and-planetary-joys', role: '前置一', title: '教派与喜乐基础关系', note: '选择日间或夜间公式分支' }, { id: 'chart-input-and-coordinate-pipeline', role: '前置二', title: '星盘输入与坐标生成链', note: '理解ASC与对象黄经从哪里来' }]} />
    <div className="astrology-source-boundaries">{data.reading_boundaries.map((item, index) => <p key={item}><i>{String(index + 1).padStart(2, '0')}</i>{item}</p>)}</div>
  </section>
}

