function WesternPredictiveMapDetail({ openCard }) {
  const data = westernAstrologyDatasets.predictiveTechniquesMap
  const [familyId, setFamilyId] = useState('chart-transformation')
  const [techniqueId, setTechniqueId] = useState('annual-profections')
  const [routeId, setRouteId] = useState('annual-activation')
  const family = data.families.find((item) => item.id === familyId) || data.families[0]
  const familyTechniques = family.techniques.map((id) => data.techniques.find((item) => item.id === id)).filter(Boolean)
  const technique = data.techniques.find((item) => item.id === techniqueId) || familyTechniques[0]
  const route = data.fixed_learning_routes.find((item) => item.id === routeId) || data.fixed_learning_routes[0]
  const coverage = data.implementation_coverage.find((item) => item.level === technique.implementation_level)
  const routeCandidates = route.candidates.map((id) => data.techniques.find((item) => item.id === id)).filter(Boolean)
  const chooseFamily = (item) => { setFamilyId(item.id); setTechniqueId(item.techniques[0]) }

  return <section className="interactive-section astrology-predictive-detail">
    <div className="interactive-heading"><span>四个方法家族</span><h2>先问时间怎样进入，再问技术输出什么</h2></div>
    <nav className="astrology-predictive-family-selector" aria-label="选择预测技术家族">{data.families.map((item, index) => <button className={item.id === family.id ? 'active' : ''} onClick={() => chooseFamily(item)} aria-pressed={item.id === family.id} key={item.id}><i>{String(index + 1).padStart(2, '0')}</i><strong>{item.name}</strong><small>{item.techniques.length} 类技术</small></button>)}</nav>
    <nav className="astrology-predictive-technique-selector" aria-label="选择预测技术">{familyTechniques.map((item) => <button className={item.id === technique.id ? 'active' : ''} onClick={() => setTechniqueId(item.id)} aria-pressed={item.id === technique.id} key={item.id}><strong>{item.name}</strong><small>{item.english}</small></button>)}</nav>

    <div className="astrology-predictive-stage">
      <header><small>{family.name}</small><strong>{technique.name}</strong><span>{technique.english}</span><em>{technique.time_scope}</em></header>
      <article><small>基础输入</small><div>{technique.base_inputs.map((item) => <span key={item}>{item}</span>)}</div></article>
      <article><small>时间变换</small><strong>{technique.transformation}</strong><p><b>输出结构</b>{technique.output_structure}</p></article>
      <aside className={technique.implementation_level}><small>锁定实现覆盖</small><strong>{coverage?.name}</strong><p>{technique.flatlib_status}</p></aside>
    </div>

    <div className="knowledge-block astrology-predictive-routes"><div className="interactive-heading"><span>固定学习问题</span><h2>问题相似，不代表技术可以互换</h2></div><nav aria-label="选择固定学习问题">{data.fixed_learning_routes.map((item) => <button className={item.id === route.id ? 'active' : ''} onClick={() => setRouteId(item.id)} aria-pressed={item.id === route.id} key={item.id}><strong>{item.question}</strong></button>)}</nav><div><article><small>问题</small><strong>{route.question}</strong><p>{route.note}</p></article><i>→</i><section>{routeCandidates.map((item) => <button onClick={() => { setFamilyId(item.family); setTechniqueId(item.id) }} key={item.id}><small>{data.families.find((group) => group.id === item.family)?.name}</small><strong>{item.name}</strong><span>{item.time_scope}</span></button>)}</section></div></div>

    <div className="knowledge-block astrology-predictive-matrix"><div className="interactive-heading"><span>八类技术总览</span><h2>输入、变换、输出和代码覆盖各自成列</h2></div><div>{data.techniques.map((item) => { const itemCoverage = data.implementation_coverage.find((entry) => entry.level === item.implementation_level); return <article className={item.id === technique.id ? 'selected' : ''} key={item.id}><header><small>{data.families.find((group) => group.id === item.family)?.name}</small><strong>{item.name}</strong></header><p>{item.time_scope}</p><span>{item.output_structure}</span><b className={item.implementation_level}>{itemCoverage?.name}</b></article> })}</div></div>

    <div className="knowledge-block astrology-predictive-coverage"><div className="interactive-heading"><span>代码覆盖状态</span><h2>概念说明、底层积木和专门模块不是同一完成度</h2></div><div>{data.implementation_coverage.map((item) => <article className={item.level} key={item.level}><small>{item.name}</small><strong>{item.count}</strong><span>类技术</span><p>{item.techniques.map((id) => data.techniques.find((techniqueItem) => techniqueItem.id === id)?.name).join(' · ')}</p></article>)}</div></div>

    <div className="knowledge-block astrology-predictive-differences"><div className="interactive-heading"><span>来源差异</span><h2>目录里有名字，不代表锁定实现已经接通</h2></div><div>{data.source_differences.map((item) => <article key={item.field}><strong>{item.field}</strong><p><small>作者资料</small>{item.author_source}</p><p><small>flatlib</small>{item.flatlib}</p><span>{item.handling}</span></article>)}</div></div>

    <WesternNodeLinks eyebrow="五个细化出口" title="总图负责选择方法，细化页负责解释算法与边界" openCard={openCard} links={[{ id: 'transits-position-set-comparison', role: '真实天空比较', title: '行运位置集合比较', note: '本命基线与目标天空' }, { id: 'annual-profections-whole-house-and-continuous-rotation', role: '星盘变换', title: '年度小限', note: '整宫年步与连续实现' }, { id: 'symbolic-motion-and-primary-directions', role: '星盘变换', title: '象征推进与主限方向弧', note: '日弧、次限与主限' }, { id: 'period-rulers-firdaria-and-zodiacal-releasing', role: '时期主星', title: '时期主星：法达与黄道释放', note: '行星时期与星座时期' }, { id: 'solar-return-time-and-chart-reconstruction', role: '回归时刻', title: '太阳回归', note: '寻找时刻并重建星盘' }]} />
    <div className="astrology-source-boundaries">{data.reading_boundaries.map((item, index) => <p key={item}><i>{String(index + 1).padStart(2, '0')}</i>{item}</p>)}</div>
  </section>
}

