function WesternCompletionNodePreview({ datasetKey }) {
  if (datasetKey === 'zodiac-signs-and-longitude-coordinate') return <div className="card-visual astrology-zodiac-coordinate-preview"><div><strong>0°</strong><i></i><strong>360°</strong></div><section>{['♈ 0–30', '♉ 30–60', '♊ 60–90', '…', '♓ 330–360'].map((item) => <span key={item}>{item}</span>)}</section></div>
  if (datasetKey === 'chart-input-and-coordinate-pipeline') return <div className="card-visual astrology-coordinate-pipeline-preview"><section><span>日期／时间</span><span>地点</span><span>时区</span></section><i>→</i><strong>绝对时刻</strong><i>→</i><div><b>天体黄经</b><b>宫界／轴点</b></div></div>
  if (datasetKey === 'transits-position-set-comparison') return <div className="card-visual astrology-transits-preview"><section><small>本命时刻</small><strong>本命位置集合</strong></section><i>×</i><section><small>目标时刻</small><strong>行运位置集合</strong></section><footer>跨集合角距 → 行运相位</footer></div>
  if (datasetKey === 'symbolic-motion-and-primary-directions') return <div className="card-visual astrology-motion-models-preview">{[['太阳弧', '统一平移'], ['次限', '一日象一年'], ['主限', '方向弧']].map(([name, motion]) => <span key={name}><small>{motion}</small><strong>{name}</strong><i></i></span>)}</div>
  return <div className="card-visual astrology-period-rulers-preview"><section><small>法达</small><strong>日夜教派</strong><i>→</i><b>行星时期</b></section><span>≠</span><section><small>黄道释放</small><strong>福点／精神点星座</strong><i>→</i><b>星座时期</b></section></div>
}

function WesternCompletionNodeDetail({ datasetKey, openCard }) {
  const data = westernAstrologyDatasets[westernCompletionDatasetKeys[datasetKey]]
  const presentation = westernCompletionPresentations[datasetKey]
  const [sampleId, setSampleId] = useState(data.fixed_samples[0].id)
  const sample = data.fixed_samples.find((item) => item.id === sampleId) || data.fixed_samples[0]
  return <section className="interactive-section astrology-completion-detail">
    <div className="interactive-heading"><span>{presentation.eyebrow}</span><h2>{presentation.headline}</h2></div>
    <div className="astrology-completion-concepts">{data.concept_cards.map((item, index) => <article key={item.id}><i>{String(index + 1).padStart(2, '0')}</i><small>{item.tag}</small><strong>{item.name}</strong><p>{item.summary}</p><div>{item.details.map((detail) => <span key={detail}>{detail}</span>)}</div></article>)}</div>
    <div className="knowledge-block astrology-completion-samples"><div className="interactive-heading"><span>{data.fixed_samples.length} 个可核对样本</span><h2>{presentation.sampleTitle}</h2></div><nav aria-label={`选择${data.title}固定样本`}>{data.fixed_samples.map((item) => <button className={item.id === sample.id ? 'active' : ''} onClick={() => setSampleId(item.id)} aria-pressed={item.id === sample.id} key={item.id}>{item.label}</button>)}</nav><div className="astrology-completion-stage"><article><small>{presentation.inputLabel}</small><strong>{sample.input}</strong></article><i>→</i><article><small>{presentation.outputLabel}</small><strong>{sample.output}</strong><span>{sample.note}</span></article></div></div>
    <div className="knowledge-block astrology-completion-comparisons"><div className="interactive-heading"><span>概念与实现边界</span><h2>{presentation.comparisonTitle}</h2></div><div>{data.comparisons.map((item) => <article key={item.field}><strong>{item.field}</strong><p><small>一侧</small>{item.left}</p><p><small>另一侧</small>{item.right}</p><span>{item.handling}</span></article>)}</div></div>
    <WesternNodeLinks title="从这里继续，不重复学习已经建立的前置规则" openCard={openCard} links={presentation.links} />
    <div className="astrology-source-boundaries">{data.reading_boundaries.map((item, index) => <p key={item}><i>{String(index + 1).padStart(2, '0')}</i>{item}</p>)}</div>
  </section>
}

