function DreamCardPreview({ id }) {
  if (id === 'dream-reading-map') return <div className="card-visual dream-map-preview">{dreamLearningStages.map((stage, index) => <span className={stage.card_ids.length ? 'active' : ''} key={stage.id}><i>{index + 1}</i><b>{stage.label}</b></span>)}</div>
  if (id === 'scope-and-objects') return <div className="card-visual dream-scope-preview">{dreamDatasets.scopeAndObjects.object_layers.map((item, index) => <Fragment key={item.id}><span><small>{item.question}</small><b>{item.label}</b></span>{index < 4 && <i>›</i>}</Fragment>)}</div>
  if (id === 'dream-record-fields') return <div className="card-visual dream-fields-preview">{dreamDatasets.dreamRecordFields.fields.map((item, index) => <span key={item.id}><i>{String(index + 1).padStart(2, '0')}</i><b>{item.label}</b></span>)}</div>
  if (id === 'six-dreams-zhouli') return <div className="card-visual dream-six-preview">{dreamDatasets.sixDreamsZhouli.dreams.map((item) => <span key={item.name}><i>{item.index}</i><strong>{item.name}</strong><small>{item.plain.slice(0, 6)}</small></span>)}</div>
  if (id === 'dream-classification-versions') return <div className="card-visual dream-versions-preview"><section><small>《周礼》</small><strong>六梦</strong><div>{dreamDatasets.dreamClassificationVersions.systems[0].names.map((item) => <b key={item}>{item}</b>)}</div></section><i>≠</i><section><small>《潜夫论》</small><strong>十梦</strong><div>{dreamDatasets.dreamClassificationVersions.systems[1].names.map((item) => <b key={item}>{item}</b>)}</div></section></div>
  if (id === 'dream-text-timeline') return <div className="card-visual dream-text-timeline-preview">{dreamDatasets.dreamTextTimeline.periods.map((item, index) => <Fragment key={item.period}><span><i>{item.period}</i><strong>{item.form}</strong><small>{item.anchor}</small></span>{index < 4 && <b>›</b>}</Fragment>)}</div>
  if (id === 'pre-qin-dream-narratives') return <div className="card-visual dream-narratives-preview">{dreamDatasets.preQinDreamNarratives.examples.map((item) => <span key={item.id}><small>{item.genre}</small><strong>{item.source}</strong><b>{item.shape}</b></span>)}</div>
  if (id === 'han-bibliography-dream-books') return <div className="card-visual dream-han-catalog-preview"><header><small>{dreamDatasets.hanBibliographyDreamBooks.catalog.class}</small><strong>{dreamDatasets.hanBibliographyDreamBooks.catalog.works}家 · {dreamDatasets.hanBibliographyDreamBooks.catalog.volumes}卷</strong></header>{dreamDatasets.hanBibliographyDreamBooks.catalog.dream_titles.map((item) => <span key={item.title}><b>{item.volumes}</b><strong>{item.title}</strong><small>仅存著录</small></span>)}</div>
  if (id === 'dunhuang-dream-manuscripts') return <div className="card-visual dream-dunhuang-preview"><header><strong>{dreamDatasets.dunhuangDreamManuscripts.manuscript.shelfmark}</strong><small>{dreamDatasets.dunhuangDreamManuscripts.manuscript.chapter_count}章 · {dreamDatasets.dunhuangDreamManuscripts.manuscript.entry_count}条</small></header><div>{dreamDatasets.dunhuangDreamManuscripts.chapter_groups.map((item) => <span key={item.label}><b>{item.chapters.length}</b><small>{item.label}</small></span>)}</div></div>
  if (id === 'mengzhan-yizhi-structure') return <div className="card-visual dream-yizhi-preview"><header><small>明 · 陈士元</small><strong>《梦占逸旨》</strong><b>八卷</b></header><div>{dreamDatasets.mengzhanYizhiStructure.architecture.map((item) => <span key={item.division}><strong>{item.division}</strong><small>{item.role}</small></span>)}</div><footer>{dreamDatasets.mengzhanYizhiStructure.nine_dreams.map((item) => <i key={item.name}>{item.name}</i>)}</footer></div>
  if (id === 'dream-image-index') return <div className="card-visual dream-image-index-preview"><i>梦象</i>{dreamDatasets.dreamImageIndex.categories.map((item, index) => <span style={{ '--dream-index': index }} key={item.id}><b>{index + 1}</b><small>{item.label.split('与')[0]}</small></span>)}</div>
  const imageData = dreamDatasets[dreamImageDatasetKeys[id]]
  if (imageData) return <div className="card-visual dream-image-category-preview">{imageData.facets.map((facet, index) => <section key={facet.label}><i>{String(index + 1).padStart(2, '0')}</i><strong>{facet.label}</strong><div>{facet.items.slice(0, 5).map((item) => <small key={item}>{item}</small>)}</div></section>)}</div>
  const interpretationData = dreamDatasets[dreamInterpretationDatasetKeys[id]]
  if (interpretationData) return <div className={`card-visual dream-interpretation-preview ${id === 'dream-time-conditions' ? 'is-time' : ''}`}>{interpretationData.sections.slice(0, 6).map((section) => <section key={section.label}><small>{section.note}</small><strong>{section.label}</strong><div>{section.items.slice(0, 3).map((item) => <span key={item.term}>{item.term}</span>)}</div></section>)}</div>
  const caseData = dreamDatasets[dreamCaseDatasetKeys[id]]
  if (caseData) return <div className="card-visual dream-case-preview">{caseData.stages.slice(0, 5).map((stage, index) => <Fragment key={`${stage.label}-${index}`}><section><i>{String(index + 1).padStart(2, '0')}</i><strong>{stage.label}</strong><small>{stage.content}</small></section>{index < Math.min(caseData.stages.length, 5) - 1 && <b>›</b>}</Fragment>)}</div>
  const boundaryData = dreamDatasets[dreamBoundaryDatasetKeys[id]]
  if (boundaryData) return <div className="card-visual dream-boundary-preview">{boundaryData.profiles.slice(0, 5).map((profile) => <section key={profile.label}><strong>{profile.label}</strong><small>{profile.object}</small><b>{profile.output}</b></section>)}</div>
  return null
}

