function PersonalityVersionDetail({ card }) {
  const { teaching } = card
  const [activeVersion, setActiveVersion] = useState(120)
  const versions = [{ n: 50, name: '宽轮廓', note: '重点观察五个大域', detail: '作答成本较低，适合只需要宽维度轮廓的场景。', load: 2 }, { n: 120, name: 'facet版本', note: '30 facet × 4题', detail: '在作答成本与facet覆盖之间折中，必须配套使用120题键向与常模。', load: 4 }, { n: 300, name: '密集版本', note: '30 facet × 10题', detail: '同一facet被更多题目观察，同时更需要处理疲劳、漏答与退出。', load: 7 }]
  const selected = versions.find((item) => item.n === activeVersion)
  return <section className="interactive-section personality-detail personality-version-detail">
    <PersonalityIntro card={card} eyebrow="版本选择台" />
    <div className="personality-version-rack">{versions.map((item) => <button type="button" className={activeVersion === item.n ? 'active' : ''} onClick={() => setActiveVersion(item.n)} key={item.n}><strong>{item.n}<small>题</small></strong><h3>{item.name}</h3><p>{item.note}</p><div>{Array.from({ length: item.load }, (_, i) => <i key={i} />)}</div></button>)}</div>
    <p className="personality-version-focus"><small>当前查看</small><strong>{selected.n}题 · {selected.name}</strong><span>{selected.detail}</span></p>
    <section className="personality-version-decision"><span>只有十分钟</span><b>先保完成率</b><i>↔</i><span>需要看主张性与群居偏好</span><b>选择facet版本</b></section>
    <p className="personality-verdict">{teaching.example.output}</p>
    <PersonalityUseRail teaching={teaching} label="选择版本时检查" />
  </section>
}

