function MbtiQuestionnaireDeepDive({ teaching }) {
  const [pairIndex, setPairIndex] = useState(0)
  const pair = teaching.pairs[pairIndex]
  return <section className="ps-mbti-deep">
    <nav aria-label="切换MBTI偏好对">{teaching.pairs.map((item,index)=><button type="button" className={index===pairIndex?'active':''} onClick={()=>setPairIndex(index)} key={item.code}><strong>{item.code}</strong><small>{item.question}</small></button>)}</nav>
    <article className="ps-mbti-facet-sheet"><header><b>{pair.left}</b><span>{pair.question}</span><b>{pair.right}</b></header><div>{pair.facets.map((facet,index)=>{const [left,right]=facet.split('—');return <p key={facet}><span>{left}</span><i>{index+1}</i><span>{right}</span></p>})}</div></article>
    <section className="ps-mbti-probability"><header><small>Global版本新增</small><strong>Probability Index</strong></header><p>{teaching.probability_index}</p><div><span>同一偏好再次出现的可能性</span><b>≠</b><span>偏好强度或人格占比</span></div></section>
    <ol className="ps-mbti-reading">{teaching.reading_order.map((item,index)=><li key={item}><i>{index+1}</i>{item}</li>)}</ol>
    <section className="ps-questionnaire-reading-grid">{teaching.type_walkthrough.map((item)=><article key={item.pair}><i>{item.choice}</i><p><small>{item.pair}</small>{item.basis}</p></article>)}</section>
    <blockquote className="ps-questionnaire-example"><small>四个字母怎样形成</small>{teaching.type_result}</blockquote>
    <section className="ps-mbti-verification"><header><small>报告类型 ≠ 未经核对的定论</small><strong>从报告类型到最佳拟合类型</strong></header><div>{teaching.verification_steps.map((step,index)=><article key={step.name}><i>{index+1}</i><strong>{step.name}</strong><p>{step.content}</p></article>)}</div><blockquote>{teaching.verification_result}</blockquote></section>
  </section>
}

function SixteenPfQuestionnaireDeepDive({ teaching }) {
  const [mode, setMode] = useState('quality')
  return <section className="ps-16pf-deep">
    <nav aria-label="切换16PF结果层">{[['quality','作答风格'],['primary','16个主要因素'],['global','5个全局因素'],['reports','报告用途']].map(([id,label])=><button type="button" className={mode===id?'active':''} onClick={()=>setMode(id)} key={id}>{label}</button>)}</nav>
    {mode==='quality'&&<section className="ps-16pf-response-style"><header><small>解释因素之前</small><strong>先检查这份答卷是怎样完成的</strong></header><div>{teaching.response_style_indices.map((item,index)=><article key={item.name}><i>{index+1}</i><strong>{item.name}</strong><small>{item.english}</small><p>{item.question}</p></article>)}</div><blockquote>{teaching.response_style_order}</blockquote></section>}
    {mode==='primary'&&<div className="ps-16pf-factor-table">{teaching.factors.map((factor)=><article key={factor.code}><header><i>{factor.code}</i><strong>{factor.name}</strong></header><p><span>{factor.low}</span><b>1 ··· 10</b><span>{factor.high}</span></p></article>)}</div>}
    {mode==='global'&&<div className="ps-16pf-global-grid">{teaching.global_factors.map((factor)=><article key={factor.name}><strong>{factor.name}</strong><p>{factor.contributors}</p></article>)}</div>}
    {mode==='reports'&&<div className="ps-16pf-report-stack">{teaching.report_modes.map((report,index)=><article key={report}><i>{index+1}</i><strong>{report}</strong><p>同一组因素按这一使用任务重新组织。</p></article>)}</div>}
    <blockquote>{teaching.score_unit}</blockquote>
    <blockquote className="ps-questionnaire-example"><small>sten轮廓怎样读</small>{teaching.worked_profile}</blockquote>
  </section>
}

function HoganQuestionnaireDeepDive({ card }) {
  const { teaching } = card
  return <section className="ps-hogan-deep">
    <article className={`ps-hogan-scale-board lens-${card.title.toLowerCase()}`}><header><small>逐条读取主要量表</small><strong>{card.title} · {teaching.identity}</strong></header><div>{teaching.scales.map((scale,index)=><span key={scale.name}><i>{String(index+1).padStart(2,'0')}</i><b>{scale.name}</b><small>{scale.reads}</small></span>)}</div></article>
    <section className="ps-hogan-percentile"><header><small>报告常见单位</small><strong>劳动力常模百分位</strong></header><div><i>1</i><span><b style={{width:'64%'}} /></span><i>99</i></div><p>{teaching.percentile}</p></section>
    <ol className="ps-hogan-cross-reading">{teaching.reading_steps.map((item,index)=><li key={item}><i>{index+1}</i>{item}</li>)}</ol>
  </section>
}

function MmpiQuestionnaireDeepDive({ teaching }) {
  const [validityIndex, setValidityIndex] = useState(0)
  const [groupIndex, setGroupIndex] = useState(0)
  const validity = teaching.validity_scales[validityIndex]
  const group = teaching.scale_groups[groupIndex]
  return <section className="ps-mmpi-deep">
    <div className="ps-mmpi-admin">{teaching.administration.map((item)=><span key={item}>{item}</span>)}</div>
    <section className="ps-mmpi-validity-console"><header><small>第一步 · 10个效度量表</small><strong>先辨认这份答卷是怎样形成的</strong></header><nav aria-label="切换MMPI-3效度量表">{teaching.validity_scales.map((item,index)=><button type="button" className={index===validityIndex?'active':''} onClick={()=>setValidityIndex(index)} key={item.code}>{item.code}</button>)}</nav><article><i>{validity.code}</i><div><strong>{validity.name}</strong><p>{validity.signal}</p></div></article></section>
    <section className="ps-mmpi-higher"><header><small>第二步 · 三条高阶量表</small><strong>先看宽广功能领域</strong></header><div>{teaching.higher_order.map((item)=><article key={item.code}><i>{item.code}</i><strong>{item.name}</strong></article>)}</div></section>
    <section className="ps-mmpi-groups"><header><small>第三步 · 继续下钻</small><strong>从宽广领域进入具体量表组</strong></header><nav aria-label="切换MMPI-3量表组">{teaching.scale_groups.map((item,index)=><button type="button" className={index===groupIndex?'active':''} onClick={()=>setGroupIndex(index)} key={item.name}><i>{index+1}</i><b>{item.name}</b><small>{item.members}</small></button>)}</nav><article><header><small>{group.name}</small><strong>{group.scales.length}条量表各自在看什么</strong></header><div>{group.scales.map((scale)=><span key={scale.code}><i>{scale.code}</i><b>{scale.name}</b><small>{scale.focus}</small></span>)}</div></article></section>
    <blockquote>{teaching.norm}</blockquote>
    <blockquote className="ps-questionnaire-example"><small>一份轮廓的阅读顺序</small>{teaching.profile_reading}</blockquote>
  </section>
}

function PersonalityQuestionnaireDeepDive({ card }) {
  if (card.id==='bfi-2-questionnaire') return <BfiQuestionnaireDeepDive teaching={card.teaching} />
  if (card.id==='hexaco-questionnaire') return <HexacoQuestionnaireDeepDive teaching={card.teaching} />
  if (card.id==='mbti-questionnaire') return <MbtiQuestionnaireDeepDive teaching={card.teaching} />
  if (card.id==='sixteen-pf-questionnaire') return <SixteenPfQuestionnaireDeepDive teaching={card.teaching} />
  if (['hpi-questionnaire','hds-questionnaire','mvpi-questionnaire'].includes(card.id)) return <HoganQuestionnaireDeepDive card={card} />
  return <MmpiQuestionnaireDeepDive teaching={card.teaching} />
}

function PersonalityQuestionnaireNode({ card }) {
  const { teaching } = card
  const knowledge = [
    ['实际怎样作答', teaching.response],
    ['回答怎样计分', teaching.scoring],
    ['最后拿到什么', teaching.report],
    ['主要用来回答什么', teaching.use],
  ]
  return <section className={`interactive-section personality-detail ps-questionnaire-node ps-questionnaire-${card.id}`}>
    <header className="ps-questionnaire-identity"><small>这份问卷的核心任务</small><strong>{teaching.identity}</strong></header>
    <PersonalityQuestionnaireSignature card={card} />
    <PersonalityQuestionnaireDeepDive card={card} />
    <div className="ps-questionnaire-knowledge">{knowledge.map(([label,content],index)=><article key={label}><i>{index+1}</i><small>{label}</small><p>{content}</p></article>)}</div>
    <blockquote className="ps-questionnaire-distinction"><small>与其他问卷分开的关键</small><strong>{teaching.distinction}</strong></blockquote>
  </section>
}

function PersonalityResultModelsMap({ card }) {
  const { teaching } = card
  const [modelIndex, setModelIndex] = useState(0)
  const model = teaching.models[modelIndex]
  return <section className="interactive-section personality-detail ps-result-models-map">
    <nav className="ps-result-model-tabs" aria-label="切换人格结果模型">{teaching.models.map((item,index)=><button type="button" className={index===modelIndex?'active':''} onClick={()=>setModelIndex(index)} key={item.name}><i>{index+1}</i><strong>{item.name}</strong></button>)}</nav>
    <article className="ps-result-model-focus"><header><small>{model.instruments}</small><strong>{model.name}</strong></header><blockquote>{model.question}</blockquote><div><span><small>结果单位</small><b>{model.unit}</b></span><span><small>固定示意</small><b>{model.example}</b></span></div></article>
  </section>
}

function PersonalityReportFormsMap({ card }) {
  const { teaching } = card
  const [reportIndex, setReportIndex] = useState(0)
  const report = teaching.reports[reportIndex]
  return <section className="interactive-section personality-detail ps-report-forms-map">
    <nav className="ps-report-form-tabs" aria-label="切换人格报告形态">{teaching.reports.map((item,index)=><button type="button" className={index===reportIndex?'active':''} onClick={()=>setReportIndex(index)} key={item.name}><i>{index+1}</i><strong>{item.name}</strong></button>)}</nav>
    <article className="ps-report-sheet"><header><small>{report.name}</small><h3>{report.headline}</h3></header><div>{report.elements.map((item,index)=><span key={item}><i>{index+1}</i><strong>{item}</strong></span>)}</div><footer>{report.fixed_example}</footer></article>
    <section className="ps-report-route"><header><small>这类报告怎样读</small><strong>{report.name}</strong></header><div>{report.route.map((item,index)=><span key={item}><i>{index+1}</i>{item}</span>)}</div></section>
    {report.integrated_case&&<section className="ps-hogan-integrated-case"><header><small>三份报告联合案例</small><strong>{report.integrated_case.task}</strong></header><div>{report.integrated_case.signals.map((signal)=><article key={signal.instrument}><i>{signal.instrument}</i><strong>{signal.score}</strong><p>{signal.meaning}</p></article>)}</div><blockquote>{report.integrated_case.synthesis}</blockquote></section>}
    <ol className="ps-report-reading-order">{teaching.reading_order.map((item,index)=><li key={item}><i>{index+1}</i>{item}</li>)}</ol>
  </section>
}

function PersonalityUseContextsMap({ card }) {
  const { teaching } = card
  const [contextIndex, setContextIndex] = useState(0)
  const context = teaching.contexts[contextIndex]
  return <section className="interactive-section personality-detail ps-use-contexts-map">
    <nav className="ps-use-context-tabs" aria-label="切换人格问卷使用任务">{teaching.contexts.map((item,index)=><button type="button" className={index===contextIndex?'active':''} onClick={()=>setContextIndex(index)} key={item.name}><i>{index+1}</i><strong>{item.name}</strong></button>)}</nav>
    <article className="ps-use-context-focus"><header><small>{context.name}</small><h3>{context.task}</h3></header><div><span><small>需要具备</small><strong>{context.needs}</strong></span><span><small>常见形式</small><strong>{context.common_forms}</strong></span></div></article>
    <section className="ps-use-decision"><header><small>固定任务</small><strong>{context.example_question}</strong></header><div><span><small>怎样选</small>{context.example_choice}</span><span><small>继续检查</small>{context.example_check}</span></div></section>
    <div className="ps-selection-axes">{teaching.selection_axes.map((item,index)=><span key={item}><i>{index+1}</i>{item}</span>)}</div>
  </section>
}

function PersonalityUnitContent({ unit }) {
  const card = { ...unit, embeddedInNode: true }
  if (unit.id === 'questionnaire-anatomy') return <PersonalityQuestionnaireAnatomyMap card={card} />
  if (['bfi-2-questionnaire','hexaco-questionnaire','mbti-questionnaire','sixteen-pf-questionnaire','hpi-questionnaire','hds-questionnaire','mvpi-questionnaire','mmpi-3-questionnaire'].includes(unit.id)) return <PersonalityQuestionnaireNode card={card} />
  if (unit.id === 'personality-result-models') return <PersonalityResultModelsMap card={card} />
  if (unit.id === 'personality-report-forms') return <PersonalityReportFormsMap card={card} />
  if (unit.id === 'personality-questionnaire-use-contexts') return <PersonalityUseContextsMap card={card} />
  if (unit.id === 'what-personality-questionnaires-measure') return <PersonalityMeasureMap card={card} />
  if (unit.id === 'how-a-self-report-item-is-answered') return <PersonalityItemResponseMap card={card} />
  if (unit.id === 'how-personality-scales-are-developed') return <PersonalityDevelopmentMap card={card} />
  if (unit.id === 'translation-adaptation-and-validation') return <PersonalityTranslationMap card={card} />
  if (unit.id === 'comparing-scores-across-groups') return <PersonalityGroupComparisonMap card={card} />
  if (unit.id === 'from-items-to-scores') return <PersonalityScoringMap card={card} />
  if (unit.id === 'trait-signal-and-acquiescence') return <PersonalityAcquiescenceMap card={card} />
  if (unit.id === 'big-five-domains-and-facets') return <PersonalityDomainsMap card={card} />
  if (unit.id === 'trait-expression-across-situations') return <PersonalitySituationMap card={card} />
  if (unit.id === 'reading-scores-and-profile') return <PersonalityReadingMap card={card} />
  if (unit.id === 'interpreting-score-change-over-time') return <PersonalityScoreChangeMap card={card} />
  if (unit.id === 'self-and-informant-personality-reports') return <PersonalitySelfOtherMap card={card} />
  if (unit.id === 'checking-response-quality') return <PersonalityResponseQualityMap card={card} />
  return <PersonalityScaleEvidenceMap card={card} />
}

function PersonalityNodeDetail({ card }) {
  const scrollToSection = (id) => document.getElementById(`personality-section-${id}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  return <div className={`ps-chapter-detail ps-chapter-${card.id}`}>
    <nav className="ps-chapter-index" aria-label={`${card.title}知识索引`}>{card.sections.map((section, index) => <button type="button" onClick={() => scrollToSection(section.id)} key={section.id}><i>{String(index + 1).padStart(2, '0')}</i><span><small>{section.nodeRole}</small><strong>{section.shortTitle}</strong></span></button>)}</nav>
    <div className="ps-chapter-river">{card.sections.map((section, index) => <article className="ps-chapter-unit" id={`personality-section-${section.id}`} key={section.id}><header className="ps-unit-heading"><i>{String(index + 1).padStart(2, '0')}</i><div><small>{section.nodeRole}</small><h2>{section.shortTitle}</h2><p className="ps-unit-question">{section.question}</p><p className="ps-unit-thesis">{section.teaching.core_idea}</p></div></header><PersonalityUnitContent unit={section} /></article>)}</div>
  </div>
}

function PersonalityDetail({ card }) {
  if (card.sections) return <PersonalityNodeDetail card={card} />
  if (['bfi-2-questionnaire','hexaco-questionnaire','mbti-questionnaire','sixteen-pf-questionnaire','hpi-questionnaire','hds-questionnaire','mvpi-questionnaire','mmpi-3-questionnaire'].includes(card.id)) return <PersonalityQuestionnaireNode card={card} />
  if (card.id === 'what-personality-questionnaires-measure') return <PersonalityMeasureMap card={card} />
  if (card.id === 'how-a-self-report-item-is-answered') return <PersonalityItemResponseMap card={card} />
  if (card.id === 'how-personality-scales-are-developed') return <PersonalityDevelopmentMap card={card} />
  if (card.id === 'translation-adaptation-and-validation') return <PersonalityTranslationMap card={card} />
  if (card.id === 'comparing-scores-across-groups') return <PersonalityGroupComparisonMap card={card} />
  if (card.id === 'from-items-to-scores') return <PersonalityScoringMap card={card} />
  if (card.id === 'trait-signal-and-acquiescence') return <PersonalityAcquiescenceMap card={card} />
  if (card.id === 'big-five-domains-and-facets') return <PersonalityDomainsMap card={card} />
  if (card.id === 'trait-expression-across-situations') return <PersonalitySituationMap card={card} />
  if (card.id === 'reading-scores-and-profile') return <PersonalityReadingMap card={card} />
  if (card.id === 'interpreting-score-change-over-time') return <PersonalityScoreChangeMap card={card} />
  if (card.id === 'self-and-informant-personality-reports') return <PersonalitySelfOtherMap card={card} />
  if (card.id === 'checking-response-quality') return <PersonalityResponseQualityMap card={card} />
  return <PersonalityScaleEvidenceMap card={card} />
}

const liuyaoCompletionOutcomes = [
  '能从六爻卦体出发，分清爻位、内外卦、八宫与世应各自回答什么。',
  '能说明纳甲、六亲、飞伏、六神与星煞怎样进入盘面，并区分主结构与辅助标签。',
  '能沿动爻、变卦、地支关系和月日状态追踪一条作用链，而不把所有条件压成单一强弱分数。',
  '能围绕目标角色继续读取用神与应期，也能指出不同古籍或实现在哪一层发生分歧。',
]

const liuyaoCompletionExclusions = [
  '不接收真人问题、随机起卦或当前日期，不替用户生成一张新盘。',
  '不把六神、星煞、旬空、冲合或应期单独翻译成固定吉凶。',
  '不发布事项断语、行动建议或针对个人处境的结论。',
  '不把古籍异说与现代实现投票合并成一套唯一算法。',
]

function LiuyaoIntroductionDetail({ openCard }) {
  return <section className="interactive-section liuyao-introduction-detail">
    <header><small>第一次进入六爻</small><h2>先分清“盘面是什么”，再讨论关系怎样变化</h2><p>一张六爻盘不是一排可以同时下结论的标签。先建立卦体和装配，再读动变、时间状态与目标角色，才能知道每个字段从哪里来、作用在哪一层。</p></header>
    <div className="liuyao-reading-river">{liuyaoLearningStages.map((stage, index) => <Fragment key={stage.id}><article><header><small>阶段 {index + 1} · {stage.label}</small><strong>{stage.question}</strong><span>{stage.note}</span></header><nav aria-label={`${stage.label}知识节点`}>{stage.cards.map((cardId) => { const card = liuyaoCards.find((item) => item.id === cardId); return <button type="button" onClick={() => openCard(cardId)} key={cardId}>{card.title}<i aria-hidden="true">→</i></button> })}</nav></article>{index < liuyaoLearningStages.length - 1 && <i>→</i>}</Fragment>)}</div>
    <LiuyaoTopicDemonstration openCard={openCard} />
    <div className="liuyao-guide-boundaries"><p>固定案例只帮助辨认字段，不替用户起卦。</p><p>六神、星煞、旬空、应期等名称必须回到各自输入与条件，不能单独换算成吉凶。</p><p>古籍异说、实现差异和项目推导继续并列保存，不合成唯一算法。</p></div>
    <section className="liuyao-completion-band" aria-labelledby="liuyao-completion-title"><header><small>读完20个正式节点以后</small><h2 id="liuyao-completion-title">能够复述完整结构，也知道知识地图主动停在哪里</h2></header><div><section><small>已经建立的理解</small>{liuyaoCompletionOutcomes.map((item, index) => <p key={item}><i>{index + 1}</i><span>{item}</span></p>)}</section><aside><small>阅读边界</small>{liuyaoCompletionExclusions.map((item) => <p key={item}>{item}</p>)}</aside></div><footer><strong>V1 完成标准</strong><span>核心对象、生成规则、关系层、时间状态、目标定位、来源差异与学习入口已经闭合；“完成”不等于穷尽所有流派，也不等于提供个人占断。</span></footer></section>
  </section>
}

