function MergedChapter({ index, title, note, children }) {
  return (
    <div className="merged-topic-chapter">
      <header className="merged-topic-heading"><small>{String(index).padStart(2, '0')}</small><div><h2>{title}</h2><p>{note}</p></div></header>
      {children}
    </div>
  )
}

