function TwelveMessageHexagramsDetail() {
  const data = liuyaoDatasets.twelveMessageHexagrams
  const [recordId, setRecordId] = useState(data.records[0].id)
  const index = data.records.findIndex((item) => item.id === recordId)
  const current = data.records[index]
  const previous = data.records[(index + data.records.length - 1) % data.records.length]
  const next = data.records[(index + 1) % data.records.length]
  return (
    <section className="interactive-section liuyao-detail message-hexagram-detail">
      <div className="interactive-heading"><span>十二个月建</span><h2>每过一月，只让下一爻改变阴阳</h2></div>
      <div className="message-month-selector">
        {data.records.map((record) => (
          <button className={record.id === recordId ? 'active' : ''} onClick={() => setRecordId(record.id)} key={record.id}>
            <small>{record.month}</small><strong>{record.branch}</strong><span>{record.name}</span>
          </button>
        ))}
      </div>

      <div className={`message-cycle-board ${current.yang_count >= 3 ? 'light' : 'dark'}`}>
        <header>
          <small>{current.month} · {current.branch}月</small>
          <strong>{current.name}</strong>
          <span>{current.phase}</span>
        </header>
        <div className="message-hexagram-lines" aria-label={`${current.name}卦六爻，自上而下显示`}>
          {current.lines.slice().reverse().map((line, lineIndex) => <span className={line} key={`${current.id}-${lineIndex}`}><i /><i /></span>)}
        </div>
        <aside>
          <small>阳爻</small><strong>{current.yang_count}<i>／6</i></strong>
          <div>{Array.from({ length: 6 }, (_, dot) => <b className={dot < current.yang_count ? 'yang' : 'yin'} key={dot} />)}</div>
          <span>{current.change}</span>
        </aside>
        <b className="message-symbol">{current.symbol}</b>
      </div>
      <p className="reading-note"><strong>{current.branch}月 · {current.name}卦</strong>：{current.note}</p>

      <div className="message-neighbor-strip">
        <article><small>上一月</small><strong>{previous.branch} · {previous.name}</strong><span>{previous.yang_count} 阳</span></article>
        <i>一爻改变</i>
        <article className="current"><small>当前</small><strong>{current.branch} · {current.name}</strong><span>{current.change}</span></article>
        <i>一爻改变</i>
        <article><small>下一月</small><strong>{next.branch} · {next.name}</strong><span>{next.yang_count} 阳</span></article>
      </div>

      <div className="knowledge-block message-structure-notes">
        <div className="interactive-heading"><span>这条环保存什么</span><h2>月份、卦形与爻位变化是三层同一个结构</h2></div>
        <div>{data.structure_notes.map((item, noteIndex) => <article key={item.label}><i>{String(noteIndex + 1).padStart(2, '0')}</i><strong>{item.label}</strong><p>{item.note}</p></article>)}</div>
      </div>
    </section>
  )
}

