function ChangedLineStatesDetail() {
  const data = liuyaoDatasets.changedLineStates
  const growthData = liuyaoDatasets.growthPeakTombAbsolute
  const tombAbsoluteMap = [
    ...growthData.element_tracks.map((item) => ({ element: item.element, tomb: item.anchors.tomb, absolute: item.anchors.absolute })),
    { element: '土', ...growthData.soil_methods.find((item) => item.id === 'water').anchors },
  ]
  const [statusId, setStatusId] = useState(data.status_types[0].id)
  const status = data.status_types.find((item) => item.id === statusId)
  const example = status.example
  return (
    <section className={`interactive-section liuyao-detail changed-state-detail ${status.id}`}>
      <div className="interactive-heading"><span>变爻状态</span><h2>四个标签共用变爻入口，却读取三组不同条件</h2></div>
      <div className="changed-state-selector">
        {data.status_types.map((item) => <button className={`${item.id} ${statusId === item.id ? 'active' : ''}`} onClick={() => setStatusId(item.id)} key={item.id}><small>{item.dependency}</small><strong>{item.label}</strong><span>{item.mark}</span></button>)}
      </div>
      <div className="changed-state-board">
        <article><small>本爻</small><strong>{example.base_branch}</strong><span>{example.base_element}</span></article>
        <div className="changed-state-route"><small>{example.route}</small><i>→</i><b>{status.label}</b><em>{example.context}</em></div>
        <article className="changed"><small>变爻</small><strong>{example.changed_branch}</strong><span>{example.changed_element}</span></article>
      </div>
      <p className="reading-note"><strong>{example.route}</strong>得到{example.base_branch}{example.base_element}化{example.changed_branch}{example.changed_element}；读取“{status.dependency}”，因为{status.rule}，所以标为<strong>{status.label}</strong>。</p>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>三层依赖</span><h2>墓绝看本爻，空看占日，破看月建</h2></div>
        <div className="changed-dependency-grid">{data.dependency_layers.map((layer) => <article key={layer.id}><small>{layer.label}</small><strong>{layer.input}</strong><i>＋ {layer.joins}</i><div>{layer.outcomes.map((item) => <b key={item}>{item}</b>)}</div><p>{layer.note}</p></article>)}</div>
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>固定映射</span><h2>三种依赖各有自己的核对表</h2></div>
        <div className="changed-map-grid">
          <article className="tomb-map"><header><small>本爻五行</small><strong>墓 · 绝</strong></header><div>{tombAbsoluteMap.map((item) => <span key={item.element}><b>{item.element}</b><i>{item.tomb}<small>墓</small></i><i>{item.absolute}<small>绝</small></i></span>)}</div></article>
          <article className="void-map"><header><small>占日所属旬</small><strong>旬空</strong></header><div>{data.void_map.map((item) => <span key={item.cycle}><b>{item.cycle}</b><i>{item.void.join(' · ')}</i></span>)}</div></article>
          <article className="break-map"><header><small>月建 → 相冲支</small><strong>月破</strong></header><div>{data.month_break_map.map((item) => <span key={item.month}><b>{item.month}</b><i>→</i><strong>{item.broken}</strong></span>)}</div></article>
        </div>
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>标签可以并存</span><h2>不同依赖层可以在同一变爻上汇合</h2></div>
        <div className="changed-overlap-board">
          <div><small>本爻</small><strong>{data.overlap_example.base_branch}</strong><span>{data.overlap_example.base_element}</span></div>
          <i>→</i>
          <div><small>变爻</small><strong>{data.overlap_example.changed_branch}</strong><span>{data.overlap_example.changed_element}</span></div>
          <article>{data.overlap_example.matches.map((item) => <b key={item}>{item}</b>)}</article>
        </div>
        <p className="reading-note"><strong>{data.overlap_example.route}</strong>；{data.overlap_example.context}。{data.overlap_example.explanation}</p>
      </div>

    </section>
  )
}

function MonthDayContextDetail() {
  const data = liuyaoDatasets.monthDayContext
  const [branch, setBranch] = useState(data.fixed_samples[0].branch)
  const sample = data.fixed_samples.find((item) => item.branch === branch)
  const year = data.contexts.find((item) => item.id === 'year')
  const month = data.contexts.find((item) => item.id === 'month')
  const day = data.contexts.find((item) => item.id === 'day')
  return (
    <section className="interactive-section liuyao-detail month-day-detail">
      <div className="interactive-heading"><span>月日直接关系</span><h2>固定寅月、申日，看两条时间关系怎样落到同一爻</h2></div>
      <div className="month-day-selector">
        {data.fixed_samples.map((item) => <button className={branch === item.branch ? 'active' : ''} onClick={() => setBranch(item.branch)} key={item.branch}><strong>{item.branch}</strong><small>{item.element}</small></button>)}
      </div>
      <div className="month-day-board">
        <article className="month-source"><small>{month.label}</small><strong>{month.branch}</strong><span>{month.element}</span><em>{month.time_span}</em></article>
        <div className="month-relation"><i>→</i>{sample.month_relations.map((item) => <b key={item}>{item}</b>)}</div>
        <article className="target-line"><small>卦中同一爻</small><strong>{sample.branch}</strong><span>{sample.element}</span></article>
        <div className="day-relation">{sample.day_relations.map((item) => <b key={item}>{item}</b>)}<i>←</i></div>
        <article className="day-source"><small>{day.label}</small><strong>{day.branch}</strong><span>{day.element}</span><em>{day.time_span}</em></article>
      </div>
      <p className="reading-note">固定<strong>寅月、申日</strong>，选择{sample.branch}{sample.element}爻后，月建侧得到<strong>{sample.month_relations.join('、')}</strong>，日辰侧得到<strong>{sample.day_relations.join('、')}</strong>。{sample.explanation} {data.fixed_context_note}</p>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>三层时间尺度</span><h2>年、月、日都在卦外，但作用范围并不相同</h2></div>
        <div className="month-day-context-grid">{data.contexts.map((item) => <article className={item.id} key={item.id}><small>{item.time_span}</small><strong>{item.label}</strong><p>{item.role}</p><div>{item.special_labels.map((label) => <b key={label}>{label}</b>)}</div></article>)}</div>
      </div>

      <div className="knowledge-block year-context-block">
        <div className="interactive-heading"><span>太岁的范围门</span><h2>司一年之令，不等于在所有事情里都比月日更强</h2></div>
        <div className="year-context-board">
          <article><small>固定年度支</small><strong>{year.branch}</strong><span>{year.label} · {year.element}</span></article>
          <i>先判断观察尺度</i>
          <div>{data.year_context.rules.map((item) => <section key={item.id}><small>{item.question}</small><strong>{item.label}</strong><p>{item.note}</p></section>)}</div>
        </div>
        <div className="year-source-positions">{data.year_context.source_positions.map((item) => <article key={item.label}><strong>{item.label}</strong><p>{item.position}</p></article>)}</div>
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>月日的直接作用范围</span><h2>月建、日辰可以越过卦层，直接连接五类对象</h2></div>
        <div className="month-day-scope">
          <header><span>月建</span><i>日月关系</i><span>日辰</span></header>
          <div>{data.object_scope.map((item) => <article key={item.id}><strong>{item.label}</strong><small>{item.note}</small></article>)}</div>
        </div>
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>月日关系命名</span><h2>同一条件在月、日两侧生成不同前缀</h2></div>
        <div className="month-day-relation-grid">{data.relation_templates.map((item) => <article key={item.condition}><small>{item.condition}</small><strong>{item.month}</strong><i>／</i><strong>{item.day}</strong></article>)}</div>
      </div>

    </section>
  )
}

function ThreeHarmonyDetail() {
  const data = liuyaoDatasets.threeHarmonyFormations
  const [formationId, setFormationId] = useState(data.formations[0].id)
  const [pathId, setPathId] = useState(data.source_paths[0].id)
  const formation = data.formations.find((item) => item.id === formationId)
  const path = data.source_paths.find((item) => item.id === pathId)
  return (
    <section className="interactive-section liuyao-detail harmony-detail">
      <div className="interactive-heading"><span>四组三合</span><h2>三个成员分别占据生、旺、墓位置</h2></div>
      <div className="harmony-selector">
        {data.formations.map((item) => <button className={formationId === item.id ? 'active' : ''} onClick={() => setFormationId(item.id)} key={item.id}><small>{item.branches.map((entry) => entry.branch).join(' · ')}</small><strong>{item.label}</strong></button>)}
      </div>
      <div className={`harmony-formation-board ${formation.id}`}>
        <div className="harmony-members">
          {formation.branches.map((item) => <article key={item.branch}><small>{item.stage}</small><strong>{item.branch}</strong></article>)}
        </div>
        <div className="harmony-convergence"><span>三个成员</span><i>↓</i><strong>{formation.label}</strong><small>{formation.branches.map((item) => item.branch).join(' · ')}</small></div>
      </div>
      <p className="reading-note">选择<strong>{formation.label}</strong>后，三支依次为{formation.branches.map((item) => `${item.branch}（${item.stage}）`).join('、')}。这里的生、旺、墓只是三合成员在结构中的位置名称。</p>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>成员从哪里来</span><h2>三支可以跨层齐备，也可以明确留下缺口</h2></div>
        <div className="harmony-path-selector">
          {data.source_paths.map((item) => <button className={pathId === item.id ? 'active' : ''} onClick={() => setPathId(item.id)} key={item.id}><small>{item.status}</small><strong>{item.label}</strong></button>)}
        </div>
        <div className={`harmony-source-board ${path.id}`}>
          <div className="harmony-source-members">{path.members.map((item, index) => <article className={item.missing ? 'missing' : ''} key={`${item.branch}-${index}`}><small>{item.source}</small><strong>{item.branch}</strong><i>{item.missing ? '待补' : '已取得'}</i></article>)}</div>
          <div className="harmony-source-result"><i>↓</i><strong>{path.status}</strong><p>{path.result}</p></div>
        </div>
        <p className="reading-note">这里的四项是互相独立的固定结构例，不跟随上方四局选择同步变化；它们专门用来比较成员来源与完成状态。</p>
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>古籍列出的四路</span><h2>本卦、内卦动变与外卦动变要分层记录</h2></div>
        <div className="harmony-classical-grid">{data.classical_paths.map((item, index) => <article key={item.label}><i>{index + 1}</i><small>{item.scope}</small><strong>{item.label}</strong><p>{item.note}</p></article>)}</div>
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>不是只查三支</span><h2>完整、来源与受阻是三项不同检查</h2></div>
        <div className="harmony-state-grid">{data.state_checks.map((item) => <article key={item.id}><small>{item.label}</small><strong>{item.question}</strong><p>{item.note}</p></article>)}</div>
      </div>

    </section>
  )
}

