function publicSourceKind(source) {
  const haystack = `${source.title} ${source.url}`.toLowerCase()
  if (/\/issues?\/|\bissue\b|争议|讨论/.test(haystack)) return { label: '争议记录', tone: 'discussion' }
  if (/test|测试|断言/.test(haystack)) return { label: '实现测试', tone: 'test' }
  if (/github\.com|实现|代码|配置|函数|字段/.test(haystack)) return { label: '实现资料', tone: 'implementation' }
  if (/博物馆|天文台|图书馆|馆藏|目录|museum|observatory/.test(haystack)) return { label: '机构资料', tone: 'institution' }
  return { label: '原文资料', tone: 'primary' }
}

function publicSourceSummary(note = '') {
  const metaTail = /(?:；|，)(?:但|不过|然而)?(?:本页|页面|本站|公开页面|当前未|故|仅作|只作|不等于|不能|不替代|不自动|不延伸|不复制|仍需|待核验|测试只|测试通过|实现内部一致|仓库叙述|仓库没有|内容权利|输入链).*$/
  const summary = note
    .replace(/\s+/g, ' ')
    .replace(metaTail, '')
    .replace(/，但.*$/, '')
    .replace(/本页/g, '页面')
    .trim()
  if (!summary) return '查看该资料对应的原文、数据或实现。'
  return /[。！？]$/.test(summary) ? summary : `${summary}。`
}

function PublicSources({ sources }) {
  return (
    <section className="knowledge-block public-sources">
      <div className="interactive-heading"><span>来源</span><h2>公开资料</h2></div>
      <div className="source-grid">
        {sources.map((source, index) => {
          const kind = publicSourceKind(source)
          return (
            <article className={`source-card ${kind.tone}`} key={`${source.id || source.title}-${source.url}-${index}`}>
              <span className="source-kind">{kind.label}</span>
              <strong><a href={source.url} target="_blank" rel="noreferrer">{source.title}<i aria-hidden="true">↗</i></a></strong>
              <p><b>支撑内容</b><span>{publicSourceSummary(source.note)}</span></p>
            </article>
          )
        })}
      </div>
    </section>
  )
}

