function BranchRelationsDetail() {
  const relationTabs = Object.entries(datasets.branchRelations.relations)
  const [selectedBranch, setSelectedBranch] = useState('子')
  const [active, setActive] = useState('liu_he')
  const activeRelation = datasets.branchRelations.relations[active]
  const branchProfile = datasets.branchRelations.branch_attributes.find((item) => item.branch === selectedBranch)
  const normalizeRecord = (record) => Array.isArray(record) ? { members: record } : record
  const related = relationTabs.flatMap(([key, relation]) => relation.records
    .map(normalizeRecord)
    .filter((record) => record.members.includes(selectedBranch))
    .map((record) => ({ key, label: relation.label, ...record })))

  function relationMark(record, relation) {
    if (relation.kind === 'pairs') return '↔'
    if (record.type === 'cycle') return '→'
    if (record.type === 'mutual') return '↔'
    if (record.type === 'self') return '各自'
    return '+'
  }

  return (
    <section className="interactive-section">
      <div className="interactive-heading"><span>单支视角</span><h2>选择一个地支，看它同时进入哪些关系</h2></div>
      <div className="branch-selector">
        {datasets.branchRelations.branches.map((branch) => <button className={selectedBranch === branch ? 'active' : ''} onClick={() => setSelectedBranch(branch)} key={branch}>{branch}</button>)}
      </div>
      <div className="branch-relation-summary">
        <div className="selected-branch">
          <small>当前地支</small><strong>{selectedBranch}</strong>
          <div className="branch-profile"><span>{branchProfile.polarity}</span><span>{branchProfile.element}</span><span>{branchProfile.animal}</span></div>
        </div>
        <div className="branch-relation-links">
          {related.map((record, index) => (
            <button onClick={() => setActive(record.key)} key={`${record.key}-${index}`}>
              <small>{record.label}</small>
              <strong>{record.members.join(relationMark(record, datasets.branchRelations.relations[record.key]))}</strong>
            </button>
          ))}
        </div>
      </div>
      <p className="reading-note">关系可以重叠。例如巳申既是六合配对，又同时进入寅巳申三刑结构；两条关系应分别保留。</p>

      <div className="knowledge-block">
      <div className="interactive-heading"><span>分类对照</span><h2>切换关系，查看完整成员</h2></div>
      <div className="relation-tabs">
        {relationTabs.map(([key, relation]) => <button className={active === key ? 'active' : ''} onClick={() => setActive(key)} key={key}>{relation.label}</button>)}
      </div>
      <div className="relation-pairs">
        {activeRelation.records.map(normalizeRecord).map((record, index) => (
          <div className={record.members.length > 2 ? 'multi' : ''} key={`${active}-${index}`}>
            <strong>{record.members.join(` ${relationMark(record, activeRelation)} `)}</strong>
            <span>{activeRelation.label}</span>
            {record.resulting_element && <small>{record.resulting_element}局</small>}
            {record.type === 'self' && <small>各支与自身相刑</small>}
          </div>
        ))}
      </div>
      <p className="reading-note">六合页只保留固定配对，不把“相合”直接写成已经合化；相刑页保留循环、互刑与自刑结构，不采用存在分歧的类别名称。</p>
      </div>
    </section>
  )
}

function GrowthStagesDetail() {
  const stems = datasets.growthStages.stem_paths.map((item) => item.stem)
  const [stem, setStem] = useState('甲')
  const path = datasets.growthStages.stem_paths.find((item) => item.stem === stem)
  const orderedPath = datasets.growthStages.stages.map((stage) => ({
    stage,
    branch: Object.entries(datasets.growthStages.matrix[stem]).find(([, value]) => value === stage)?.[0],
  }))
  const stageNotes = {
    长生: '开始生发', 沐浴: '初生而未定', 冠带: '逐渐成形', 临官: '能够任事',
    帝旺: '气势最盛', 衰: '由盛转弱', 病: '力量受损', 死: '生机收束',
    墓: '收藏入库', 绝: '旧气断绝', 胎: '新气受形', 养: '蓄养待生',
  }
  return (
    <section className="interactive-section">
      <div className="interactive-heading"><span>阶段路径</span><h2>选择一个天干，从长生走完十二阶段</h2></div>
      <div className="stem-selector">
        {stems.map((item) => <button className={stem === item ? 'active' : ''} onClick={() => setStem(item)} key={item}>{item}</button>)}
      </div>
      <div className="growth-path">
        {orderedPath.map(({ branch, stage }, index) => (
          <div key={stage}><i>{String(index + 1).padStart(2, '0')}</i><strong>{branch}</strong><span>{stage}</span></div>
        ))}
      </div>
      <p className="reading-note"><strong>{stem}</strong>是{path.polarity}干，从<strong>{path.start_branch}</strong>开始长生，随后沿地支<strong>{path.direction}</strong>。下方按阶段顺序排列，不是子到亥的固定支序。</p>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>阶段含义</span><h2>十二个名称描述一轮气的生长、收藏与再启</h2></div>
        <div className="stage-meaning-grid">
          {datasets.growthStages.stages.map((stage, index) => (
            <div key={stage}><i>{String(index + 1).padStart(2, '0')}</i><strong>{stage}</strong><span>{stageNotes[stage]}</span></div>
          ))}
        </div>
        <p className="reading-note">这些名称先表示循环中的位置。十二长生追踪“一个天干经过十二地支”；旺相休囚死比较“五行在某个时令中”，两者不是同一张表。</p>
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>完整起点</span><h2>十天干从哪里开始，向哪个方向运行</h2></div>
        <div className="growth-start-grid">
          {datasets.growthStages.stem_paths.map((item) => (
            <div key={item.stem}><strong>{item.stem}</strong><span>{item.start_branch}起长生</span><small>{item.polarity}干 {item.direction}</small></div>
          ))}
        </div>
      </div>
    </section>
  )
}

function TiaohouDetail() {
  const data = datasets.tiaohouSelection
  const examples = [data.worked_example, ...(data.additional_examples || [])]
  const [dayStem, setDayStem] = useState(examples[0].day_stem)
  const example = examples.find((item) => item.day_stem === dayStem)
  const [month, setMonth] = useState(example.records[0].month_branch)
  const record = example.records.find((item) => item.month_branch === month) || example.records[0]

  function selectExample(item) {
    setDayStem(item.day_stem)
    setMonth(item.records[0].month_branch)
  }

  return (
    <section className="interactive-section tiaohou-detail">
      <div className="interactive-heading"><span>阅读路径</span><h2>调候不是查一个字，而是连续回答四个问题</h2></div>
      <div className="tiaohou-dimensions">
        {data.reading_dimensions.map((item, index) => (
          <article key={item.id}>
            <i>{String(index + 1).padStart(2, '0')}</i>
            <small>{item.label}</small>
            <h3>{item.question}</h3>
            <p>{item.explanation}</p>
          </article>
        ))}
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>固定阅读样本</span><h2>选择日干样本，再切换月份</h2></div>
        <div className="tiaohou-example-selector">
          {examples.map((item) => (
            <button className={dayStem === item.day_stem ? 'active' : ''} onClick={() => selectExample(item)} key={item.day_stem}>
              <strong>{item.day_stem}</strong><span>{item.label.replace(item.day_stem, '')}</span>{item.scope && <small>{item.scope}</small>}
            </button>
          ))}
        </div>
        <p className="tiaohou-scope-note">{example.note}</p>
        <div className="branch-selector tiaohou-month-selector">
          {example.records.map(({ month_branch: branch }) => (
            <button className={month === branch ? 'active' : ''} onClick={() => setMonth(branch)} key={branch}>{branch}</button>
          ))}
        </div>
        <div className="tiaohou-example">
          <div className="tiaohou-month">
            <small>{example.day_stem}生于</small>
            <strong>{record.month_branch}</strong>
            <span>{record.season_label}</span>
          </div>
          <div className="tiaohou-reading">
            <p>{record.condition}</p>
            <div className="tiaohou-role-list">
              {record.roles.map((role, index) => (
                <div key={`${role.type}-${index}`}>
                  <small>{role.type}</small>
                  <strong>{role.stems.join(' · ')}</strong>
                  <span>{role.purpose}</span>
                </div>
              ))}
            </div>
            <p className="tiaohou-conclusion">{record.reading}</p>
          </div>
        </div>
        <p className="reading-note">样本用来展示原文怎样区分先用、次用、佐用与条件用；月令是起点，显示出的天干不是脱离具体条件的固定答案。</p>
      </div>

      <div className="knowledge-block">
        <div className="interactive-heading"><span>三种常见误读</span><h2>为什么速查表容易丢掉信息？</h2></div>
        <div className="tiaohou-misread-grid">
          <article><b>把所有字放成同一级</b><p>先用、次用、佐用被压成数组后，原本的作用顺序会消失。</p></article>
          <article><b>把条件用当成常用</b><p>只在“水多”“金局”等条件下出现的字，不能脱离条件长期保留。</p></article>
          <article><b>只保留每月两个字</b><p>简表便于速查，却可能删掉原文用来解释转折的关键分支。</p></article>
        </div>
      </div>

    </section>
  )
}

